\begin{remark} \label[remark]{rem:limit-convention}
Here and throughout, any limit of $q$ or $N$ permits the parameters to vary and depend on each other arbitrarily unless explicitly stated otherwise. For example, the limit $q^N \to \infty$ includes the cases $q$ fixed with $N \to \infty$, $N$ fixed with $q \to \infty$, and more. 
\end{remark}

We refer to the subset of polynomials whose prime factors all have degree exceeding an integer $z \geq 1$ as \textit{$z$-rough polynomials}. In other words, polynomials $F$ such that 
\begin{equation} \label{def:min-degree}
P^-(F) := \min\{ \deg P : P \mid F, \, P \text{ monic irreducible} \}
\end{equation}
exceeds $z$. 
 As suggested by Xu \cite{Xu-2022}, one can expect a CLT when summing over sufficiently rough polynomials. As a brief final application of \cref{thm:main-intro}, we confirm this observation in \S\ref{sec:roughpolyCLT}. 
\begin{theorem}\label{thm:CLT-rough}
 Let $q \geq 2$ be a prime power and $N\geq 1$ an integer. Assume $N^{1/2} \leq z \leq N-1$ is an integer satisfying $N^{1/2} = o(z)$ as $N \to \infty$. If $f$ is a Steinhaus random multiplicative function over $\mathbb{F}_q[t]$, then \eqref{eqn:CLT} holds for
 \[
 \mathcal{A} = \{ F \in \mathcal{M}_N : P^-(F) > z \}
 \]
 as $N \to \infty$. 
\end{theorem}

\begin{enumerate}[label=(\roman*)]
 \item $|\mathcal{A} \backslash \mathcal{S}| = o(|\mathcal{A}|)$. \label{thmmain:i}
 \item $|\{ (F_1,F_2,G_1,G_2) \in \mathcal{S}^4 : F_1 F_2=G_1 G_2 , F_1 \neq G_1, F_1 \neq G_2 \}| = o(|\mathcal{A}|^2)$. \label{thmmain:ii}
 \item $|\{F\in \mathcal{S}:\ P^+_\prec(F)=Q\}| = o(|\mathcal{A}|)$ for every monic irreducible $Q$. \label{thmmain:iii}
\end{enumerate}
If $f$ is a Steinhaus random multiplicative function over $\mathbb{F}_q[t]$ then, as $q^N\to\infty$,
\[
Z=\frac{1}{\sqrt{|\mathcal{A}|}}\sum_{F\in \mathcal{A}} f(F)\ \xrightarrow{d}\ \mathcal{CN}(0,1).
\]
\end{theorem}
\begin{remark}\label[remark]{rem:martingale} The advantage of our refined filtration with $P_{\prec}^+(F)$ can be seen from condition (iii). Observe that 
\begin{align*}
\max_{Q \in \mathcal{P}} | \{ F \in \mathcal{M}_N : P^+_{\prec}(F) = Q \} | & \ll q^N \exp\Big( - \tfrac{1}{2} \sqrt{N \log q} \Big), \\
\max_{d \geq 1} | \{ F \in \mathcal{M}_N : P^+(F) = d \} | & \gg q^N /N, 
\end{align*}
upon applying \cref{lem:filtration} with $h=N-1$ for the first bound, and noting $d=N$ corresponds to the total number of monic irreducibles for the second bound. The latter filtration is based purely on the degree $P^+(F)$ and would require us to assume $|\mathcal{A}| \gg q^N/N$ in \cref{thm:main-intro}. Aggarwal--Subedi--Verreault--Zaman--Zheng \cite{FUSRP2020} successfully used this filtration in their case, because their desired application for $\mathcal{A}$ was sufficiently large. However, the constraint $|\mathcal{A}| \gg q^N/N$ is too strict for our intended applications. Our refined filtration with $P^+_{\prec}(F)$ allows us to only require $|\mathcal{A}| \gg q^N \exp(- \tfrac{1}{3}\sqrt{N \log q})$ in \cref{thm:main-intro}, which is notably more flexible. It also more closely mimics Harper \cite{Harper-2013} and his filtration based on $\{ m \in [1,n] \cap \mathbb{Z} : P^+(m) = p\}$ for any prime $p$, where $P^+(m)$ denotes the largest prime factor of $m \in \mathbb{Z}$.
\end{remark}

Fix $\epsilon > 0$ sufficiently small. As in the proof of \cref{prop:short-interval-mult-energy}, we again count off-diagonal solutions to $F_1F_2 = G_1G_2$ for $F_1,F_2,G_1,G_2 \in \mathcal{S}$ with the same GCD parametrization. Write $F_1 = GA, G_1 = GB, F_2 = HB,$ and $G_2 = HA$. Denoting $d = \deg G = \deg H$, it follows by \cref{prop:short-interval-mult-energy} and its proof that $N-h \leq d \leq h$, and we may assume $h \geq N/2$ without loss. Set $m=(1+ \epsilon)\log N$ so that $\Omega(GABH)\leq 2m$. This yields the following estimate for the off-diagonal solutions:
\begin{align}
 \mathsf{E}_\times(\mathcal{S}) - 2|\mathcal{S}|^2 + |\mathcal{S}|
 &\ll \sum_{d=N-h}^{h} \, \ssum_{\substack{G, H \in \mathcal{M}_d}} \, \ssum_{\substack{A, B \in \mathcal{M}_{N-d}\\ GA, HB, GB, HA\in \mathcal{I}(K,h)}}2^{2m-\Omega(GABH)} \nonumber\\
 &=2^{2m}\sum_{d=N-h}^{h} \sum_{\substack{G\in\mathcal{M}_d}}2^{-\Omega(G)}\ssum_{\substack{A,B\in \mathcal{I}(K,h)/G \\ A,B \in \mathcal{M}_{N-d}}}2^{-\Omega(A)-\Omega(B)}\sum_{\substack{ H\in \mathcal{I}(K,h)/A \\ H \in \mathcal{M}_d}}2^{-\Omega(H)}. \label{eqn:short-intervals-off-diag}
\end{align} 
As described at the end of \S\ref{sec:intervals}, for each $A \in \mathcal{M}_{N-d}$, the interval quotient $\mathcal{I}(K,h)/A$ is \textit{equal} to the interval $\mathcal{I}(\widetilde{K},h+d-N)$ for some $\widetilde{K}$ (depending on $A$) of degree $d = N - (N-d)$ because $h+d-N \geq 0$ in our sum. Thus, by \cref{thm:shiu} with $g(H) = 2^{-\Omega(H)}$, it follows that 
 \[
 \sum_{\substack{ H\in \mathcal{I}(K,h)/A \\ H \in \mathcal{M}_d}}2^{-\Omega(H)} = \sum_{\substack{ H\in \mathcal{I}(\widetilde{K},h+d-N) }}2^{-\Omega(H)} \ll \frac{q^{h+d-N+1}}{d} \exp\Big( \sum_{P \in \mathcal{P}_{\leq d} } \frac{1}{2q^{\deg(P)}} \Big) \ll \frac{q^{h+d-N+1}}{d^{1/2}} 
 \]
 for each $A \in \mathcal{M}_{N-d}$, since by the prime number theorem $\sum_{P \in \mathcal{P}_{\leq d} } q^{-\deg(P)} = \log d +O(1)$. By \eqref{eqn:short-intervals-off-diag}, this implies that 
 \[
\mathsf{E}_\times(\mathcal{S}) - 2|\mathcal{S}|^2 + |\mathcal{S}| \ll 2^{2m}\sum_{d=N-h}^{h} \frac{q^{h+d-N+1}}{d^{1/2}} \sum_{\substack{G\in\mathcal{M}_d}}2^{-\Omega(G)}\Big( \sum_{\substack{A\in \mathcal{I}(K,h)/G \\ A \in \mathcal{M}_{N-d}}}2^{-\Omega(A)} \Big)^2
 \]
 since the sums over $A$ and $B$ are identical. For the sum over $A$, the same argument with \cref{thm:shiu} applies. Indeed, for each $G \in \mathcal{M}_d$, the interval quotient $\mathcal{I}(K,h)/G$ is \textit{equal} to the interval $\mathcal{I}(\widetilde{K}',h-d)$ for some $\widetilde{K}'$ (depending on $G$) of degree $N-d$ because $h-d \geq 0$ in our sum. Thus, by \cref{thm:shiu} with $g(A) = 2^{-\Omega(A)}$, we similarly have that
 \[
 \sum_{\substack{A\in \mathcal{I}(K,h)/G \\ A \in \mathcal{M}_{N-d}}}2^{-\Omega(A)} 
 =
 \sum_{\substack{A\in \mathcal{I}(\widetilde{K}',h-d)}}2^{-\Omega(A)} \ll \frac{q^{h-d+1}}{N-d} \exp\Big( \sum_{P \in \mathcal{P}_{\leq N-d} } \frac{1}{2 q^{\deg(P)}} \Big) \ll \frac{q^{h-d+1}}{(N-d)^{1/2}}. 
 \]
Inserting this into the previous equation, we deduce that 
 \[
 \mathsf{E}_\times(\mathcal{S}) - 2|\mathcal{S}|^2 + |\mathcal{S}| \ll 2^{2m}\sum_{d=N-h}^{h} \frac{q^{3h-N-d+3}}{d^{1/2} (N-d)} \sum_{\substack{G\in\mathcal{M}_d}}2^{-\Omega(G)}. 
 \]
Upon noting $\mathcal{I}(G,d-1) = \mathcal{M}_d$, we again apply \cref{thm:shiu} on the sum over $G$ to see that
\[
\sum_{\substack{G\in\mathcal{M}_d}}2^{-\Omega(G)} \ll \frac{q^{d+1}}{d^{1/2}}
\]
for each $N-h \leq d \leq h$. Therefore, we may conclude that 
\[
 \mathsf{E}_\times(\mathcal{S}) - 2|\mathcal{S}|^2 + |\mathcal{S}| \ll 2^{2m} q^{3h+3-N}\sum_{d=N-h}^h \frac{1}{d(N-d)} \ll 2^{2m} q^{3h+3-N} \frac{\log N}{N} 
\]
since $N-d \geq h \geq N/2$ and $\sum_{d=N-h}^h \frac{1}{d} \leq \sum_{d=1}^N \frac{1}{d} \ll \log N$. Using our choice $m = (1+\epsilon) N$ and noting $|\mathcal{S}| \asymp |\mathcal{I}(K,h)| = q^{h+1}$ by \cref{lem:short-interval-hardy-ramanujan}, we have overall that 
\[
2|\mathcal{S}|^2 - |\mathcal{S}| \leq \mathsf{E}_\times(\mathcal{S}) \leq 2|\mathcal{S}|^2 - |\mathcal{S}| + O\Big( |\mathcal{S}|^2 q^{h+1-N} N^{2\log 2 (1+\epsilon) - 1} \log N \Big). 
\]
The error term is $o(|\mathcal{S}|^2)$ provided $q^{h+1} = o(q^N / N^{2\log 2-1+2\epsilon} )$. Our assumption states $q^{h+1} = o(q^N/N^c)$ as $h \to \infty$ for some fixed $c > 2\log 2-1$. By fixing $\epsilon = \epsilon(c) > 0$ sufficiently small, we deduce that $\mathsf{E}_\times(\mathcal{S}) = 2 |\mathcal{S}|^2(1+o(1))$ as $h \to \infty$. This verifies (ii) and establishes case (b). 
\end{proof}

post_theorem_intro_text:
\begin{remark} \label[remark]{rem:limit-convention}
Here and throughout, any limit of $q$ or $N$ permits the parameters  to vary and depend on each other arbitrarily unless explicitly stated otherwise.  For example, the limit $q^N \to \infty$ includes the cases $q$ fixed with $N \to \infty$, $N$ fixed with $q \to \infty$, and more. 
\end{remark}

As remarked in \cite{SoundXu-2023}, the size constraints on $|\mathcal{A}|$ and $|\mathcal{S}|$ are mild, but \eqref{main-mult-energy} is  pivotal. This condition  concerns the \textit{multiplicative energy} $\mathsf{E}_{\times}(\mathcal{S})$ of a finite set $\mathcal{S} \subseteq \mathcal{M}$, defined by
\begin{equation} \label{eqn:mult-energy}
    \mathsf{E}_{\times}(\mathcal{S}) := |\{(F_1,F_2,G_1,G_2)\in \mathcal{S}^4:F_1F_2=G_1G_2\}| = \mathbb{E} \Big| \sum_{F \in \mathcal{S} } f(F) \Big|^4.
\end{equation}
We say a family of sets $\mathcal{S}$ have \textit{asymptotically trivial multiplicative energy} when
\begin{equation}\label{trivialenergy}
\mathsf{E}_{\times}(\mathcal{S}) =(2+o(1))|\mathcal{S}|^2 \quad \text{ as } |\mathcal{S}| \to \infty.
\end{equation}
The trivial (or diagonal) solutions $(F_1, F_2, F_1, F_2)$ and $(F_1, F_2, F_2, F_1)$ for \eqref{eqn:mult-energy} always exist, so it is immediate that $\mathsf{E}_{\times}(\mathcal{S}) \geqslant 2|\mathcal{S}|^2 - |\mathcal{S}|$. Statement \eqref{trivialenergy} therefore requires that the multiplicative energy is dominated by the trivial solutions in the limit. 

The proof of \cref{thm:main-intro} largely follows Soundararajan--Xu by invoking a central limit theorem for martingale difference sequences due to McLeish (\cref{thm:mcleishclt}). This approach was utilized in \cite{FUSRP2020} for function fields but they applied a coarse filtration depending only on
\begin{equation} \label{def:max-degree}
P^+(F) := \max\{ \deg P : P \mid F, P \text{ monic irreducible } \},
\end{equation}
the maximum degree of any monic irreducible dividing $F \in \mathcal{M}$. We require a more refined filtration for each individual prime $P$, necessitating a new estimate for smooth polynomials in short intervals (\cref{lem:filtration}) in addition to a related estimate of Gorodetsky \cite{OfirSmoothPolys23}; see \cref{rem:martingale} for details. 

From \cref{thm:main-intro}, we deduce  four central limit theorems: 
\begin{itemize}
	\item (\cref{thm:CLT-intervals})  CLT for short intervals 	
	\item (\cref{thm:CLT-kprimes}) CLT for restricted number of prime factors 
	\item (\cref{thm:CLT-shiftedprimes}) CLT for shifted primes 
	\item (\cref{thm:CLT-rough}) CLT for rough polynomials 
\end{itemize}
Each application requires a variety of function field number theoretic lemmas, many of which we could not find in the literature with sufficient uniformity. We established several new results which we expect to be of independent interest: a uniform Hildebrand bound for smooth polynomials in short intervals (\cref{prop:intervalshift}), a uniform Shiu's theorem for multiplicative functions (\cref{thm:shiu}), and a uniform Chebyshev bound for rough polynomials in short intervals (\cref{lem:chebyshev}). See  \S\ref{sec:CLTs} for details on these four central limit theorems and number theoretic lemmas.  

\subsection*{Organization} \cref{sec:CLTs} describes the CLT applications deduced from \cref{thm:main-intro}  and other number theoretic results over $\mathbb{F}_q[t]$. \cref{sec:prelim} collects our notation and basic terminology regarding function field intervals, and then presents a  simplified version of the Selberg sieve for function fields. \cref{sec:smoothroughpolys} develops novel bounds on the numbers of smooth and rough polynomials in an interval (\cref{prop:intervalshift,lem:chebyshev}). \cref{sec:clts} establishes \cref{thm:main-intro} by applying these lemmas. 

The remaining subsections are dedicated to deducing the four central limit theorems described in \cref{sec:CLTs}.   \cref{sec:shiu} prepares a function field analogue of Shiu's theorem (\cref{thm:shiu}), so that \cref{sec:interval-CLT} can establish the short interval CLT (\cref{thm:CLT-intervals}). \cref{sec:almostprimesCLT,sec:shiftedprimesCLT} respectively establish the few prime factors CLT (\cref{thm:CLT-kprimes}) and shifted prime CLT (\cref{thm:CLT-shiftedprimes}). Finally, \cref{sec:roughpolyCLT} presents a short proof of the rough polynomial CLT (\cref{thm:CLT-rough}).

\subsection*{Acknowledgments} The authors thank Lior Bary-Soroker, Ofir Gorodetsky, Dimitris Koukoulopoulos, and Max Xu for helpful discussions and references. This research was conducted as part of the 2024 Fields Undergraduate Summer Research Program, and the authors are deeply grateful for the Fields Institute's support. AZ was partially supported by NSERC grant RGPIN-2022-04982.

