\section{Proof of Proposition \ref{prop 1.3}}\label{tech-section}
The rest of the paper is devoted to proving Proposition \ref{prop 1.3}. We begin in Section \ref{Tech-esti} by establishing the required technical estimates. The main steps of the proof of the lower and upper bounds are then presented in Sections \ref{se:3} and \ref{se:4}, respectively.

\subsection{Technical Estimates}\label{Tech-esti}
Let $(G_n)$ be a SRW start at $G_1=1$, conditioned on never hit $0$.
That is, $(G_n)$ is an $h-$process.  In other words, starting from $G_1=1$ and with respect to its natural filtration $\mathcal{F}^{G}_{n}$, its transition probabilities are explicitly given as follows:
\begin{align*}
    &\p\left(G_{n+1}=G_n+1\mid \mathcal{F}^{G}_{n}\right)=\frac{G_n+1}{2G_n},\\
    &\p\left(G_{n+1}=G_n-1\mid \mathcal{F}^{G}_{n}\right)=\frac{G_n-1}{2G_n}.
\end{align*}
Define $\tau^G_s:=\inf\{n:G_n=s\}$ is the stopping time when  $(G_n)$ hits $x$ for the first time. Define
\begin{equation*}
    \mathcal{G}_s:=\left\{ y : \exists \ k\in[1, \tau^G_s] \text{ such that } G_k = y, \text{ and } G_l \neq y \text{ for } 1 \leq l \leq \tau^G_s,\ l \neq k \right\}
\end{equation*}
which is the once visited set at time $\tau^G_s$. Let $g(s)=\#\mathcal{G}_s$.
\begin{proposition}\label{prop1.5}
For any $\epsilon>0$, $0<c_1<c_2$, there exists $N=N(\epsilon,c_1,c_2)>0$ such that for any $s\geq N$, $C\in [c_1,c_2]$, we have
    \begin{equation*}
       \exp\left({-(2+\epsilon)C\log s}\right)\leq \p\left(g(s)\geq C\log^2 s\right)\leq \exp\left({-(2-\epsilon)C\log s}\right).
    \end{equation*}
\end{proposition}
By adapting ideas from \cite[Theorem 2]{Ma88}, Proposition \ref{prop1.5} can be proved by verifying the following two lemmas. We remark that the first lemma is similar to \cite[Lemma 4]{Ma88}.
\begin{lemma}\label{lem1.6}
For any $0<\epsilon<1$, $0<c_1<c_2$, there exists $N=N(\epsilon,c_1,c_2)>0$ such that for any $n\geq N$, $k\in [c_1\log s,c_2\log s]$, we have
\begin{equation*}
    \left(\frac{(1-\epsilon)\log s}{2}\right)^k\leq \e \left[\binom{g(s)}{k}\right]\leq \left(\frac{(1+\epsilon)\log s}{2}\right)^k.
\end{equation*}
\end{lemma}

\begin{lemma}\label{lem1.7}
    If a sequence of random variables $X_s\in \N$ satisfy that for any $0<\epsilon<1$, $0<c_1<c_2$, there exists $N=N(\epsilon,c_1,c_2)>0$ such that for any $n\geq N$, $k\in [c_1\log s,c_2\log s]$,
\begin{equation*}
    \left(\frac{(1-\epsilon)\log s}{2}\right)^k\leq \e \left[\binom{X_s}{k}\right]\leq \left(\frac{(1+\epsilon)\log s}{2}\right)^k,
\end{equation*}
then for any constants $\epsilon>0$, $0<c_1<c_2$, there exists $N=N(\epsilon,c_1,c_2)>0$ such that for any $n\geq N$, $C\in [c_1,c_2]$, it holds that
    \begin{equation*}
       \exp\left(-(2+\epsilon)C\log s\right)\leq \p\left(X_s\geq C\log^2 s\right)\leq \exp\left(-(2-\epsilon)C\log s\right).
    \end{equation*}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lem1.6}]
    For any set $A=\{x_1,x_2,\dots ,x_k\}\subset \{1,2,\dots ,s-1\}$, suppose $x_1<x_2<\dots<x_k$ and $k\le s-1$.
    Then $A\subset \mathcal{G}_s$ if and only if $G_{n_1}>x_i$ for any $1\leq i\leq k-1$ and $\tau^G_{x_i}+1\leq {n_1}\leq \tau^G_{x_{i+1}}$, and $G_{n_2}>x_k$ for any $\tau^G_{x_k}+1\leq n_2\leq \tau^G_{s}$.
    Similar to our previous techniques \cite[(4.7)]{FH25}, we see that $(\frac{1}{G_n})_{n\ge1}$ is martingale. By applying the Optional Stopping theorem at $\tau^G_{a}\wedge\tau^G_{b}$, with the initial state $\frac{1}{G_1}=\frac{1}{a+1}$. One has,
    \begin{equation}\label{mart-anal}
        \p\left(G_n>a,\ \mbox{ for any } \tau^G_{a}+1\leq n\leq \tau^G_{b}\,\Big|\, \mathcal{F}^{G}_{\tau^G_{a}}\right)=\frac{b}{2a(b-a)}.
    \end{equation}

