ref_dict.thm:Effective:
\begin{thmx} [Effective equidistribution of maximal compact subgroup orbits] \label{thm:Effective}
Suppose the action of $G$ on $\Omega = G/\G$ has a spectral gap. Let $A = \{a(y) : y \in \R_+^{\times} \}$ be an $\Ad$-diagonalizable one-parameter subgroup of $G$ such that $a(e)$ projects non-trivially to each simple factor of $G$. Then there exist a constant $c > 0$ and an integer $r \geq 1$ such that for every compact subset $Q \subset \Omega$, for all $f \in C^{\infty}(K)$, $\phi \in C_c^\infty(\Omega)$, $x \in Q$, and $y \geq 1$, we have
\begin{equation} \label{eq:Single-Eq}
\int_K f(k) \phi \bigl(a(y) k x \bigr) \dd \mu_K(k) = \int_K f \dd \mu_K \int_{\Omega} \phi \dd \mu_{\Omega} + O \big ( y^{-c} \cS_r(f) \cS_r(\phi) \big ),
\end{equation}
and, for all $f \in C^{\infty}(K)$, $\phi_1, \phi_2 \in C_c^\infty(\Omega)$, $x_1, x_2 \in Q$, 
and $y_2 \geq y_1 \geq 1$, we have
\begin{multline} \label{eq:Double-Eq}
\int_K f(k) \phi_{1}\bigl(a(y_1) k x_1 \bigr) \phi_{2} \bigl(a(y_2) k x_2 \bigr) d \mu_K(k) =  \int_K f \dd \mu_K \int_{\Omega} \phi_1 \dd \mu_{\Omega}  \int_{\Omega} \phi_2 \dd \mu_{\Omega} \\ + O \big ( \min \{y_1, y_2/y_1 \}^{-c} \cS_r(f) \cS_r(\phi_1) \cS_r(\phi_2) \big ),
\end{multline} 
where the implicit constant in $O(\cdot)$ depends only on $Q$.
\end{thmx}

ref_dict.thm:L1:
\begin{thmx} [$L^1$-integrability] \label{thm:L1} 
The following assertions are equivalent.
\begin{enumerate}[label=(\arabic*)]
\item The Siegel transform $S_\chi$ maps $B_c^{\infty}(\widetilde{X})$ into $L^1(\Omega)$.
\item There exists a unique (up to scaling) $G$-invariant Radon measure $\lambda_{\widetilde{X}}$ on $\widetilde{X}$, the Siegel transform $S_\chi$ extends to a bounded operator $S_{\chi} : L^1(\widetilde{X}) \rightarrow L^1(\Omega)$, and $\lambda_{\widetilde{X}}$ can be normalized so that we have a convergent mean value formula:
\begin{equation} \label{eq:WeilIntegrationFormula*}
\forall \, f \in L^1(\widetilde{X}), \quad \int_{\Omega} S_\chi f \, \dd \mu_{\Omega} = \int_{\widetilde{X}} f \, \dd \lambda_{\widetilde{X}}.
\end{equation}
\item The Lie group $L = \bL(\R)$ is unimodular and $\G_L = \G \cap L$ is a lattice in $L$.
\item The parabolic $\Q$-subgroup $\bP$ of $\bG$ is maximal.
\item There exists $\varepsilon > 0$ such that $S_\chi$ maps $B_{c}^{\infty}(\widetilde{X})$ into $L^{1+\varepsilon}(\Omega)$.
\end{enumerate}
\end{thmx}

