\begin{theorem}
		\label{thm:main-threshold}
		Let $\pi\colon \X\to Y$ be the coarse moduli map of a compact complex orbifold of complex dimension~$n$, and let $A$ be an ample line bundle on~$Y$ with Kähler form~$\omega_A$.
		Assume the curvature hypotheses \textup{(H1)}–\textup{(H4)} of \Cref{assump:curv}.
		Then$\colon $
		\begin{enumerate}[label=(\roman*), leftmargin=1.6em]
			\item The Green--Griffiths--Demailly hyperbolicity threshold depends only on the coarse Kähler class $[\omega_A]$ and not on the presence of orbifold or stack structure.
			\item Equivalently,
			\[
			\text{$Y$ is GGD--positive at some jet order $k_0$}
			\quad\Longleftrightarrow\quad
			\text{$\X$ is GGD--positive at the same order.}
			\]
			\item The minimal jet order and asymptotic growth rate of $h^0(E^{\mathrm{GG}}_{k,m}\otimes L^{-q})$ remain unchanged under coarse projection, finite quotient, or rigidification.
		\end{enumerate}
	\end{theorem}

