[cf. Theorem 2 in \cite{Maa96}]\label{thm:maa}
Let $X_1, X_2, X_3$  be i.i.d. random vectors with values in $\mathbb{R}^k$ and Lebesgue probability density $f_X$, let $Y_1, Y_2, Y_3$ be i.i.d. random vectors with values in $\mathbb{R}^k$ and  Lebesgue probability density $f_Y$ and let $X_1, X_2,X_3$ and $Y_1, Y_2, Y_3$ be independent. Let $d:\mathbb{R}^k\times \mathbb{R}^k\longrightarrow \mathbb{R}$ be a nonnegative, continuous function with
\begin{enumerate}
    \item[\textbf{(D1)}] $d(x,y)= 0$ if, and only if,  $x=y$,
    \item[\textbf{(D2)}] for all $a \in \mathbb{R}$ and $x,y,b \in \mathbb{R}^k$ $d(ax+b, ay+b) = |a|d(x,y)$.
\end{enumerate} 
\noindent
Moreover, assume that
\begin{enumerate}[start=1,label={(\bfseries R\arabic*):}]
    \item[\textbf{(R1)}]  $\int_{\mathbb{R}^k}f^2_X(x) dx, \int_{\mathbb{R}^k}f^2_Y(y)dy<\infty$,
     \item[\textbf{(R2)}]  the zero vector is a Lebesgue point of the function $u(y)= \int f_Y(x+y) f_X(x) dx$, i.e. it holds that $\frac{1}{\lambda(B_r(0))} \int_{B_r(0)} |u(y) - u(0)| d y \underset{r \rightarrow 0}{\rightarrow} 0$, where $B_r(x)$ denotes the ball in $\mathbb{R}^k$ with radius $r$ around $x$ with respect to  the distance function $d$.
\end{enumerate}
\noindent
Then, it holds that
\begin{equation*}
    f_X = f_Y \textit{\quad if, and only if,  \quad } d(X_1, X_2) \overset{\mathcal{D}}{=} d(Y_1, Y_2) \overset{\mathcal{D}}{=}d(X_3, Y_3).
\end{equation*}

ref_dict.bsp::Canberra:
\begin{bsp} (Canberra distance) \label{bsp::Canberra}\\ 

\noindent
Let us consider the Canberra distance of $x=(x_1, \ldots, x_k)^{\top}$ and $y=(y_1, \ldots, y_k)^{\top}$ in $\R^k$ defined by
\begin{equation}\label{eqn::Canberra_k}
h(x, y) := \sum_{i=1}^k
\begin{cases}
\frac{|x_i - y_i|}{|x_i| + |y_i|}, & \text{if } |x_i| + |y_i| \neq 0, \\
0, & \text{if } x_i = y_i = 0.
\end{cases}
\end{equation}
\noindent
\textbf{Case $k = 1$:} \\
In this case, $h(x,y) = \frac{\lvert x - y \rvert}{\lvert x\rvert +  \lvert y\rvert}$. Consider for $x > 0$ and $t \in (0,1)$ the cases $y \geq x$ and $y  < x$ separately. 
For $y \geq x$ and   $h(x,y)  < t$, we have
\begin{equation*}
    \frac{y - x}{x + y}  < t, \ \text{or, equivalently,} \  \   y  < \frac{x(t + 1)}{1 - t}.
\end{equation*}
For  $y  < x$ and   $h(x,y)  < t$, we have
\begin{equation*}
     \frac{x-y}{x + y}  < t, \ \text{or, equivalently,} \  \   y > \frac{x(1-t)}{1+t}.
\end{equation*}
It follows that
\begin{equation} \label{eqn::Canberra_1D_cube}
    B_t(x)= \left(x\frac{1-t}{1+t} , x\frac{1+t}{1-t} \right)
\end{equation}
and therefore $\mu(B_t(x)) = \frac{4tx}{1-t^2}$. Due to symmetry, for $x < 0$ we have $\mu(B_t(x)) = -\frac{4tx}{1-t^2}$ and we conclude
\begin{equation} \label{eqn::Phi_1D}
    \Phi(x, t) = \frac{4t \lvert x \rvert}{1-t^2} \textnormal{ \quad \quad for } t \in (0,1) \textnormal{ and } x \neq 0.
\end{equation}
Moreover, it holds that  
\begin{equation*}
    B_t(0) = 
\begin{cases}
\{ 0\} & t < 1 , \\
\R & t \geq 1,
\end{cases}
\end{equation*}
and therefore 
\begin{equation*}
     \Phi(0,t) = 
\begin{cases}
0 & t < 1 , \\
\infty & t \geq 1.
\end{cases} 
\end{equation*}

\noindent
\textbf{Case $k > 1$:} \\
We firstly provide an upper and lower bounds on the volume of $B_t^{(h)}(x)$ for the case $x_i \neq 0$ for all $i \in \{1,...,k\}$. For the upper bound, we consider the rectangle in $\R^k$ with sides corresponding to  \eqref{eqn::Canberra_1D_cube}. Since $y_i \notin \left(x_i\frac{1-t}{1+t} , x_i\frac{1+t}{1-t} \right) $ implies $h(x,y) \geq t$, we have
\begin{equation*}
    B_t(x) \subseteq \prod\limits_{i=1}^k \left(x_i\frac{1-t}{1+t} , x_i\frac{1+t}{1-t} \right).
\end{equation*}
It follows that 
\begin{equation} \label{eqn::Canberra_upper}
    \Phi(x,t) \leq \left(\frac{4t}{1-t^2} \right)^k \prod\limits_{i=1}^k \lvert x_i \rvert \textnormal{ \quad \quad for } t \in (0,1) \textnormal{ and } x_i \neq 0.
\end{equation}
For the lower bound consider the rectangle with sides 
\begin{equation*}
   I_i = \left(x_i\frac{1-t/k}{1+t/k} , x_i\frac{1+t/k}{1-t/k} \right).
\end{equation*}
Since $y_i \in I_i$ for all $i \in \{1,...,k\}$ implies $y \in B_t(x)$, we conclude that
\begin{equation*}
     \prod\limits_{i=1}^k \left(x_i\frac{1-t/k}{1+t/k} , x_i\frac{1+t/k}{1-t/k} \right) \subseteq B_t(x)
\end{equation*}
and therefore
\begin{equation}\label{eqn::Canberra_lower}
    \left(\frac{4t/k}{1-(t/k)^2} \right)^k \prod\limits_{i=1}^k \lvert x_i \rvert \leq \Phi(x,t) \textnormal{ \quad \quad for } t \in (0,1) \textnormal{ and } x_i \neq 0.
\end{equation}
If for any $i \in \{1,...,k\}$ $x_i = 0$, then in that dimension the set of permissible $y_i$ is empty, and therefore $\Phi(0,t) = 0$ for $t \in (0,1)$. The set $\{x=(x_1, \ldots, x_k)^{\top} \mid x_i = 0 \ \text{for at least one $i \in \{1, \ldots, k\}$}\}$ has, however, Lebesgue measure $0$ in $\R^k$.
Accordingly,  for a.e. $x$
\begin{equation*}
    \Phi(x,t) \sim C(x) \left( \frac{t}{1-t^2} \right)^k,
\end{equation*}
where $0<C(x)\sim \prod_{i=1}^k \lvert x_i \rvert$. More precisely, with \eqref{eqn::Canberra_upper} and \eqref{eqn::Canberra_lower} it follows that $\delta_t(x,y) \leq C \delta(x,y)$ with $\delta(x,y) = \prod_{i= 1}^k \left|\frac{x_i}{y_i}\right|$ for some $C>0$. We conclude that the conditions \eqref{eqn::Phi_limit}, \eqref{eqn::Phi_positive} and \eqref{eqn::Phi_uniform} in the definition of volume-regular functions, i.e. Definition \ref{def:volume_reg},  are fulfilled.  Theorem \ref{thm::Main} then applies if its conditions on the densities $f$ and $g$ are fulfilled.\\

\noindent
As a concrete example, consider the density function $f$ of the standard normal distribution, i.e. $f(x) = \frac{1}{\sqrt{2 \pi}} e^{-\lVert x \rVert^2 /2}$, which is smooth on $\R^k$. Then, the Lebesgue differentiability condition is fulfilled since
\begin{align*}
      \frac{1}{\Phi(x,t)} \int_{B_t(x) } \lvert f(x) - f(y)\rvert d y &\leq \frac{1}{\Phi(x,t)} \sup_{y \in B_t(x)}\lvert f(x) - f(y)\rvert \Phi(x,t) \\
      &= \sup_{y \in B_t(x)}\lvert f(x) - f(y)\rvert \rightarrow 0
\end{align*}
for almost every $x \in \R^k$ and $t \rightarrow 0^{+}$. According to \eqref{eqn::Canberra_upper}, it further holds that
\begin{equation*}
    f^2(x)\Phi(x,t) \leq \frac{1}{2\pi}\left(\frac{4t}{1-t^2} \right)^k \prod\limits_{i=1}^k \lvert x_i \rvert  e^{-\lVert x \rVert^2 }
\end{equation*}
with the right-hand side of the above inequality being  integrable on $\R^k$. We conclude that $f \delta(\cdot,y), f^2 \delta(\cdot,y) \in L^1(\R^k)$ for any $t \in (0,1)$ and the integrability condition is fulfilled. In other words: Theorem \ref{thm::Main} holds for  normally distributed data and the Canberra distance. 
\end{bsp}

ref_dict.thm:maa:
\begin{Theorem}[cf. Theorem 2 in \cite{Maa96}]\label{thm:maa}
Let $X_1, X_2, X_3$  be i.i.d. random vectors with values in $\mathbb{R}^k$ and Lebesgue probability density $f_X$, let $Y_1, Y_2, Y_3$ be i.i.d. random vectors with values in $\mathbb{R}^k$ and  Lebesgue probability density $f_Y$ and let $X_1, X_2,X_3$ and $Y_1, Y_2, Y_3$ be independent. Let $d:\mathbb{R}^k\times \mathbb{R}^k\longrightarrow \mathbb{R}$ be a nonnegative, continuous function with
\begin{enumerate}
    \item[\textbf{(D1)}] $d(x,y)= 0$ if, and only if,  $x=y$,
    \item[\textbf{(D2)}] for all $a \in \R$ and $x,y,b \in \R^k$ $d(ax+b, ay+b) = |a|d(x,y)$.
\end{enumerate} 
\noindent
Moreover, assume that
\begin{enumerate}[start=1,label={(\bfseries R\arabic*):}]
    \item[\textbf{(R1)}]  $\int_{\mathbb{R}^k}f^2_X(x) dx, \int_{\mathbb{R}^k}f^2_Y(y)dy<\infty$,
     \item[\textbf{(R2)}]  the zero vector is a Lebesgue point of the function $u(y)= \int f_Y(x+y) f_X(x) dx$, i.e. it holds that $\frac{1}{\lambda(B_r(0))} \int_{B_r(0)} |u(y) - u(0)| d y \underset{r \rightarrow 0}{\rightarrow} 0$, where $B_r(x)$ denotes the ball in $\mathbb{R}^k$ with radius $r$ around $x$ with respect to  the distance function $d$.
\end{enumerate}
\noindent
Then, it holds that
\begin{equation*}
    f_X = f_Y \textit{\quad if, and only if,  \quad } d(X_1, X_2) \overset{\mathcal{D}}{=} d(Y_1, Y_2) \overset{\mathcal{D}}{=}d(X_3, Y_3).
\end{equation*}
\end{Theorem}

