\item $\det(\SF)\,\cong\, \pi_X^* \xi$, where $\pi_X\,:\,X\times Q\,\longrightarrow\, X$ is the natural projection, and

\item $\SE\ \cong\ (\id_X\times \tau)^*\SF$.
\end{itemize}
\end{lemma}

