The main result of this article is that the ERW in $\C$ exhibits a superdiffusive behaviour if $\Re(\Phi_1)>1/2$, while it remains diffusive when $\Re(\Phi_1)<1/2$. In addition, we show that when superdiffusive, the path of the ERW scales towards a randomly rotated logarithmic spiral.

In order to provide variety to this article, we propose to prove Theorem~\ref{thm:main} in two different ways. We study the regime $\Re(\Phi_1) \leq 1/2$ in Section~\ref{sec:diffusive} using Lindeberg's central limit theorem. The key observation in this section is that
\begin{equation}
 \label{eqn:defMartingale}
 \left( \frac{S_n}{\prod_{j=1}^n \left( 1 + \frac{\Phi_1}{j} \right)}, n\geq 1 \right) \text{ is a martingale,}
\end{equation}
its asymptotic behaviour can be deduced from studying its quadratic variation. Up to the difficulty of dealing with a complex martingale, the argument there follows closely standard methods in dimension 1 or $d$ \cite{BaB,BercuLaulin2019}.

In this model, remark that $\Phi_1= p - r + i (q-s)$, therefore Theorem~\ref{thm:main} implies the following behaviour for $(S_n, n \geq 1)$, depending on the sign of $p-r-1/2$.
\begin{corollary}
Let $(S_n, n \geq 1) $ be the ERW in $\Z^2$ with parameters $p,q,r,s$ defined above.
\begin{itemize}
 \item If $p < r+1/2$, then $\lim_{n \to \infty} \frac{S_n}{n^{1/2}} = \mathcal{N}(0, \frac{1}{2 - 4 (p-r)} I_2)$ in law.
 \item If $p=r+1/2$, then $\lim_{n \to \infty} \frac{S_n}{(n\log )^{1/2}}= \mathcal{N}(0, \frac{1}{2} I_2)$ in law.
 \item If $p > r+1/2$, then there exists a random vector $W \in \R^2$ such that
 \begin{multline*}
 \lim_{n \to \infty} \frac{\mathcal{R}_{-(q-s)\log n}S_n}{n^{p-r}} = W \quad \text{a.s.} \\ \text{and}\quad \lim_{n \to \infty} \frac{S_n - n^{p-r} \mathcal{R}_{(q-s)\log n}W}{n^{1/2}} = \mathcal{N}(0,\frac{1}{4(p-r)-2}I_2) \quad \text{ in law},
 \end{multline*}
 writing $\mathcal{R}_\theta$ for a rotation of angle $\theta$.
\end{itemize}
\end{corollary}

We denote by $(S_n, n \geq 1)$ an ERW defined by \eqref{eqn:defERWC}, and we assume in this section that
\begin{equation}
 \label{eqn:cdSub}
 \Re(\Phi_1) = \Re\left(\E\left( \erm^{i\theta_1} \right)\right) < \frac{1}{2}.
\end{equation}
We prove in this section that
\[
 \lim_{n \to \infty} \frac{S_n}{n^{1/2}} = \mathcal{N}_\C\left(0,\frac{1}{1- 2 \Re(\Phi_1)}\right) \quad \text{ in distribution.}
\]
The proof of \eqref{eqn:mainCrit} follows a similar path with minor modifications, and will be sketched at the end of the section. Let us mention that \eqref{eqn:mainSup} also could have be obtained using the same techniques as developed here.

We denote by $\Gamma$ Euler's Gamma function defined on $\C \backslash \Z_-$, and observe that we can rewrite
\begin{align*}
 a^{(k)}_n &= \prod_{j=1}^{n-1} \left( 1 + \frac{\Phi_k}{j} \right) = \prod_{j=1}^{n-1}\frac{j+\Phi_k}{j} \frac{\Gamma(j+\Phi_k)}{\Gamma(j)} \frac{\Gamma(j)}{\Gamma(j+\Phi_k)}\\
 &= \prod_{j=1}^{n-1} \frac{\Gamma(j + \Phi_k+ 1)}{\Gamma(j+\Phi_k)} \frac{\Gamma(j)}{\Gamma(j + 1)} = \frac{\Gamma(n+\Phi_k)}{\Gamma(n)\Gamma(\Phi_k)},
\end{align*}
from which we deduce there exists $c_k > 0$ such that
\begin{equation}
 \label{eqn:data}
 a_n^{(k)} \sim C_k n^{\Phi_k}, \text{ and } |a_n^{(k)}|^2 \sim |C_k|^2 n^{2 \Re(\Phi_k)} \text{ as $n \to \infty$.}
\end{equation}
Using that $\Re(\Phi_k) \in (-1,1)$ due to \eqref{eqn:Nunidimensional} we conclude that
\[
 \sum_{j=1}^n \frac{1}{|a_j^{(k)}|^2} \begin{cases}
 = O(1) & \text{ if } \Re(\Phi_k)>1/2\\
 \sim |C_k|^2 \log n & \text{ if } \Re(\Phi_k) = 1/2\\
 \sim \frac{|C_k|^2}{1 - 2 \Re(\Phi_k)} n^{1 - 2 \Re(\Phi_k)} &\text{ if } \Re(\Phi_k) < 1/2
 \end{cases}
 \quad \text{ as $n \to \infty$.}
\]
Solving the recursion for $u$ in all three cases, we conclude the proof.
\end{proof}

\begin{proof}
Let $n \geq 1$, we observe that
\begin{align*}
 \Delta M_k &= M_{k+1} - M_k = \frac{S_n + \Delta S_n}{a_{n+1}} - \frac{S_n}{a_n} = \frac{1}{a_{n+1}}\left( S_n + \Delta S_n - \left(1+ \frac{\Phi_1}{n}\right) S_n \right)\\
 &= \frac{1}{a_{n+1}} \left( \Delta S_n - \frac{\Phi_1}{n}S_n \right).
\end{align*}
Therefore,
\begin{align*}
 \E\left( |\Delta M_k|^2 \middle| \mathcal{F}_k \right)
 &= \frac{1}{|a_{k+1}|^2}\E\left( |\Delta S_k|^2 + \left| \frac{\Phi_1}{k} S_k \right|^2 - 2 \Re\left( \frac{\Phi_1}{k} S_k \overline{\Delta S_k} \right) \middle| \mathcal{F}_k \right)\\
 &= \frac{1}{|a_{k+1}|^2} \left( 1 + \left| \frac{\Phi_1}{k} S_k \right|^2 - 2 \Re\left( \left|\frac{\Phi_1}{k} S_k\right|^2 \right)\right) \text{ a.s.},
\end{align*}
using that $|\Delta S_k| = 1$ and $\E(\Delta S_{k}| \mathcal{F}_k) = \Phi_1\frac{S_k}{k}$ a.s. This yields
\begin{equation*}
 \E\left( |\Delta M_k|^2 \middle| \mathcal{F}_k \right) = \frac{1}{|a_{k+1}|^2}\left( 1 - \left| \frac{\Phi_1}{k} S_k \right|^2\right) \text{ a.s.}
\end{equation*}
As a consequence, we have
\begin{equation}
 \label{eqn:formula}
 \crochet{M,\bar{M}}_n = \sum_{k=1}^{n-1} \frac{1}{|a_{k+1}|^2} - \sum_{k=1}^{n-1} \frac{1}{|a_{k+1}|^2} \left|\Phi_1\frac{S_k}{k}\right|^2 \quad \text{a.s.}
\end{equation}
We now study the asymptotic behaviour of these two sums.
We deduce from \eqref{eqn:data} that
\begin{equation}
 \label{eqn:asymp}
 v_n := \sum_{k=1}^{n-1} \frac{1}{|a_{k+1}|^2} \sim |C_1|^2 \frac{n^{1 - 2 \Re(\Phi_{1})}}{1 - 2 \Re(\Phi_1)},
\end{equation}
and from Lemma~\ref{lem:martingale} that
\[
 \frac{1}{|a_{n+1}|^2 n^2}\E\left( |S_n|^2\right) \sim_{n \to \infty} |C_1|^2 n^{-(1+ 2\Re(\Phi_1))},
\]
as $n \to \infty$. Therefore, there exists $C > 0$ such that for all $n$ large enough, we have
\begin{equation}
 \label{eqn:intermediate}
 \E\left( \sum_{k=1}^{n-1} \frac{1}{|a_{k+1}|^2} \left|\Phi_1\frac{S_k}{k}\right|^2\right) \leq C n^{-2\Re(\Phi_1)} = o(v_n).
\end{equation}
It shows that $\lim_{n \to \infty} \frac{1}{v_n}\sum_{k=1}^{n-1} \frac{1}{|a_{k+1}|^2} \left|\Phi_1\frac{S_k}{k}\right|^2 = 0$ in probability, which completes the proof.
\end{proof}

We now turn to the central limit theorem result, writing
\begin{align*}
 &\phantom{=}\frac{S_n - n^{\Re(\Phi) \erm^{i \Im(\Phi) \log n}} W \exp(-\Phi_1 \log E) }{\sqrt{n}}\\
 &= \frac{Z_1(\tau_n) - W \exp(\Phi_1 \log (N_{\tau_n}/E))}{\sqrt{n}}\\
 &= \erm^{-\tau_n/2}\frac{Z_1(\tau_n) - W \erm^{\Phi_1 \tau_n} + W \erm^{\Phi_1 \tau_n} - W \exp(\Phi_1 \log (N_{\tau_n}/E)}{\sqrt{N_{\tau_n} \erm^{-\tau_n}}}.
\end{align*}
By Corollary~\ref{cor:obvious}, we observe that
\[
 \lim_{t \to \infty} \erm^{-t/2}\frac{Z_1(t) - W \erm^{\Phi_1 t}}{\sqrt{N_t \erm^{-t}}} = \mathcal{N}_\C(0,\frac{1}{2 \Re(\Phi_1) - 1}) \quad \text{in law},
\]
from which we deduce straightforwardly that $\erm^{-\tau_n/2}\frac{Z_1(\tau_n) - W \erm^{\Phi_1 \tau_n} }{\sqrt{N_{\tau_n} \erm^{-\tau_n}}}$ admit the same limit in distribution as $n \to \infty$, using that $\tau_n - \log n$ is tight. In addition, we have
\[
 \frac{\erm^{\Phi_1 t} - \erm^{\Phi_1 \log (N_t / E)}}{\sqrt{N_t}} = \frac{1+o(1)}{\sqrt{E}}\erm^{(\Phi_1 - 1/2)t}(1 - \erm^{\Phi_1 \log (N_t \erm^{-t}/E)}) \quad \text{a.s.}
\]
As $ 1/2 < \Re(\Phi_1)<1$ and $\lim_{t \to \infty} \frac{N_t - E \erm^{t}}{\erm^{t/2}}$ converges in distribution towards a Gaussian random variable, we conclude that this quantity converges to $0$ in probability.

post_theorem_intro_text:
In order to provide variety to this article, we propose to prove Theorem~\ref{thm:main} in two different ways. We study the regime $\Re(\Phi_1) \leq 1/2$ in Section~\ref{sec:diffusive} using Lindeberg's central limit theorem. The key observation in this section is that
\begin{equation}
  \label{eqn:defMartingale}
  \left( \frac{S_n}{\prod_{j=1}^n \left( 1 + \frac{\Phi_1}{j} \right)}, n\geq 1 \right) \text{ is a martingale,}
\end{equation}
its asymptotic behaviour can be deduced from studying its quadratic variation. Up to the difficulty of dealing with a complex martingale, the argument there follows closely standard methods in dimension 1 or $d$ \cite{BaB,BercuLaulin2019}.

We then turn to the regime $\Re(\Phi_1)> 1/2$ in Section~\ref{sec:spiraling}. We use there the known connection between ERW and P\'olya urns, which was notably exploited by Baur and Bertoin in \cite{BaB} to obtain a functional central limit theorem, as well as the connection between P\'olya urns and multitype Galton-Watson processes, that was exploited by Janson~\cite{Jan} to obtain asymptotics on the behaviour of these urns. These results cannot be applied immediately as we do not necessarily have a finite number of colors\footnote{Understand here directions that steps of the ERW might align with.}. P\'olya urns with infinite number have been already studied in the literature \cite{JMV} however, considering that we are only interested with a single martingale of that process, the analysis can be simplified. Specifically, borrowing arguments from the study of the additive martingales of branching random walks at complex parameters \cite{IKM} will allow us to conclude.

Before turning to the proofs though, we begin by stating explicitly the behaviour of the ERW in $\mathbb{Z}^2$. This process is parametrized by four positive numbers $p,q,r,s$ such that $p+q+r+s=1$.  These parameters correspond respectively to the probability for a walker oriented according to one of its uniformly sampled previous steps to move forward (repeating the step), to the left (making a rotation of angle $\pi/2$), backward (making a rotation of angle $\pi$) or to the right (making a rotation of angle $3\pi/2$). The case $q=r=s=(1-p)/3$ reduces to the previously studied standard ERW in the plane.

In this model, remark that $\Phi_1= p - r + i (q-s)$, therefore Theorem~\ref{thm:main} implies the following behaviour for $(S_n, n \geq 1)$, depending on the sign of $p-r-1/2$.
\begin{corollary}
Let $(S_n, n \geq 1) $ be the ERW in $\mathbb{Z}^2$ with parameters $p,q,r,s$ defined above.
\begin{itemize}
  \item If $p < r+1/2$, then $\lim_{n \to \infty} \frac{S_n}{n^{1/2}} = \mathcal{N}(0, \frac{1}{2 - 4 (p-r)} I_2)$ in law.
  \item If $p=r+1/2$, then $\lim_{n \to \infty} \frac{S_n}{(n\log )^{1/2}}= \mathcal{N}(0, \frac{1}{2} I_2)$ in law.
  \item If $p > r+1/2$, then there exists a random vector $W \in \mathbb{R}^2$ such that
  \begin{multline*}
    \lim_{n \to \infty}  \frac{\mathcal{R}_{-(q-s)\log n}S_n}{n^{p-r}} = W \quad \text{a.s.} \\ \text{and}\quad \lim_{n \to \infty} \frac{S_n - n^{p-r} \mathcal{R}_{(q-s)\log n}W}{n^{1/2}} = \mathcal{N}(0,\frac{1}{4(p-r)-2}I_2) \quad \text{ in law},
  \end{multline*}
  writing $\mathcal{R}_\theta$ for a rotation of angle $\theta$.
\end{itemize}
\end{corollary}

Finally, remark that the ERW in $\mathbb{Z}^2$ can be seen as a reinforced version of the Markov chains studied by Lopusanschi and Simon in \cite{LoS}, studying the asymptotic behaviour of the Lévy area of this path would therefore be of interest, especially studying the convergence of the ERW under a rough path topology.

\medskip
We now turn to the proof of Theorem~\ref{thm:main} in the two following sections. The proof of \eqref{eqn:mainSub} is given in the following section using Lindenberg's central limit theorem, with a sketch of the proof of \eqref{eqn:mainCrit}. The proof of \eqref{eqn:mainSup} is completed in Section~\ref{sec:spiraling}, using Poissonization methods and the analysis of a branching process.

