and $(S_n, n \geq 1)$ the ERW defined by
\begin{equation}
  \label{eqn:defERWC}
  S_0 = 0, \quad S_1 = 1 \quad \text{and}\quad S_n= S_{n-1} + (S_{I_n} - S_{I_n-1}) \erm^{i \theta_n}.
\end{equation}
\begin{itemize}
  \item If $\Re(\Phi_1) < 1/2$, then writing $\sigma^2 = \frac{1}{1 - 2 \Re(\Phi_1)} \in (1/3,\infty)$, we have
  \begin{equation}
   \label{eqn:mainSub}
    \lim_{n \to \infty} \frac{S_n}{n^{1/2}} = \mathcal{N}_\mathbb{C}(0,\sigma^2) \quad \text{ in law}.
  \end{equation}
  \item If $\Re(\Phi_1)= 1/2$, then
  \begin{equation}
    \label{eqn:mainCrit}
