ref_dict.thm:1-comp:
\begin{theorem}\label{thm:1-comp}
Let $\pi\colon \mathcal{X}\rightarrow \mathbb{D}$ be a Fano projective morphism where $\mathcal{X}_0$ is reduced in $\mathcal{X}$ and
$(\mathcal{X},\mathcal{X}_0)$ plt.
Assume that the following conditions hold for the general fiber $\mathcal{X}_t$ with $t\neq 0$:
\begin{enumerate}
\item $\mathcal{X}_t$ is a toric surface of Picard rank one;
\item ${\rm mld}(\mathcal{X}_t)<\frac{1}{6}$; 
\item $\mathcal{X}_t$ does not have singularities in the baskets 
$\mathcal{F}_1,\dots,\mathcal{F}_4,\mathcal{D}$.
\end{enumerate}
Then, the pair $(\mathcal{X},\mathcal{X}_0)$ admits a $1$-complement over $\mathbb{D}$.
\end{theorem}

ref_dict.thm:toric-deg:
\begin{theorem}\label{thm:toric-deg}
Let $\pi\colon \mathcal{X}\rightarrow \mathbb{D}$ be a projective fibration.
Let $(\mathcal{X},\mathcal{X}_0+\mathcal{B})$ be a log Calabi--Yau pair over $\mathbb{D}$ for which $(\mathcal{X},\mathcal{X}_0)$ is plt. 
If $(\mathcal{X}_t,\mathcal{B}_t)$ is a toric pair\footnote{Meaning that $\mathcal{X}_t$ is a projective toric variety and $\mathcal{B}_t$ is the reduced torus invariant boundary.} for $t \in \mathbb{D}^*$,
then $(\mathcal{X}_0,\mathcal{B}_0)$ is a finite quotient of a toric pair. 
\end{theorem}

ref_dict.prop:tor-deg:
\begin{proposition}\label{prop:tor-deg}
Let $\mathcal{X}\rightarrow \mathbb{D}$ be a klt Fano degeneration of $\pp(1,1,n)$ with $n\geq 3$, then $\mathcal{X}_0$ is toric if and only if $\mathcal{X}_0\cong \pp(x^2,y^2,n)$ such that $x^2+y^2+n=(n+2)xy$.
\end{proposition}

ref_dict.def:pt:
\begin{definition}\label{def:pt}
{\em 
A pair $(X,B)$ is said to be {\em purely terminal} if the following conditions are satisfied:
\begin{enumerate}
\item the pair $(X,B)$ is plt; and 
\item for every prime component $S\subset \lfloor B\rfloor$ the pair $(S,B_S)$, obtained from adjunction of $(X,B)$ to $S$, is terminal. 
\end{enumerate} 
}
\end{definition}

