ref_dict.prop:permutohedral:
\begin{proposition}\label{prop:permutohedral}
    Let $\bm{\chi}$ be the character of the defining representation of $\Wn$ (i.e. the action on $\C^n$). Let $\fh_i$ be the character of the action of $\Wn$ on the cosets of $\mathfrak{S}_i \times \mathfrak{W}_{n-i}$. Let $\mathbb{1}$ be the character of the trivial representation. Then 
   \[
     \lrep{\Delta}_1 = \sum_{i=1}^n \fh_i - \bm{\chi} 
    \hspace{1cm}\text{and}\hspace{1cm}
    \rrep{\Delta}_1 = \sum_{i=1}^n \fh_i - n\,\mathbb{1}.
    \]
\end{proposition}

ref_dict.def:itypes:
\begin{definition}\label{def:itypes}
Consider $S(H)$ and $i \in [n]$. We call $i$\begin{itemize}
    \item \emph{uncovered} if $\begin{cases} \{t_{i-1},t_i\} \cap S(H) = \emptyset &\text{and } i \neq n-1\text{, or} \\ \{t_{n-1},t_{n-1},t_{n}\} \cap S(H) = \emptyset &\text{and } i = n-1\end{cases}$
    \item \emph{surrounded} if $i \in [n-2]$ and $\{t_{i-1},t_i\} \cap S(H) = \{t_{i-1}\}$ and $t_m \in S(H)\text{ for some } m>i$,
    \item \emph{shaded} if $t_i \in S(H)$ or if $t_n \in S(H)$ and $i=n-1$.
\end{itemize}
\end{definition}

ref_dict.thm:character:
\begin{theorem}\label{thm:character}
    Say $\Delta \subsetneq H$. Let $\bm{\chi}$ be the character of the defining representation of $\Wn$ (i.e. the action on $\C^n$). Let $\fh_i$ be the character of the action of $\Wn$ on the cosets of $\mathfrak{S}_i\times \mathfrak{W}_{n-i}$. Let $\fs$ be the character of the action of $\Wn$ on cosets of $\mathfrak{W}_1 \times \mathfrak{W}_{n-1}$. Let $\mathbb{1}$ be the character of the trivial representation and $\bm{\delta}$ be the character $w\mapsto (-1)^{\abs{\Neg(w)}}$. Then 
    \begin{align*}
     \lrep{H}_1 = \abs{\{i \in [n] \mid i\text{ shaded}\,\}}\mathbb{1} &+ \sum_{i\text{ uncovered}} \fh_i \\[6pt]&+ \abs{\{i \in [n-2] \mid i\text{ surrounded}\,\}}\fh_1 \\[6pt]&+ \begin{cases}
    \fs &\text{if $t_n \notin S(H)$}\\
    \bm{\delta} &\text{if }\{t_{n-1},t_n\} \cap S(H) = \{t_{n}\}\\
    0 &\text{otherwise.}
\end{cases}
    \end{align*}
    and 
        \begin{align*}
     \rrep{H}_1 = \bm{\chi} &+ \sum_{i\text{ uncovered}} \left(\fh_i - \mathbb{1}\right) \\[6pt]&+ \abs{\{i \in [n-2] \mid i\text{ surrounded}\,\}}\left(\fh_1-\mathbb{1}\right) \\[6pt]&+ \begin{cases}
    \fs-\mathbb{1} &\text{if $t_n \notin S(H)$}\\
    \bm{\delta} &\text{if }\{t_{n-1},t_n\} \cap S(H) = \{t_{n}\}\\
    0 &\text{otherwise.}
\end{cases}
    \end{align*}
\end{theorem}

