			\item \label{i:usos:iii}
			There exist $r_1,\ldots,r_{N_{\rm red}(d)}\in\ccA_d$ s.t.
			\begin{equation*}\label{eq:usosthm}
				f\ =\ \sum_{i=1}^{N_{\rm red}(d)} r_i^*r_i.
			\end{equation*}
		\end{enumerate}
		If $\cH$ is infinite-dimensional, then the above statements are also equivalent to
		\begin{enumerate}[\rm(i)]\itemsep=5pt
			\item[\rm (iv)] \label{i:usos:iv}
			There exists $r\in\ccA_d$ s.t.
			\begin{equation*}
				f\ =\ r^*r.
			\end{equation*}
		\end{enumerate}
	\end{thm}

