 \begin{equation}\label{linear equation}
 \begin{cases}
 i\partial_{t}u+(\Delta_{g}^{2}-\beta\Delta_{g})u=0,\\ u(0,x)=u_{0}(x).
 \end{cases}
 \end{equation}
 \subsection{Local controllability in energy space}
 Since $\omega$ satisfies the Geometric Control Condition, we can find $\omega'$ satisfying GCC and $\omega'\Subset \omega$, we then introduce $\varphi\in C^{\infty}(M)$ real-valued supported in $\omega$ such that $\varphi=1$ on $\omega'$.
 Consider the systems
 \begin{equation}\label{HUM dual double equation}
 \begin{cases}
 i\partial_{t}u+\Delta^2_g u-\beta\Delta_{g}u=h\in L^{2}(0,T;H^2), u(T)=0,\\ i\partial_{t}v+\Delta^{2}_{g}v-\beta\Delta_{g}v=0, v(0)=v_{0}\in H^{-2}(M),
 \end{cases}
 \end{equation}

