\begin{equation}\label{damped}
	\begin{cases}
		i\partial_{t}u+\Delta^{2}_{g}u-\beta\Delta_{g}u+|u|^{2k}u+u=a(x)(1-\Delta_{g})^{-2}\big(a(x)u_{t}\big),& (t,x)\in [0,T]\times M,\\ u(0,x)=u_{0}\in H^{2}(M)
	\end{cases}
\end{equation}
By  the direct computation, one can observe that the damped equation does not conserve its energy:
\begin{equation*}
	E(u)(t)-E(u)(0)=-\int_{0}^{t}\|(1-\Delta_{g})^{-1}\big(a(x)\partial_{t}u\big)\|_{L^{2}(M)}^{2}\,\dd t.
\end{equation*}The presence of damping term helps us obtain the exponential decay of the energy, which is stated as follows.

\begin{theorem}
	Let $(M,\omega)$ satisfy GCC and $a\in C^{\infty}(M)$, then for every $R_{0}>0$, there exist $C(R_{0})$ and $\gamma(R_{0})$ such that 
	\begin{equation}
		\|u(t)\|_{H^{2}(M)}\leq Ce^{-\gamma t}\|u_{0}\|_{H^{2}(M)}, ~t>0,
	\end{equation}
	holds for every solution $u$ of \eqref{damped} with initial data $u_{0}\in H^{2}(M)$ obeying $\|u_{0}\|_{H^{2}(M)}\leq R_{0}$.
\end{theorem}
