The proof of the main theorem is described as an "immediate consequence of" the following two theorems.

\begin{theorem}[Algebraic classification theorem] \label{th:ordersAllBasisG}
  Suppose $\du=(d_1,d_2,d_3)$ is a list of positive integers, where any repeated term is odd. Let $R$ be the sphere-product $\Q$-algebra generated by $x_1, x_2, x_3$ in degrees $\du=(d_1,d_2,d_3)$. If $A$ is an order in $R$, then there exists a coefficient sequence $\cf$ for which $A \iso A(\cf, \du)$.
\end{theorem}

\begin{theorem}[Topological existence theorem]\label{thm_top_main}
Let $\underline{d}=(d_1,d_2,d_3)$ be a list of positive integers greater than $1$, and let $\mathfrak{c} : \mathcal{P}([3]) \to \N$ be a coefficient sequence. 
There exists a $CW$-complex $X(\cf,\du)$ such that $H^*(X(\cf,\du);\Z)\cong A(\cf,\du)$.
\end{theorem}

The algebraic classification theorem gives that for an order $A$ in the $3$-generated sphere-product $\mathbb{Q}$-algebra $R$ (with the hypothesis that any repeated degree is odd), there exists a coefficient sequence $\mathfrak c$ such that $A \cong A(\mathfrak c,\underline d)$ (i.e., $A$ is a weighted sphere-product ring). Then the topological existence theorem realizes any such $A(\mathfrak c,\underline d)$ (when $d_i>1$) by a $CW$-complex $X(\mathfrak c,\underline d)$ with $H^*(X(\mathfrak c,\underline d);\mathbb Z)\cong A(\mathfrak c,\underline d)$. Combining these, one obtains a $CW$-complex $X_A$ with $H^*(X_A;\mathbb Z)\cong A$.

ref_dict.thm-jak:
\begin{theorem}\label{thm-jak}
Let $J(a,k) = \int_{-\pi/2}^{\pi/2} e^{2at} \cos^{2k-2} t\, dt$. Then for $k\geq 2$, $J(z,k)$ has no zeros in the strip $\{|\Im z| < k\} \subset \C$.
\end{theorem}

ref_dict.thm-f-b:
\begin{theorem}\label{thm-f-b}
	For the Fourier transform of $\frac{1}{J(a,k+1,1)}$, for $k\geq 1$, we have
	\[
	F(b) = \left(k+\frac{1}{2}\right) \cosh^{-2(k+1)}(\pi b) \quad \text{for any } b \text{ such that }|\Im b| < \frac12.
	\]
\end{theorem}

ref_dict.thm-disk-model:
\begin{theorem}\label{thm-disk-model} 
	Let $(X,\omega)$ be a hyperbolic Riemann surface. Let $(L,h)\to X$ be a holomorphic Hermitian line bundle with $i\Theta_h=\omega$. Let $p\in X$ have injectivity radius $r(p)$. Then for $k\geq 2$ and $(\cosh \frac{r(p)}{2})^{2k-2}>7\sqrt{k}$, we have
	\[
	\left|\rho_k(p)-\frac{1}{2\pi}(k-\frac12)\right| < 14k^{3/2}e^{-2(k-1)\log\cosh \frac{r(p)}{2}}.
	\]
\end{theorem}

ref_dict.thm-max-min:
\begin{theorem}\label{thm-max-min}
	Let $X$ be a hyperbolic Riemann surface of finite topology with no cusps. Assume further that no two systoles intersect. Then, there exists $l'>l_1$ and $k_0 > 0$ such that for all $k \geq k_0$, if the holonomies of $(kL, h^k)$ around all systoles are $1$ ($-1$, respectively), the maximum (minimum, respectively) of $\rho_k$ is attained in the exponentially small region $$\left\{ x \in X ,\Big| d(x,\gamma) < \left(\frac{\cosh\left(\frac{l_1}{2}\right)}{\cosh\left(\frac{l'}{2}\right)}\right)^{k} \right\}$$ for some systole $\gamma$.
\end{theorem}

ref_dict.thm-main:
\begin{theorem}\label{thm-main}
  Suppose that $(X,\omega)$ is a Riemann surface equipped with a complete hyperbolic metric. Let $(L,h)$ be a Hermitian holomorphic line bundle over $X$, whose curvature is $-i\omega$. We further assume that $(X,\omega)$ either has finite topology(i.e., genus of $X$ is finite), or the injectivity radius $r_X$ of $X$ is positive.  
  Let $k_0=3$ ($k_0=2$ when $X$ is compact).
  Then for all $k \geq k_0$, the Bergman kernel function $\rho_k(p)$ satisfies the following equality:
\[
\rho_k(p)
= \frac{k-\tfrac12}{2\pi}\left(1+\sum_{\gamma\in\mathfrak{G}_p}
\cosh^{-2k}\!\Big(\frac{l(\gamma)}{2}\Big)\cos\!\big(2\pi k\alpha_\gamma\big)\right).
\]

\end{theorem}

ref_dict.prop-kx:
\begin{proposition}\label{prop-kx}
	When $L=K_X$, the holonomy along a simple closed geodesic is $e^{2\pi \alpha\sqrt{-1}}=1$.
\end{proposition}

