\subsection{Van Kampen--Flores theorem} \label{subsec:vk-f}
A simplicial complex of dimension $d$ can always be embedded (even affinely) in $\R^{2d+1}$, for example, by placing the vertices of the complex along the moment curve $\R \to \R^{2d+1},~t \mapsto (t, t^2, \dots, t^{2d+1})$. The result of van Kampen \cite{van1933komplexe} and Flores \cite{flores1933n} states that the $d$-skeleton of the $(2d+2)$-dimensional simplex does not embed in $\R^{2d}$, showcasing that the above general embedding result is the best possible. In fact, they prove a stronger statement. For a simplicial complex $K$, we say that a function $f \colon K \to \R^n$ is \emph{almost injective} if $f(x_1) = f(x_2)$ implies that $x_1$ and $x_2$ belong to a common face of~$K$. This describes a wider class of functions than just injective functions. A function that is almost injective and is continuous will be called an \emph{almost embedding}.

\begin{theorem}[van Kampen--Flores \cite{flores1933n,van1933komplexe}]
    \label{thm:vk-f}
    Let $d \ge 1$ be an integer. Then, there does not exists an almost embedding $\sk_d(\Delta_{2d+2}) \to \R^{2d}$.
\end{theorem}

As before, a natural question arises: \emph{Since every almost injective function $\sk_d(\Delta_{2d+2}) \to \R^{2d}$ is discontinuous, can we quantify how discontinuous it needs to be}?
To answer this question, we will need to adjust the notion of the scale invariant modulus of discontinuity $\alpha$. Namely, for a simplicial complex $K$, let
\begin{equation*}
    \Conf_2^{\Delta}(K) \coloneqq \{(x,y) \in K \times K \colon~ x,y~\text{belong to disjoint faces}\}
\end{equation*}
denote the appropriate configuration space, in the literature \cite{matousek2003using} also known as the \emph{2-fold deleted product of $K$}. We again equip it with a $\Z/2$-action that flips $x$ and $y$. Then, an almost embedding $f \colon~ K \to \R^d$ induces a $\Z/2$-map
\begin{equation} \label{eq:Pf-vk-f}
    P_f \colon \Conf_2^{\Delta}(K) \longrightarrow S^{2d-1},~(x,y) \longmapsto \frac{f(x)-f(y)}{\|f(x)-f(y)\|}, 
\end{equation}
which is the restriction of the map \eqref{eq:test-inj}. We now define the \emph{scale invariant modulus of discontinuity of an almost injective function} $f$ as $\alpha^{(2)}(f) \coloneqq \delta(P_f)$. The reason we have the number two in the superscript of $\alpha$ is that in Section \ref{sec:almost-r-emb} we will study the more general almost $r$-injective functions and define the appropriate modulus of discontinuity $\alpha^{(r)}$.

With the new notion at hand, we can prove the following generalization of Theorem \ref{thm:vk-f}.

\begin{theorem}[Quantified van Kampen--Flores]
    \label{thm:quant-vk-f}
    Let $d \ge 1$ be an integer. Then, every almost injective function $\sk_d(\Delta_{2d+2}) \to \R^{2d}$ satisfies $\alpha^{(2)}(f) \ge r_{2d-1} = \arccos{\left(\frac{-1}{2d}\right)}$.
\end{theorem}
\begin{proof}
    Let $f \colon~ \sk_d(\Delta_{2d+2}) \to \R^{2d}$ be almost injective. Analogously as in the proof of Theorem \ref{thm:quant-general}, the function $P_f$ from \eqref{eq:Pf-vk-f} induces a $\Z/2$-map
    \begin{equation} \label{eq:del-prod-to-sphere}
        \Conf_2^{\Delta}(\sk_d(\Delta_{2d+2})) \longrightarrow \vrm{S^{2d-1}}{\alpha^{(2)}(f) + \varepsilon}.
    \end{equation}
    Let us show that this can only happen if $\alpha^{(2)}(f) + \varepsilon \ge r_{2d-1}$.
    Indeed, if $\alpha^{(2)}(f) + \varepsilon < r_{2d-1}$, the homotopy equivalence \eqref{eq:P(Sn)-homotopy} (and the text thereafter) would yield a $\Z/2$-map 
    \[
        \vrm{S^{2d-1}}{\alpha^{(2)}(f) + \varepsilon} \longrightarrow S^{2d-1}
    \] which when precomposed with \eqref{eq:del-prod-to-sphere} would yield a $\Z/2$-map
    \begin{equation*}
        F \colon \Conf_2^{\Delta}(\sk_d(\Delta_{2d+2})) \longrightarrow S^{2d-1}.
    \end{equation*}
    Let us introduce the \emph{2-fold deleted join} (see \cite[Section~5.5]{matousek2003using} for more detail) as a simplicial complex
    \begin{equation*}
        (\sk_d(\Delta_{2d+2}))^{*2}_{\Delta} \coloneqq \{tx + (1-t)y \in (\sk_d(\Delta_{2d+2}))^{*2} \colon~ x,y~\text{belong to disjoint faces}\}.
    \end{equation*}
    The deleted product can be seen as a subspace of the deleted join via the inclusion
    \begin{equation*}
        \Conf_2^{\Delta}(\sk_d(\Delta_{2d+2})) \longrightarrow (\sk_d(\Delta_{2d+2}))^{*2}_{\Delta},~(x,y) \longmapsto \tfrac{1}{2}x + \tfrac{1}{2}y.
    \end{equation*}
    The map $F$ can be extended to a $\Z/2$-map
    \begin{equation*}
        (\sk_d(\Delta_{2d+2}))^*_{\Delta} \longrightarrow S^{2d},\quad tx + (1-t)y \longmapsto \frac{(1-2t,t(1-t)F(x,y))}{\|(1-2t,t(1-t)F(x,y))\|}.
    \end{equation*}
    However, this contradicts \cite[Section~5.6, pg.~117]{matousek2003using} which says that $(\sk_d(\Delta_{2d+2}))^*_{\Delta}$ is a $(2d+1)$-sphere.
\end{proof}

We remark that we cannot improve the lower bound on the scale parameter for the non-existence of a $\Z/2$-map \eqref{eq:del-prod-to-sphere} since a $\Z/2$-map 
    \begin{equation*}
        \Conf_2^{\Delta}(\sk_d(\Delta_{2d+2})) \longrightarrow \vrm{S^{2d-1}}{r_{2d-1}}
    \end{equation*} exists. Namely, the domain is a $(2d)$-dimensional cellular complex with a free $\Z/2$-action and by \eqref{eq:P(Sn)-homotopy} the codomain is $(2d-1)$-connected. Hence, all obstructions to defining such a $\Z/2$-map vanish (see also \cite[Lemma~6.2.2]{matousek2003using}).

\section{Almost \texorpdfstring{$r$}{r}-embeddings}
\label{sec:almost-r-emb}

In this section we will prove a quantified topological Tverberg's theorem \cite{BSSz1981,ozaydin1987}. We will first introduce the appropriate language in order to state it as a nonembeddability-type result \cite{avvakumov2021eliminating}.

\begin{definition}
    Let $r \ge 2$, $d \ge 0$ be integers and $K$ a simplicial complex. A function $f\colon K \to \R^d$ is \emph{almost $r$-injective} if any $r$ pairwise disjoint faces $\sigma_1,\dots ,\sigma_r \subseteq \Delta_N$ satisfy $f(\sigma_1) \cap \dots \cap f(\sigma_r) = \emptyset$.
\end{definition}

In another words, an almost $r$-injective function $f$ never identifies $r$ points from pairwise disjoint faces. This represents the $r$-fold generalization of the notion of the almost injectivity ($r=2$) from the previous section.
Tverberg \cite{tverberg1966} proved that for $r \ge 2$ and $d \ge 0$ any \emph{affine} function $f\colon \Delta_N \to \R^d$ is not almost $r$-injective if the dimension of the simplex is large enough, namely if $N \ge (r-1)(d+1)$.
B\'ar\'any, Shlosman and Sz\H ucs \cite{BSSz1981} and \"Ozaydin \cite{ozaydin1987} showed that no such \emph{continuous} almost $r$-injective function exists if $r$ is a prime power. 

\begin{theorem}[Topological Tverberg, prime power case {\cite{BSSz1981, ozaydin1987}}] \label{theorem: topological tverberg}
    Let $d \ge 1$ be an integer, let $r \ge 2$ be a prime power, and let $N = (r-1)(d+1)$. Let $f\colon \Delta_N \to \R^d$ be any function. Then, if $f$ is a $r$-injective, it is not continuous.
\end{theorem}

The prime power condition is really necessary: Frick \cite{frick2015counterexamples} and Blagojevi\'c, Frick and Ziegler~\cite{blagojevic2015barycenters}, building on work of Mabillard and Wagner \cite{mabillard2014eliminating}, showed that if $r$ is not a prime power and $d \ge 3r$, then a continuous almost $r$-embedding $f \colon~ \Delta_N \to \R^d$ exists. The lower bound on $d$ was improved to $d \ge 2r+1$ by Avvakumov, Mabillard, Skopenkov and Wagner \cite{avvakumov2021eliminating}. In particular, when $r$ is a prime power, a natural question of quantifying discontinuity of almost $r$-injective functions emerges.

In order to answer it, in Definition \ref{def:alpha^(r)} below, we introduce a notion $\alpha^{(r)}$ that captures discontinuity of such maps. It is an $r$-fold analogue of scale-invariant moduli of discontinuity $\alpha$ and $\alpha^{(2)}$ introduced in Section \ref{sec:injectivity}. The following is the main theorem of the section.

\begin{theorem} [Quantified topological Tverberg] \label{theorem: discontinuous tverberg}
    Let $d \ge 1$ be an integer, $r$ a prime power, and $f\colon \Delta_{(r-1)(d+1)} \to \R^d$ any function. Then, if $f$ is almost $r$-injective it must satisfy
    \[
    	\alpha^{(r)}(f) ~\ge~  \arccos(\tfrac{-1}{d(r-1)}).
    \]
\end{theorem}

The constant $\arccos(\tfrac{-1}{d(r-1)})$ denotes the diameter of the regular $d(r-1)$-dimensional simplex inscribed in the $(d(r-1)-1)$-sphere equipped with the geodesic metric. As explained in Remark \ref{remark: R_delta and angles}, the fact that $\alpha^{(r)}(f) > 0$ implies that $f$ is not continuous. Therefore, Theorem \ref{theorem: discontinuous tverberg} presents a generalization of the topological Tverberg theorem.

\begin{definition} \label{def:r-del-prod}
	For an integers $r \ge 2$ and $N \ge r-1$ we define a cellular complex
	\[
        \Conf_r^{\Delta}(\Delta_N) := \{(x_1,...,x_r) \in  (\Delta_N)^{\times r}: x_i\text{'s belong to pairwise disjoint faces}\},
	\]
    called the \textit{$r$-fold deleted product} of $\Delta_N$.
\end{definition}

The symmetric group $\mathfrak{S}_r$ acts freely on $\Conf_r^{\Delta}(\Delta_N)$ by permuting the coordinates. Let us denote by
\(
	W_r^{\oplus d} := \{(z_1,...,z_r) \in (\R^d)^{\oplus r}: z_1 + \dots + z_r = 0\}
\)
a $d(r-1)$-dimensional $\mathfrak{S}_r$-representation, where the action is also given by permutation of coordinates. Next, we define an $\mathfrak{S}_r$-map
\begin{equation*} \label{eq:map Pf}
	\Conf_r^{\Delta}(f) \colon \Conf_r^{\Delta}(\Delta_N) \longrightarrow W_r^{\oplus d}
\end{equation*}
which sends a tuple $(x_1,...,x_r) \in \Conf_r^{\Delta}(\Delta_N)$ to a tuple obtained from 
\(
	(f(x_1), \dots , f(x_r)) \in (\R^d)^{\oplus r}
\)
by subtracting the average $\frac{1}{r}(f(x_1) + \dots + f(x_r))$ from each of the $r$ coordinates $f(x_i)$. We note that $f$ is almost $r$-injective if and only if the image of $\Conf_r^{\Delta}(f)$ does not contain the origin $0 \in W_r^{\oplus d}$, which enables the following definition.

\begin{definition} \label{def:alpha^(r)}
	Let $f\colon \Delta_N \to \R^d$ be an almost $r$-embedding. Then we define
	\[
		\alpha^{(r)}(f) := \delta\Big(\Conf_r^{\Delta}(\Delta_N) ~ \xrightarrow{~\Conf_r^{\Delta}(f)~}~ W_r^{\oplus d} \setminus \{0\} ~\xrightarrow{~\nu~} ~S(W_r^{\oplus d})\Big),
	\]
	where $\nu\colon v \mapsto v/\|v\|$ is a deformation retraction and the unit sphere $S(W_r^{\oplus d}) \subseteq W_r^{\oplus d}$ is assumed to be endowed with the geodesic metric.
\end{definition}

\begin{remark} \label{remark: R_delta and angles}
    Let $f\colon \Delta_N \to \R^d$ be an almost $r$-embedding.  The value $\alpha^{(r)}(f)$ can be geometrically interpreted as follows. 
    We have 
\[
	\Conf_r^{\Delta}(f)(x_1,...,x_r) = \left(f(x_1) - \tfrac{1}{r}\bigl(f(x_1) + \dots + f(x_r)\bigr), \dots , f(x_r) - \tfrac{1}{r}\bigl(f(x_1) + \dots + f(x_r)\bigr)\right),
\]
as depicted in Figure \ref{fig:r-tuple}.
Then, there are arbitrarily close $r$-tuples $x, y \in \Conf_r^{\Delta}(\Delta_N)$ with the property that the angle between the vectors $\Conf_r^{\Delta}(f)(x),~ \Conf_r^{\Delta}(f)(y) \in W_r^{\oplus d}$
is at least $\alpha^{(r)}(f)$.
In other words, the notion $\alpha^{(r)}(f)$ captures how large angles between values of $\Conf_r^{\Delta}(f)$ at two close points in the $r$-fold deleted product can be. If $f$ is moreover continuous, then so is $\Conf_r^{\Delta}(f)$, and therefore $\alpha^{(r)}(f) = 0$. So, in particular, having $\alpha^{(r)}(f)>0$ ensures that $f$ is discontinuous.

