\section{Introduction}
\label{sec:introduction}
Let $\mathbb{K}$ be a commutative ring, and let $A \in \mathbb{K}^{n \times n}$ be a square matrix of order $n$. 
The characteristic polynomial of $A$ is defined by
\begin{equation}\label{Eqn:c-h-thm,coeef-as-d}
p_A(\lambda) = \lambda^n + d_1 \lambda^{n-1} + d_2 \lambda^{n-2} + \cdots + d_{n-k} \lambda^{k} + \cdots + d_n.
\end{equation}
The classical \emph{Cayley-Hamilton theorem} states that
\[
p_A(A) = A^n + d_1 A^{n-1} + d_2 A^{n-2} + \cdots + d_{n-k} A^{k} + \cdots + d_n I_n = O,
\]
where $O$ denotes the zero matrix. 
Various combinatorial proofs of such fundamental results are well known in the literature~\cite{Comb-Newton-Girad-Disc_Mukherjee-Bera,Straubing1983,11,22}.

The \emph{length} of a linear subdigraph $\gamma$, denoted $L(\gamma)$, is the total number of edges in $\gamma$. 
Let $L_r$ denote the set of all linear subdigraphs of $\mathcal{D}(A)$ having length $r$. 
We then define
\begin{equation}\label{Eqn:Defn of lr;sgn sum of weightd of lsd of length r}
\ell_r \triangleq \sum_{\gamma \in L_r} (-1)^{c(\gamma)} \, w(\gamma).
\end{equation}

Alternatively, the characteristic polynomial of $A$ can also be expressed in terms of the sums of its principal minors as
\begin{equation}\label{eqn:C-H-Thm-f-as coef}
p_A(\lambda) = \lambda^n - f_1 \lambda^{n-1} + f_2 \lambda^{n-2} - \cdots + (-1)^{n-k} f_{n-k} \lambda^{k} + \cdots + (-1)^n f_n,
\end{equation}
where $f_i$ denotes the sum of all principal minors of order $i$ of $A$. 
Comparing Equations~\eqref{Eqn:c-h-thm,coeef-as-d} and~\eqref{eqn:C-H-Thm-f-as coef}, we obtain
\[
d_i = (-1)^i f_i, \qquad \text{for each } i \in [n].
\]
Since $f_i$ is the sum of all principal minors of order $i$, it can equivalently be expressed as a weighted sum over linear subdigraphs of $\mathcal{D}(A)$:
\begin{equation}\label{Eqn:fi=sum lsd}
f_i = \sum_{\gamma} (-1)^{i - c(\gamma)} \, w(\gamma),
\end{equation}
where the summation extends over all linear subdigraphs $\gamma$ of $\mathcal{D}(A)$ containing $i$ vertices.

\begin{proof}
We compute:
\begin{align*}
d_i 
 &= (-1)^i f_i \\
 &= (-1)^i \sum_{\gamma} (-1)^{i - c(\gamma)} w(\gamma) 
 && \text{(by Equation~\eqref{Eqn:fi=sum lsd})}\\
 &= \sum_{\gamma} (-1)^{c(\gamma)} w(\gamma)\\
 &= \ell_i, 
 && \text{(by Equation~\eqref{Eqn:Defn of lr;sgn sum of weightd of lsd of length r}).}
\end{align*}
\end{proof}

\begin{remark}\label{Rem:dr=lr: Coeffiecients of Ch eqn is weightd sum of lsd}
The preceding discussion provides a clear combinatorial interpretation of the coefficients of the characteristic polynomial of $A$: 
each coefficient is a sign-weighted sum of the weights of all linear subdigraphs of the associated digraph $\mathcal{D}(A)$.
\end{remark}

\begin{lemma}\label{Lemma:(i,j)th entry of Ak is the sum of weights of all closed walk lengh k from i to j}[Theorem 3.1.2, \cite{Brualdi-Cvetkovic-combinatorial-matrix-thy}]
Let $A=[a_{ij}]$ be a matrix of order $n.$ For each positive integer $k,$ the entry $a_{ij}^{(k)}$ of $A^k$ in the $i$th row and $j$th column equals the sum of the weights of all walks in $\mathcal{D}(A)$ of length $k$ from vertex $i$ to vertex $j.$ 
 \end{lemma}
\begin{lemma}\label{Lemma:Tr(Ak)=Ck}
For any $k\in \mathbb{N},$ the trace of the matrix $A^k$ is $\text{Tr}(A^k)=c_k.$ 
\end{lemma}
\begin{proof}
By Lemma \ref{Lemma:(i,j)th entry of Ak is the sum of weights of all closed walk lengh k from i to j}, the entry $a_{ii}^{(k)}$ of $A^k$ in the $i$th row and $i$th column equals the sum of the weights of all closed walks in $\mathcal{D}(A)$ of length $k$ from the vertex $i$ to itself. Therefore, $\text{Tr}(A^k)$ is the sum of the weights of all closed walks of length $k.$ That is, $\text{Tr}(A^k)=c_k.$ 
\end{proof}
\begin{remark}\label{Rem:Combinatorial inte of Trace}
According to Lemma \ref{Lemma:Tr(Ak)=Ck}, a combinatorial interpretation of trace of a matrix is the sum of the weights of closed walks. 
\end{remark}
\section{Trace Cayley-Hamilton theorem}
In this section, we will articulate and demonstrate the trace Cayley-Hamilton theorem. The theorem, as referenced in \cite{Darij-Grinberg-Trace-Cayley-Hamilton}
\begin{theorem}[Trace Cayley-Hamilton theorem]\label{Thm: Trace cayley Hamilton Thm}
Let $A$ be a $n\times n$ matrix over the commutative ring $\mathbb{K}.$ Let $p_A(\lambda)$ be the characteristic polynomial of $A$ defined as in Equation \eqref{Eqn:c-h-thm,coeef-as-d}. Then the trace Cayley-Hamilton theorem says the following:
\begin{enumerate}
 \item $\text{Tr}(A^r)+\text{Tr}(A^{r-1})d_1+\cdots+\text{Tr}(A^{r-(n-1)})d_{n-1}+\text{Tr}(A^{r-n})d_n=0, \text{ for }r>n$
 \item $\text{Tr}(A^r)+\text{Tr}(A^{r-1})d_1+\cdots+\text{Tr}(A^{r-(n-1)})d_{n-1}+rd_r=0, \text{ for } 1\leq r\leq n.$
\end{enumerate}
\end{theorem}
To establish Theorem \ref{Thm: Trace cayley Hamilton Thm}, we will initially prove the following theorem. 
\begin{theorem}\label{Thm:Combinatorial proof of Trace Cayley Hamilton thm}
Let $A$ be an $n\times n$ matrix and $\mathcal{D}(A)$ be the associate weighted digraph of $A.$ Then the following hold: 
\begin{enumerate}
 \item $c_r+c_{r-1}\ell_1+c_{r-2}\ell_2+\cdots+c_{r-n}\ell_n=0, r>n$
 \item $c_r+c_{r-1}\ell_1+c_{r-2}\ell_2+\cdots+r\ell_r=0, 1\leq r\leq n$.
\end{enumerate} 
\end{theorem}

