Let $n,m,Q\ge 1$ be natural numbers, $U\subset \mathbb{R}^m$ open, and $f\in W_{loc}^{1,p}(f(\Omega),\mathcal A_Q(\mathbb{R}^n))$. If $\omega$ is a $S_Q$-invariant smooth $k$-form on $(\mathbb{R}^n)^Q$, and either $k+1\le p$ of $\mathrm {d} \omega=0$ and $k\le p$, then $\omega$ has a well-defined pull-back $f^*\omega \in L^{p/k}_{loc}(U,\bigwedge^k\mathbb{R}^m)$ and moreover
\begin{align*}
    \mathrm {d}(f^*\omega)=f^*(\mathrm {d}\omega)
\end{align*}
weakly.,

full_context:
A real number $x$ is a \emph{Liouville number} if for every $N\in\mathbb{N}$ there exist integers $p,q$ with $q\ge2$ such that
\[
\bigl|x-\tfrac{p}{q}\bigr|<q^{-N}.
\]
We denote by $\mathcal{L}$ the set of all Liouville numbers. It is classical that $\mathcal{L}$ is dense in $\mathbb{R}$, has Lebesgue measure zero, and is a dense $G_\delta$ subset of $\mathbb{R}$. In particular, $\mathcal{L}$ is uncountable and topologically large while being arithmetically very thin.

In 1962, \cite{erdos} proved that every real number can be expressed both as a sum and, if nonzero, as a product of two Liouville numbers. This also follows from the fact that the set $\mathcal{L}$ of Liouville numbers is a dense $G_{\delta}$ subset of $\mathbb{R}$, although Erd\H{o}s gave an explicit elementary proof. Equivalently, for any nonzero real number $r$, there exist $\sigma,\tau\in\mathcal{L}$ such that $r=f(\sigma,\tau)$ with $f(x,y)=x+y$ or $f(x,y)=xy$.

Later, \cite{burger} extended this phenomenon to a broad family of functions $f(x,y)$. In particular, for $f(x,y)=y^x$, he showed that every positive real number $r\ne1$ can be written as $r=\sigma^{\tau}$ for suitable $\sigma,\tau\in\mathcal{L}$. We refer to~\cite{alniacik1995, Morris2024, Kumar2014} for further topological studies of $\mathcal{L}$ and to~\cite{LG2024} for analogous results concerning $U$-numbers. Consequently, there is no analogue of the Gelfond--Schneider theorem within the class of Liouville numbers. Recently, \cite{ChalebgwaMorris2025} proved that if $S$ is any set of real numbers of full Lebesgue measure, then every positive real number $r$ equals $x^y$, for $x,y\in S$. So, for example, this applies to the case that $S$ is the set of all normal numbers, or the set of real numbers of irrationality exponent 2, or the Mahler set of S-numbers.

\begin{definition}
Let $\varepsilon>0$. A real number $x$ is called an \emph{$\varepsilon$-strong Liouville number} if there exists an infinite sequence of rationals $p_k/q_k$ with $q_k>1$ such that
\[
\Bigl|x-\frac{p_k}{q_k}\Bigr| < q_k^{-(\log q_k)^{1+\varepsilon}}, \quad \forall k\ge1.
\]
We denote the set of such numbers by $\mathcal L_\varepsilon$.
\end{definition}

\begin{proposition}
Every $\varepsilon$-strong Liouville number is a Liouville number.
\end{proposition}

\begin{proof}
For any $N>0$, take $k$ large enough that $(\log q_k)^{1+\varepsilon} > N$ (e.g., $k>3N^{1/(1+\varepsilon)}+2$). Then 
\[
\left|x - \frac{p_k}{q_k}\right| < q_k^{-(\log q_k)^{1+\varepsilon}} < q_k^{-N},
\]
so $x$ is Liouville.
\end{proof}

\begin{definition}
Let $\varepsilon>0$. A real number $x$ is called an \emph{$\varepsilon$-strong Liouville number} if there exists an infinite sequence of rationals $p_k/q_k$ with $q_k>1$ such that
\[
\Bigl|x-\frac{p_k}{q_k}\Bigr| < q_k^{-(\log q_k)^{1+\varepsilon}}, \quad \forall k\ge1.
\]
We denote the set of such numbers by $\mathcal L_\varepsilon$.
\end{definition}

\begin{proof}
For any $N>0$, take $k$ large enough that $(\log q_k)^{1+\varepsilon} > N$ (e.g., $k>3N^{1/(1+\varepsilon)}+2$). Then 
\[
\left|x - \frac{p_k}{q_k}\right| < q_k^{-(\log q_k)^{1+\varepsilon}} < q_k^{-N},
\]
so $x$ is Liouville.
\end{proof}

\begin{proof}
The proof relies on a linear forms in logarithms estimate due to Baker combined with the defining property of \emph{$\varepsilon$-strong Liouville numbers}. We refer the reader to \cite[Proposition 3.2]{MarquesOliveira2023} for details.
\end{proof}

\begin{theorem}
Every spiffy constant belongs to $\mathcal L_\varepsilon$ for all $\varepsilon>0$.
\end{theorem}

\begin{proof}
Let $x=x_a$ be a spiffy constant and define the rational truncations
\begin{equation}
\label{eq:trunc}
r_m = \sum_{n=1}^m \frac{a_n}{3^{e_n}} = \frac{p_m}{q_m}, \qquad q_m = 3^{e_m}.
\end{equation}
Then
\[
|x - r_m| \le q_m^{-3^{e_m-1}}.
\]
Since $\log q_m = e_m \log 3$, we have $(\log q_m)^{1+\varepsilon} = o(3^{e_m-1})$, and therefore, for sufficiently large $m$,
\[
|x - r_m| < q_m^{-(\log q_m)^{1+\varepsilon}}.
\]
Hence, $x \in \mathcal{L}_\varepsilon$ for every $\varepsilon>0$.
\end{proof}

\begin{theorem}\label{thm:strong-Liouville-selfpowers-nonLiouville}
For every $\varepsilon>0$ there exist continuum many $\varepsilon$-strong
Liouville numbers $x$ such that $x^x$ is transcendental and not a Liouville
number.

For any $\xi\in C\setminus\mathcal{B}$, we have $|\xi^\xi-a/b|\geq b^{-\tau}$ for all but finitely many rationals $a/b$, so $\xi^\xi$ is not Liouville. Moreover, since every $\xi\in C$ is $\varepsilon$-strong Liouville, Theorem 1.2 implies $\xi^\xi$ is transcendental. Thus $C\setminus\mathcal{B}$ consists of continuum many $\varepsilon$-strong Liouville numbers $\xi$ for which $\xi^\xi$ is transcendental and not Liouville.
\end{proof}

Having settled that:
\begin{enumerate}
\item for $x$ an $\varepsilon$-strong Liouville number, $x^x$ is a transcendental number;
\item the set of $\varepsilon$-strong Liouville numbers is a dense $G_\delta$-subset of $\mathbb{R}$;
\item for cardinality $\mathfrak{c}$ members of $\mathcal{L}_\varepsilon$, $x^x$ are Liouville numbers, and an equal number are not Liouville numbers.
\end{enumerate}
 We ask: what can be said about the set all Liouville numbers $x$ such that $x^x$ is transcendental, or indeed a Liouville number? The theorems below shed some light on this question.

