\begin{equation*}
        |h(x)|\le C\{\lVertu\rVert_{L^\infty(\Omega \cap B_4)}+\lVertu\rVert_{\cL_{2s}}\}\operatorname{dist}(x,\partial \Omega)^{\alpha },
    \end{equation*}
    where $\alpha = \min\{s,1-s\}$. Combining this decay estimate and the interior regularity result (Theorem \ref{Holder thm}), we derive the $C^\alpha$ boundary regularity. Then by an iteration process, we increase the power $\alpha$ successively until it reaches the desired power $s$.

As an important application, we establish a priori estimate for the solutions  to \eqref{main2}.  We assume that $\Omega \subset \mathbb{R} ^n$ is an unbounded domain with uniformly $C^{1,1}$ boundary, and $f$ satisfies the following condition:
\begin{itemize}
    \item $f(x,t):\Omega \times [0,\infty)\to\mathbb{R}$ is uniformly H\"older continuous with respect to $x$ and continuous with respect to $t$.
\end{itemize}
\begin{theorem}\label{1A1}
Assume $1<p<\frac{n+2s}{n-2s}$, $f$ satisfies 
\begin{equation}\label{growth f}
    f(x,t)\le C_0(1+t^p)
\end{equation}
uniformly for all $x$ in $\Omega$, and 
\begin{equation}\label{lim f}
    \lim _{t\to\infty}\frac{f(x,t)}{t^p} = K(x),
\end{equation}
    where $K(x)\in (0,\infty)$ is uniformly continuous and $K(\infty):=\lim _{|x|\to\infty }K(x) \in (0,\infty)$. 
Then there exists a constant $C$, such that 
\begin{equation}\label{bd1}
u(x)\le C,\quad\forall \, x\in \Omega
\end{equation}
holds for all nonnegative solutions $u$ of \eqref{main2}.
\end{theorem}

\begin{remark}
    The assumptions on $f$ are essential for the a priori estimate. When $f=0$ and $\Omega = B_1$, Abatangelo, Jarohs and Salda\~na \cite{Abatangelo2018Green} constructed nontrivial nonnegative solutions to \eqref{main2} that are unbounded, see also \cite{Li2023unique}.
\end{remark}

During the process of blow-up and rescaling, it can be shown that a sequence of the rescaled functions (still denoted by $u_i$) converges to a limiting function $u$ in the sense of $C^{2s+\beta}_{loc}$. In the case of a local operator, say $-\Delta$, we already have 
\[   \lim _{i\to\infty}(-\Delta) u_i(x) = (-\Delta) u(x).\]
However, this is not the case for nonlocal operators, as shown in \cite[Theorem 1.1]{Du2023blowup} by Du-Jin-Xiong-Yang, in which they work on the whole space $\mathbb{R}^n$. In order to establish a priori estimate on general  unbounded domains with boundaries, we generalize  their convergence result as follows.
\begin{theorem}\label{conv}
    Assume $n\ge 1$, $s\in (0,1)$, $\beta\in (0,1)$. $\Omega$ is an unbounded domain with boundary. Suppose nonnegative functions $\{u_i\}\subset \mathcal{L}_{2s}\cap C^{2s+\beta}_{loc}(\Omega)$ vanishes outside $\Omega$, and $u\in \mathcal{L}_{2s}$ vanishes outside $\Omega$. If $\{u_i\}$
    converges in $C^{2s+\beta}_{loc}(\Omega)$ to a function $u\in \mathcal{L}_{2s}$ , and $\{\mbox{$(-\triangle)^s$} u_i \}$ converges pointwisely in $\Omega$, then there exists a constant $b\ge 0 $ such that
    \begin{equation}
        \lim _{i\to\infty}\mbox{$(-\triangle)^s$} u_i(x) = \mbox{$(-\triangle)^s$} u(x) -b.
    \end{equation}
\end{theorem}

 In Section 2, we establish local boundary H\"older regularity  for \eqref{main1} and prove Theorem \ref{1bdry C^s}. In Section 3, we derive  a priori estimates for \eqref{main2} and validate Theorem \ref{1A1}. Finally, the proof of Theorem \ref{conv} is included in the Appendix.

