\begin{lemma}\label{lem. Ricatti}
 Assume that $u\in\mathcal{L}_{2s}(\mathbb{R}^{n})$ is a non-negative, continuous, and bounded function satisfying
 \begin{equation*}
 (-\Delta)^{s}u\leq-\lambda u^{p}
 \end{equation*}
 in the weak or viscosity sense, where $\lambda,p>0$ are two given constants. Then $u\equiv0$ in $\mathbb{R}^n$.
\end{lemma}
\begin{proof}
 Let us denote $\displaystyle M:=\sup_{x\in\mathbb{R}^{n}}u$, which is a finite and non-negative number. Our goal is to show $M=0$. Suppose on the contrary that $M>0$, we first apply the weak Harnack principle (see \cite[Theorem 1.2]{dCKP14}) to $v=M-u$, which satisfies $(-\Delta)^{s}v\geq0$ and $v\geq0$ in $\mathbb{R}^{n}$. It then follows that for every $r>0$ and $p\in\mathbb{R}^{n}$,
 \begin{equation*}
 \Big(\frac{1}{|B_{r}(p)|}\int_{B_{r}(p)}v^{t}dx\Big)^{1/t}\leq C\inf_{B_{2r}(p)}v,\quad\mbox{where }t<\frac{n}{n-2s}.
 \end{equation*}

\begin{lemma}\label{leuaddv}
Let $u,v>0$ be two globally bounded functions solving the system \eqref{eq. main}. Then there exists some $q>0$, such that
\[
q^{-1}\leq u(x),v(x)\leq q\quad \text{for all } x \in \mathbb{R}^n.
\]
\end{lemma}
\begin{proof}
 Since $u$ and $v$ are both bounded, we have $u,v\leq q_{1}$ for some sufficiently large $q_{1}$. Next, we argue that
 \begin{equation*}
 u,v\geq\min\Big\{\frac{1}{2},\frac{\omega}{(1+\alpha)q_{1}}\Big\}=:q_{2},
 \end{equation*}
 which confirms the existence of the desired $q>0$.

Back to \eqref{eq3.11'}, using the integrability obtained above, we have
\begin{equation*}
 \lim_{R\to0}\int_{(B_{R}^{+})^{c}}y^{1-2s}(\varphi^{2}|\nabla\sigma|^{2}+\psi^{2}|\nabla\tau|^{2})\,dxdy=0.
\end{equation*}
so we get
\begin{equation*}
 \int_{B_{R}^{+}}y^{1-2s}\zeta^{2}(\varphi^{2}|\nabla\sigma|^{2}+\psi^{2}|\nabla\tau|^{2})\,dxdy+\int_{\{y=0\}\cap B_{R}}|\sigma-\tau|^{2}\mathcal{P}(x)\,dx\to0,\quad\mbox{as }R\to0.
\end{equation*}
Therefore, $\sigma$ and $\tau$ are constants. Besides, since $\mathcal{P}(x)$ is strictly positive, we also have
\begin{equation*}
\sigma(x, 0) = \tau(x, 0), \quad x \in \mathbb{R}^n.
\end{equation*}
In conclusion, $\sigma\equiv\tau\equiv\mbox{constant}$ in $\mathbb{R}^{n}\times\mathbb{R}_{+}$. This completes the proof of Lemma \ref{lem. Liouville-type result with cutoff function}.
\end{proof}
As an immediate consequence of the Liouville-type result in Lemma~\ref{lem. Liouville-type result with cutoff function}, we can now derive a more concrete classification in the setting of one dimensional lower.
\begin{corollary}\label{cor. n=2 is more obvious}
 Assume that $n\leq2$ with $\frac{1}{2}\leq s<1$, or $n\leq1$ with $0<s<\frac{1}{2}$. Assume that $(U,V)$ is a solution to \eqref{eq. simplified extension equation} in $\mathbb{R}^{n}\times\mathbb{R}_{+}$, such that there exists a pair $(\varphi,\psi)$, with $\varphi>0>\psi$ everywhere and $L\begin{bmatrix}\varphi\\\psi\end{bmatrix}$ always belonging to $\overline{\mathbb{R}_{+}}\times\overline{\mathbb{R}_{-}}$. Then
 \begin{itemize}
 \item Either: $(u,v)$ is constant.
 \item Or: There exists a unit vector $\vec{\nu}$ such that $\Big(u(x),v(x)\Big)=\Big(u(x\cdot\vec{\nu}),v(x\cdot\vec{\nu})\Big)$, with $\partial_{\vec{\nu}}u>0>\partial_{\vec{\nu}}v$ along that direction.
 \end{itemize}
\end{corollary}
\begin{proof}
 Let us denote for $1\leq i\leq n$ that:
 \begin{equation*}
 (\xi_{i},\eta_{i}):=(\frac{\partial u}{\partial x_{i}},\frac{\partial v}{\partial x_{i}}),\quad(\sigma_{i},\tau_{i}):=(\frac{\xi_{i}}{\varphi},\frac{\eta_{i}}{\psi}).
 \end{equation*}
 Accordingly, we also define $Q_{(\varphi,\psi)}\begin{bmatrix}\sigma_{i}\\\tau_{i}\end{bmatrix}$ like in \eqref{eq. ratio quadratic operator}. Then we realize that \eqref{eq. quadratic energy growth condition} is true. In fact, we recall that as $(u,v)$ is bounded, the extension $(U,V)$ is also bounded in $\mathbb{R}^{n+1}_{+}$. By the Schauder estimate for the degenerate or singular equation \eqref{eq. simplified extension equation}, we have
 \begin{equation}\label{eq. gradient pointwise estimate 1 in cor}
 \|\nabla U\|_{L^{\infty}(\mathbb{R}^{n+1}_{+})}+\|\nabla U\|_{L^{\infty}(\mathbb{R}^{n+1}_{+})}\leq C.
 \end{equation}
 Besides, we apply the interior Schauder estimate to \eqref{eq. simplified extension equation} in each ball $B_{y/2}(x,y)$. Using the uniform ellipticity of \eqref{eq. simplified extension equation} inside $B_{y/2}(x,y)$ and the boundedness of $(U,V)$, we have
 \begin{equation}\label{eq. gradient pointwise estimate 2 in cor}
 |\nabla U(x,y)|+|\nabla V(x,y)|\leq\frac{C}{y}.
 \end{equation}
 By integrating the estimates \eqref{eq. gradient pointwise estimate 1 in cor} and \eqref{eq. gradient pointwise estimate 2 in cor}, we have verified \eqref{eq. quadratic energy growth condition}.

\begin{lemma}\label{lem. classification of one limiting profile}
Assume that one of the following holds:
\begin{itemize}
 \item Case 1: $\frac{1}{2} \le s < 1$ and $n = 3$;
 \item Case 2: $0 < s < \frac{1}{2}$ and $n = 2$.
\end{itemize}
For $(\overline{u}, \overline{v})$ as in Definition~\ref{def. limiting profile}, there exist functions $\varphi > 0 > \psi$ defined in $\mathbb{R}^n_{+}$ such that
\[
 \begin{cases}
 \displaystyle \lim_{y \to 0} \big(y^{1-2s} \varphi_y\big) 
 \le W_{uu}(\overline{u}, \overline{v})\,\varphi + W_{uv}(\overline{u}, \overline{v})\,\psi, \\[0.8em]
 \displaystyle \lim_{y \to 0} \big(y^{1-2s} \psi_y\big) 
 \ge W_{vu}(\overline{u}, \overline{v})\,\varphi + W_{vv}(\overline{u}, \overline{v})\,\psi.
 \end{cases}
\]
Moreover, $(\overline{u}, \overline{v})$ is one-dimensional. Specifically, one of the following holds:
\begin{itemize}
 \item[(i)] $(\overline{u}, \overline{v})$ is constant, equal to one of
 \[
 (\overline{u}, \overline{v}) \equiv (a,b), \quad (b,a), \quad \text{or} \quad \left(\sqrt{\frac{1+\omega}{2+\alpha}}, \sqrt{\frac{1+\omega}{2+\alpha}}\right).
 \]
 \item[(ii)] $(\overline{u}, \overline{v})$ depends only on $(x_{n-1}, y)$ (up to a rotation in $\mathbb{R}^{n-1}$), and
 \[
 \frac{\partial \overline{u}}{\partial x_{n-1}} > 0 > \frac{\partial \overline{v}}{\partial x_{n-1}}.
 \]
\end{itemize}
\end{lemma}

Denote by $(\varphi_{R},\psi_{R})$ the limit of this subsequence, and let $\lambda_{R}$ be the infimum of the functional \eqref{eq. eigenvalue functional}. Then $\lambda_{R}$ decreases with $R$, and hence $\lambda_{R}$ is uniformly bounded for all $R\geq100$. Furthermore,
\begin{equation*}
 \frac{\overline{\mathcal{E}}(\varphi_{R},\psi_{R})}
 {\displaystyle\int_{\mathbb{R}^{n-1}}(|\varphi_{R}|^{2}+|\psi_{R}|^{2})\,dx'}
 = \inf_{(\xi,\eta)\in C^{\infty}_{0}([-R,R]^{n-1}\times[0,R])}
 \frac{\overline{\mathcal{E}}(\xi,\eta)}
 {\displaystyle\int_{\mathbb{R}^{n-1}}(|\xi|^{2}+|\eta|^{2})\,dx'}
 = \lambda_{R}.
\end{equation*}
Since $\overline{W}_{uv}>0$ (see \eqref{eq. W_uv>0}), it is advantageous to replace $(\varphi_{R},\psi_{R})$ with $(|\varphi_{R}|,-|\psi_{R}|)$, which does not increase the quotient \eqref{eq. eigenvalue functional}. Hence, without loss of generality, we may assume that
\begin{equation*}
 \varphi_{R}\geq0\geq\psi_{R}
 \quad\text{in }[-R,R]^{n-1}\times[0,R],
 \qquad
 \varphi_{R}=\psi_{R}=0
 \quad\text{outside }[-R,R]^{n-1}\times[0,R].
\end{equation*}
The Euler-Lagrange equations associated with the minimizers $(\varphi_{R},\psi_{R})$ are
\begin{align}\label{eq. varphi_R and psi_R equation}
 &\left\{
 \begin{aligned}
 &\mathrm{div}(y^{1-2s}\nabla\varphi_{R})=0,\\
 &\mathrm{div}(y^{1-2s}\nabla\psi_{R})=0
 \end{aligned}
 \right.
 \quad \text{in }[-R,R]^{n-1}\times[0,R],\\[4pt]
 &\left\{
 \begin{aligned}
 &-\lim_{y\to0}(y^{1-2s}\partial_{y}\varphi_{R})
 +\overline{W}_{uu}\varphi_{R}
 +\overline{W}_{uv}\psi_{R}
 =\lambda_{R}\varphi_{R},\\
 &-\lim_{y\to0}(y^{1-2s}\partial_{y}\psi_{R})
 +\overline{W}_{vu}\varphi_{R}
 +\overline{W}_{vv}\psi_{R}
 =\lambda_{R}\psi_{R}
 \end{aligned}
 \right.
 \quad \text{on }[-R,R]^{n-1}.
\end{align}

