As per \citet{arnold2020bivariate}, the general accelerated failure conditionals model is of the form: 
\begin{align}
 \bar{F}_X(x) = P(X>x) = \bar{F}_0(x),\quad x>0, \label{eq: general marginal}
\end{align}
for some survival function $\bar{F}_0(x) \in [0, 1] \ \forall x> 0$, and for each $x>0$:
\begin{equation}
 P(Y>y\mid X>x) = \bar{F}_1\left(\beta(x)y\right), \quad x, y >0,\label{eq: general cond}
\end{equation}
for some survival function $\bar{F}_1(\beta(x)y) \in [0, 1] \ \forall x, y >0$ and a suitable acceleration function $\beta(x)$. As per \citet{arnold2020bivariate}, in the analysis of dependent lifetimes of components in a system, it is more appropriate to consider the conditional density of $Y$ given that the first component, with lifetime $X$, remains operational at time $x$. Hence why, the conditioning event is taken to be $\{X > x\}$, rather than conditioning on the exact value $X = x$. The joint survival function is then:
\begin{align}
 P(X>x, Y>y) = \bar{F}_0(x) \bar{F}_1\left(\beta(x)y\right), \quad x, y>0. \label{eq: general joint}
\end{align}
Assuming differentiability and $X,Y$ are continuous, we obtain the marginal densities:
\[
f_X(x) = -\frac{d}{dx}P(X>x) = -\frac{d}{dx}\bar{F}_0(x) = f_0(x),
\]
and since $\lim_{x\to 0^+}\bar{F}_0(x)=1$, where $\beta(0):=\lim_{x\to 0^+}\beta(x)$:
\[
P(Y>y) = \lim_{x\to 0^+}P(Y>y,X>x) = \bar{F}_1\bigl(\beta(0)y\bigr).
\]
Now, the density of $Y$ is:
\[
f_Y(y) = -\frac{d}{dy}P(Y>y) 
= -\frac{d}{dy}\bar{F}_1(\beta(0)y)
= \beta(0)\,f_1(\beta(0)y),
\]
where $f_1(t)=-\bar{F}_1'(t)$ denotes the density associated with $\bar{F}_1$. Hence the marginal distribution of $Y$ belongs to the same family as $\bar{F}_1$, but with its argument scaled by $\beta(0)$. For \eqref{eq: general joint} to be a valid survival function, it must have a non-negative 
mixed partial derivative. Denoting $f_0$ and $f_1$ as the densities corresponding to the survival function $\bar{F}_0$ and $\bar{F}_1$, and differentiating, we obtain:
\begin{align}
 \frac{\partial}{\partial x} \frac{\partial}{\partial y} P(X>x, Y>y) &= 
f_0(x) f_1(\beta(x) y)\beta(x)
- \bar{F}_0(x) f_1'(\beta(x) y) \beta(x) \beta'(x) y
- \bar{F}_0(x) f_1(\beta(x) y) \beta'(x) \nonumber \\
&= f_0(x) f_1(\beta(x) y)\beta(x)
- \beta'(x) \bar{F}_0(x) \left[ f_1(\beta(x) y) + f_1'(\beta(x) y) \beta(x) y\right]. \nonumber
\end{align}
Denoting $t = \beta(x)y$, we have:
\begin{align}
 \frac{\partial}{\partial x} \frac{\partial}{\partial y} P(X>x, Y>y) 
&= f_0(x) f_1(t)\beta(x)
- \beta'(x) \bar{F}_0(x) \left[ f_1(t) + f_1'(t)t\right] \nonumber \\
& = f_0(x) f_1(t)\beta(x)
- \beta'(x) \bar{F}_0(x) \left[ t f_1(t) \right]' .\nonumber 
\end{align}
Thus a necessary and sufficient condition for $ \frac{\partial}{\partial x} \frac{\partial}{\partial y} P(X>x, Y>y) \geq 0$ is:
\[
\beta'(x)\;\begin{cases}
\le\; \dfrac{f_0(x)}{\bar F_0(x)}\;\dfrac{f_1(t)}{[t f_1(t)]'}\;\beta(x), & \text{if } [t f_1(t)]'>0,\\[10pt]
\ge\; \dfrac{f_0(x)}{\bar F_0(x)}\;\dfrac{f_1(t)}{[t f_1(t)]'}\;\beta(x), & \text{if } [t f_1(t)]'<0, \\
\text{unconstrained}, & \text{if } [t f_1(t)]'=0.
\end{cases}
\]
Denoting the hazard function $h_0(x) = \frac{f_0(x)}{\bar{F}_0(x)}$ and $S(t) = \frac{f_1(t)}{[t f_1(t)]'}$, we may write the bounds as such:
\begin{align}
\sup_{t: [t f_1(t)]'<0} h_0(x) S(t)\beta(x) 
\;\leq\; \beta'(x) 
\;\leq\;
\inf_{t: [t f_1(t)]'>0} h_0(x) S(t)\beta(x). \label{eq: B'(x) bounds}
\end{align}
A special case of the upper bound for $B'(x)$ arises for distribution families satisfying $f_1'(t) \leq0$ - that is, for non-increasing densities. In this case, we note that $S(t) = \frac{f_1(t)}{\left[tf_1(t) \right]'} = \frac{f_1(t)}{f_1(t) + tf_1'(t) } \geq1$ for $t \geq 0$, hence $\beta'(x) 
\;\leq\;
 h_0(x)\beta(x)$.\\

It should be noted that multiple functional forms for $\beta(x)$ are possible. The question of selecting a form of $\beta(x)$ that provides the best model fit has already been investigated by \citet{arnold2020bivariate}. Accordingly, the present study restricts attention to those choices of $\beta(x)$ that arise from the extreme case in which $\beta'(x)$ attains its theoretical upper bound, that is, given $\inf_{t: [t f_1(t)]'>0} S(t) = c^*$:
\begin{align}
 \beta'(x) &= c^*h_0(x) \beta(x), \nonumber \\
 \therefore \int \frac{1}{\beta(x)} d\beta(x) &= \int c^* h_0(x) dx, \nonumber\\
 \therefore \log\left( \beta(x) \right) &= -c^* \log\left( \bar{F}_0 (x)\right) + K. \nonumber \\
 \therefore \beta(x) &= \gamma \frac{1}{\left[\bar{F}_0(x)\right]^{c^*}}, \label{eq: beta(x) general}
 \end{align}
for $\gamma = e^K>0$. This suggests $\beta(x)$ is non-decreasing for $c^*>0$. Furthermore, $\beta(0): = \lim_{x\to 0^+} \beta(x) = \gamma$ since $\lim_{x\to 0^+}\bar{F}_0(x) = 1$. We also note that since $\bar{F}_0(x)$ approaches zero only as $x\rightarrow \infty$, the expression in \eqref{eq: beta(x) general} remains finite for all finite $x$.\\

The role of the acceleration function $\beta(x)$ in determining the sign of the correlation between $X$ and $Y$ is established in Theorem~\ref{thm: cov(x, y)}. In particular, since the present study considers only non-decreasing specifications of $\beta(x)$, the resulting framework is restricted to modelling data in which $X$ and $Y$ exhibit negative correlation.

\subsection{Moments}
Noting $X \sim Weibull(\alpha, \lambda)$ and $Y \sim Weibull(\gamma, \nu)$, we have:
\begin{align}
 E(X) &= \frac{1}{\alpha} \Gamma\left(1+ \frac{1}{\lambda}\right), \label{eq: Weibull ex} \\
 E(Y) &= \frac{1}{\gamma} \Gamma\left(1+ \frac{1}{\nu}\right), \label{eq: Weibull ey} \\
 {Var}(X) &= \frac{1}{\alpha^2}\left( \Gamma\left( 1+ \frac{2}{\lambda}\right) - \left(\Gamma\left(1+\frac{1}{\lambda}\right)\right)^2 \right),\label{eq: Weibull varx} \\
 {Var}(Y) &= \frac{1}{\gamma^2}\left( \Gamma\left( 1+ \frac{2}{\nu}\right) - \left(\Gamma\left(1+\frac{1}{\nu}\right)\right)^2 \right).\label{eq: Weibull vary} 
\end{align}
Accordingly:
\begin{align}
\operatorname{Cov}(X, Y) 
&= \int_0^\infty \int_0^\infty 
 \big( P(Y>y , X> x) - P(X> x)P(Y> y) \big) \,dy\,dx \nonumber \\
&= \int_0^\infty \int_0^\infty 
 \bar{F}_0(x) \left( \bar{F}_1\bigl(\beta(x)y\bigr) - \bar{F}_1\bigl(\beta(0)y\bigr) \right) \,dy\,dx \nonumber \\
&= \int_0^\infty e^{-(\alpha x)^\lambda}
 \left( \int_0^\infty \left( e^{-(\beta(x)y )^\nu}- e^{-(\beta(0)y )^\nu} \right) dy \right) dx \nonumber \\
&= \int_0^\infty e^{-(\alpha x)^\lambda}
 \left( \frac{\Gamma\!\left(1+\frac{1}{\nu}\right)}{\beta(x)} -\frac{\Gamma\!\left(1+\frac{1}{\nu}\right)}{\beta(0)} \right) dx \nonumber \\
&= \frac{1}{\gamma } \Gamma\!\left( 1+ \frac{1}{\nu}\right) 
 \left[\int_0^\infty e^{-(\alpha x)^\lambda - \frac{1}{\nu}(\alpha \tau x)^\lambda} \, dx 
 - \int_0^\infty e^{-(\alpha x)^\lambda} \, dx \right] \nonumber \\
&= \frac{1}{\alpha \gamma} \Gamma\!\left(1+ \frac{1}{\nu} \right)\Gamma\!\left(1+ \frac{1}{\lambda} \right)
 \left[ \left(\frac{\nu}{\nu + \tau^\lambda} \right)^{\frac{1}{\lambda}} - 1 \right].
\label{eq: Weibull cov}
\end{align}
Now, using \eqref{eq: Weibull varx}, \eqref{eq: Weibull vary} and \eqref{eq: Weibull cov}, the correlation function is:
\begin{align}
 \rho(X,Y)
 &= \frac{\operatorname{Cov}(X,Y)}{\sqrt{\operatorname{Var}(X)\operatorname{Var}(Y)}} \nonumber\\
 &= \frac{\Gamma\left(1+ \frac{1}{\nu} \right)\Gamma\left(1+ \frac{1}{\lambda} \right)\left[ \left(\frac{\nu}{\nu + \tau^\lambda} \right)^{\frac{1}{\lambda}} - 1 \right]}{\sqrt{\left( \Gamma\left( 1+ \frac{2}{\lambda}\right) - \left(\Gamma\left(1+\frac{1}{\lambda}\right)\right)^2 \right)\left( \Gamma\left( 1+ \frac{2}{\nu}\right) - \left(\Gamma\left(1+\frac{1}{\nu}\right)\right)^2 \right)}}.
 \label{eq: Weibull rho}
\end{align}
Clearly, \eqref{eq: Weibull rho} is strictly decreasing in $\tau \in [0, 1]$. Hence:
\begin{align}
 \rho_{\text{min}}(\lambda, \nu):=\frac{\Gamma\left(1+ \frac{1}{\nu} \right)\Gamma\left(1+ \frac{1}{\lambda} \right)\left[ \left(\frac{\nu}{\nu + 1} \right)^{\frac{1}{\lambda}} - 1 \right]}{\sqrt{\left( \Gamma\left( 1+ \frac{2}{\lambda}\right) - \left(\Gamma\left(1+\frac{1}{\lambda}\right)\right)^2 \right)\left( \Gamma\left( 1+ \frac{2}{\nu}\right) - \left(\Gamma\left(1+\frac{1}{\nu}\right)\right)^2 \right)}} \leq \rho(X, Y) \leq 0.
\end{align}
Now, $\inf_{\lambda, \nu > 0} \rho_{\text{min}}(\lambda, \nu) = \lim_{\nu \to \infty}\rho_{\text{min}}(\lambda = 1, \nu) = -\frac{\sqrt{6}}{\pi}$. Hence, this Weibull model with acceleration function $\beta(x) = \gamma e^{\frac{1}{\nu}(\alpha \tau x)^\lambda}$ will be able to accommodate correlations in the range $\rho(X,Y)\in\big[-\tfrac{\sqrt{6}}{\pi},\,0\big]$.

