\begin{proof}
Since $P(Y>y , X> x) = \bar{F}_0(x)\bar{F}_1\bigl(\beta(x)y\bigr)$ then $P(Y>y) = \lim_{x\to 0^+}P(Y>y , X> x) = \bar{F}_0(0)\bar{F}_1\bigl(\beta(0)y\bigr) = \bar{F}_1\bigl(\beta(0)y\bigr)$ since $\lim_{x\to 0^+}\bar{F}_0(x) = 1$ and $\beta(0): = \lim_{x\to 0^+} \beta(x)$. We note from Hoeffding's covariance identity:
\begin{align}
    Cov(X, Y) & = \int_0^\infty \int_0^\infty\left( P(Y>y , X> x) - P(X> x)P(Y> y)   \right) \ dx dy \nonumber \\
    & = \int_0^\infty \int_0^\infty  \bar{F}_0(x) \left( \bar{F}_1\bigl(\beta(x)y\bigr) - \bar{F}_1\bigl(\beta(0)y\bigr)  \right) \ dx dy.\nonumber 
\end{align}
Now since $\bar{F}_1'(\cdot)\le 0$ (as $\bar{F}_1$ is a survival function), if $\beta'(x) \geq 0$ then $\bar{F}_1\bigl(\beta(x)y\bigr) \leq \bar{F}_1\bigl(\beta(0)y\bigr)$ and $Cov(X, Y) \leq 0$ for $x, y \geq 0$. Conversely, if $\beta'(x) \leq 0$ then $\bar{F}_1\bigl(\beta(x)y\bigr) \geq \bar{F}_1\bigl(\beta(0)y\bigr)$ and $Cov(X, Y) \geq 0$ for $x, y \geq 0$. Finally, if $\beta(x)$ is constant, say $\beta(x)\equiv c$, then $P(X>x,Y>y)=\bar F_0(x)\,\bar F_1(cy)=P(X>x)\,P(Y>y)$, so $X$ and $Y$ are independent and ${Cov}(X,Y)=0$.
\end{proof}
Furthermore, as done in \citet{arnold2020bivariate}, we introduce a dependence parameter $\tau$ which controls the strength of the dependence between $X$ and $Y$. Extending from \eqref{eq: beta(x) general}, we define the acceleration function as such:
\begin{align}
    \beta(x) &= \gamma \frac{1}{\left[\bar{F}_0(\tau x)\right]^{c^*}}. \label{eq: beta(x) general 2}
\end{align}
Given the bounds established in \eqref{eq: B'(x) bounds}, and upon selecting a non-decreasing specification for $\beta(x)$ as defined in \eqref{eq: beta(x) general 2}, and again assuming $\inf_{t: [t f_1(t)]'>0} S(t) = c^* > 0$, we obtain bounds for $\tau$ as such:
\begin{align}
    0 &\leq \beta'(x) \leq c^* h_0(x)\, \beta(x), \nonumber\\
    \therefore  
    0 &\leq 
    \frac{c^* \tau \gamma f_0(\tau x)}{\big[\bar{F}_0(\tau x)\big]^{c^* + 1}} 
    \leq 
    c^* \gamma \, 
    \frac{f_0(x)}{\big[\bar{F}_0(x)\big]^{c^*}}
    \frac{1}{\big[\bar{F}_0(\tau x)\big]^{c^*}}, \nonumber\\
    \therefore  
    0 &\leq \tau \leq \frac{h_0(x)}{h_0(\tau x)}. \nonumber\end{align}
We re-write this inequality as such: 
\begin{align}
    0 \le r(x, \tau) \le 1,
    \label{eq: tau bounds}
\end{align}
where $r(x, \tau) = \tau \frac{h_0(\tau x)}{h_0(x)}$, where the endpoint $\tau=0$ is included by continuity, with $r(x,0):=\lim_{\tau\to 0^+}r(x,\tau)=0$. Theorem \ref{thm: ABC} and Theorems \ref{thm: ifr hazard} and \ref{thm: factor hazard} in Appendix \ref{app: thms}, serve as a basis for establishing bounds on the dependence parameter $\tau$ that satisfy \eqref{eq: tau bounds}.

\begin{theorem}
\label{thm: ABC}
Let $h_0:(0,\infty)\to(0,\infty)$ be a hazard function. For $x>0$ and $\tau>0$ define:
\[
r(x,\tau):=\tau\,\frac{h_0(\tau x)}{h_0(x)},\qquad 
\phi(x):=x\,h_0(x).
\]
Let
\[
A:\ \ 0\le r(x,\tau)\le 1\ \ \text{for all }x>0,\qquad
B:\ \ \tau\in(0,1],\qquad
C:\ \ \phi \text{ is non-decreasing on }(0,\infty).
\]
Then:
\begin{enumerate}
\item[(1)] $(A \wedge B)\ \Rightarrow\ C$.
\item[(2)] $(C \wedge B)\ \Rightarrow\ A$.
\item[(3)] $(C \wedge A)\ \Rightarrow\ B$, \emph{unless} $\phi$ is identically constant on $(0,\infty)$, in which case $A$ holds for all $\tau>0$ and $B$ cannot be inferred.
\end{enumerate}

\end{theorem}

\begin{proof}
\textbf{(1) $(A \wedge B)\Rightarrow C$.}
Fix $0<y<x$ and set $\tau:=y/x\in(0,1]$ so that $B$ holds. By $A$,
\[
1 \ \ge\ r(x,\tau)=\tau\,\frac{h_0(\tau x)}{h_0(x)}=\frac{y\,h_0(y)}{x\,h_0(x)}.
\]
Hence $y\,h_0(y)\le x\,h_0(x)$ for all $0<y<x$, i.e.\ $\phi$ is non-decreasing. Thus $C$ holds.

\medskip
\textbf{(2) $(C \wedge B)\Rightarrow A$.}
Assume $C$ and $\tau\in(0,1]$. Then $\tau x\le x$ and, by the non-decreasing nature of $\phi$,
\[
\phi(\tau x)\le \phi(x)\ \Longleftrightarrow\ \tau x\,h_0(\tau x)\le x\,h_0(x)
\ \Longleftrightarrow\ r(x,\tau)\le 1.
\]
Since $h_0>0$, we also have $r(x,\tau)\ge 0$. Hence $A$ holds.

\medskip
\textbf{(3) $(C \wedge A)\Rightarrow B$, unless $\phi$ is constant.} 
Assume $C$ and $A$ hold. Because $h_0(x)>0$, the lower bound $r(x,\tau)\ge 0$ implies $\tau \ge 0$. Now suppose, toward a contradiction, that $\tau>1$, then $\tau x > x$ and, by assuming $\phi$ is now strictly increasing:
\[
\phi(\tau x) > \phi(x)\ \Longleftrightarrow\ \tau x\,h_0(\tau x) > x\,h_0(x)
\ \Longleftrightarrow\ r(x,\tau) > 1.
\]
contradicting the upper bound. Hence $\tau \le 1$. If instead $\phi$ is identically constant,
say $\phi(x)\equiv K>0$, then $h_0(x)=K/x$ and
\[
r(x,\tau)=\tau\,\frac{K/(\tau x)}{K/x}=1 \quad (\forall x>0,\ \forall \tau>0),
\]
so $A$ holds for all $\tau>0$ and no restriction $B$ follows.
\end{proof}
\begin{remark} When convenient, extend $B$ to $\tau\in[0,1]$ by defining $r(x,0):=\lim_{\tau\to 0^+} r(x,\tau)=0$ (whenever the limit exists). All implications above then carry over with this convention.
\end{remark}
\begin{remark}
If $h_0$ is non-decreasing, then $\phi(x) =  x h_0(x)$ is non-decreasing (product of increasing, positive functions), so Theorem~\ref{thm: ABC} recovers Theorem \ref{thm: ifr hazard}.
If $h_0(x)=C\,x^{p-1}g(x)$ with $C>0$, $p\ge 0$, and $g(x)$ non-decreasing, then $\phi(x) = C x^pg(x)$ is non-decreasing, so Theorem \ref{thm: ABC} recovers Theorem \ref{thm: factor hazard}.
\end{remark}

The following sections present the range of models employed in this study. In each case, the survival function forms are specified according to a single particular rate-shape distributional family such that $X \sim Family (\alpha, \lambda)$ and $Y \sim Family (\beta(0), \nu)$ where $\alpha$ and $\beta(0)$ denote the rate parameters and $\lambda$ and $\nu$ denote the shape parameters (shape parameters are not applicable for exponential and half-Cauchy models, however). Closed-form expressions of the models' moments are derived, and additionally, theoretical correlation bounds are obtained (with the exception of the half-Cauchy and gamma models).

