ref_dict.def:ct:
\begin{definition}\label{def:ct}
{\em 
Let $(X,B)$ be log Calabi--Yau pair of dimension $n$. 
We say that $(X,B)$ is of {\em cluster type}
or that $(X,B)$ is a {\em cluster type pair} if there exists an embedding 
in codimension one 
\[
\mathbb{G}_m^n \dashrightarrow X\setminus B, 
\]
i.e., there exists a closed subset of codimension at least two $Z\subset \mathbb{G}_m^n$ 
and an embedding $\mathbb{G}_m^n\setminus Z \hookrightarrow X\setminus B$.
}
\end{definition}

theorem.content:
\label{thm: main thm}
    Suppose that the residue field of $K$ is algebraically closed and that every root of $F(x)$ is tamely ramified. Then, $\mathcal{D}(C/K)$ is not cofinite if and only if $v(F(0)) \not \equiv 0 \pmod q$, and for every Galois-invariant cluster $\mathfrak{s}$ of roots of $F(x)$,
    \begin{enumerate}[label=$(\roman*)$]
        \item $|\mathfrak{s}| \equiv 0 \pmod q$ and $c_{\mathfrak{s}} \not \equiv 0 \pmod{q}$, and
        \item if $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$, then $v(F(\gamma_{\mathfrak{s}})) \not \equiv 0 \pmod{q}$.
    \end{enumerate}
    When these conditions are satisfied, we have that
    \begin{align*}
        \mathcal{D}(C/K) \subseteq q\mathbb{N} \cup \bigcup_{\substack{ \mathfrak{s} \, \text{\rm not Galois} \\ \text{\rm invariant}}} |\mathcal{O}(\mathfrak{s})| \mathbb{N}.
    \end{align*}

ref_dict.rem: compute v(F(gamma)):
\begin{remark}\label{rem: compute v(F(gamma))}
    Define the \textbf{depth} of $\mathfrak{s}$ by $d_\mathfrak{s} \coloneqq \min_{\alpha, \alpha'} \val(\alpha - \alpha')$.  When $|{\mathfrak{s}}| > 1$ and $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$, we have that $\val(\gamma_{\mathfrak{s}} - \alpha_j) = d_{\mathfrak{s}}$, and hence $\val(F(\gamma_{\mathfrak{s}})) = |\mathfrak{s}| d_{\mathfrak{s}} +c_{\mathfrak{s}}$.
\end{remark}

ref_dict.defn: cluster:
\begin{definition}\label{defn: cluster}
    A \textbf{cluster} is a nonempty subset $\mathfrak{s} \subseteq \{\alpha_i\}$ of the form $\mathfrak{s} = D \cap \{\alpha_i\}$ for some disk $D_{z,\, d} = \{x \in \overline{K}\mid |x - z|\leq d\}$ for some $z \in \overline{K}$ and $d \in \mathbb{R}$.  Let $\mathcal{O}(\mathfrak{s})$ denote the orbit of $\mathfrak{s}$ as a set under $\text{Gal}(K^{\text{\rm sep}}/K)$, and let $\mathfrak{s}^c$ denote the complement of $\mathfrak{s}$ in $\{\alpha_i\}$.
\end{definition}

