$$J(r(1-s)u-rsv) < \mu_1(M)+\mu_1(\mathbb{B}^n)\qquad\text{for all \ }s\in[0,1]\text{ \ and \ }r\geq 0,$$ 
then the problem \eqref{scalar flat} has a least energy sign-changing solution.
\end{corollary}

