\Ensure  a lower bound on $\lambda_F$
\State $\mathcal{L}_{\text{periodic\_orbits}} \gets \textsc{FindPeriodicOrbits}(M, \varepsilon)$
\cmt{\textsc{FindPeriodicOrbits} return all periodic orbits of $T$ of length $\leq M$, approximated with error $\leq \varepsilon$}
\State $\text{bound} \gets -\infty$

\ForAll{$\text{orbit} \in \mathcal{L}_{\text{periodic\_orbits}}$}
    \State $\text{bound\_q} \gets \textsc{LowerBoundQ}(\text{orbit}, \varepsilon)$
