    \State $\text{orbit\_bound} \gets \uo{i=1}{\text{length}(\text{orbit})}{\sum} \inf \partial_s \varphi([\text{orbit}[i]-\varepsilon,\text{orbit}[i]+\varepsilon], \text{bound\_q}[i])$
    \cmt{\eqref{in_lf}}
    \State $\text{bound} \gets \max(\text{bound}, \text{orbit\_bound})$
