Thanks to Proposition~\ref{prop2.1}, we can compute a lower bound on the Lyapunov exponent of the transformation $T$ using the same method. For all $M\in\N^*$, \begin{align*}
    \lambda_u\geq \sup_{m\leq M}\sup_{x\in \text{Per}_m(\rz)}\frac{1}{m}\sum_{i=0}^{m-1}\log|T'(T^ix)|.
\end{align*}
However, the Lyapunov exponent of the transformation $T$ does not depend on $q$, making it easier to compute.

\subsection{Upper bound on the Lyapunov exponents}\label{s2.2}

This subsection presents a useful method for computing upper bounds on the Lyapunov exponents $\lambda_F$ and $\lambda_u$. These exponents are approximated by finding upper bounds of the Birkhoff sums of the functions $F$ and $\log |T'|$ on small intervals and using the expressions given in Corollary~\ref{coro2.2}.

\subsubsection{An expression of the Lyapunov exponents for computing an upper bound}

Corollary~\ref{coro2.2} provides an alternative expression for the Lyapunov exponents $\lambda_F$ and $\lambda_u$, which is useful for computing an upper bound on these exponents.

\begin{corollary}\label{coro2.2}
 Assume (H\ref{hyp4}). For all continuous functions $f:\RZ\to \mathbb{R}$, \begin{align}\label{abc}
        \sup_{\nu\in\mathcal{P}_T(\rz)}\int_{\rz} f(x) \,\mathrm{d}\nu(x)=\sup_{x\in\rz}\inf_{k\in\mathbb{N}^*}\frac{1}{k}\sum_{i=0}^{k-1} f(T^ix).
    \end{align}
In particular,
\begin{align*}
\lambda_F=\sup_{x\in\rz}\inf_{k\in\mathbb{N}^*}\frac{1}{k}\sum_{i=0}^{k-1} F(T^ix) \quad \text{and} \quad \lambda_u=\sup_{x\in\rz}\inf_{k\in\mathbb{N}^*}\frac{1}{k}\sum_{i=0}^{k-1} \log|T'(T^ix)|.
\end{align*}
\end{corollary}

\begin{proof}Let $f:\RZ\to \mathbb{R}$ be a continuous function.
    By Proposition~\ref{prop2.1}, \begin{align*}
        \sup_{\nu\in\mathcal{P}_T(\rz)}\int_{\rz} f(x) \,\mathrm{d}\nu(x)=\sup_{k\in\mathbb{N}^*}\sup_{x\in \text{Per}_k(\rz)}\frac{1}{k}\sum_{i=0}^{k-1}f(T^ix). 
    \end{align*} 
    Let $k\in\mathbb{N}^*$ and $x\in \text{Per}_k(\rz)$. By Pliss's lemma \cite[Lemma 11.8]{MR889254}, there exists $j\in\mathbb{N}$ such that \begin{align*}
        \frac{1}{k}\sum_{i=0}^{k-1}f(T^ix)= \inf_{n\in\mathbb{N}^*}\frac{1}{n}\sum_{i=0}^{n-1}f(T^{i+j}x)\leq\sup_{y\in\rz}\inf_{n\in\mathbb{N}^*}\frac{1}{n}\sum_{i=0}^{n-1} f(T^iy).
    \end{align*}
    Having established that \begin{align*}
        \sup_{\nu\in\mathcal{P}_T(\rz)}\int_{\rz} f(x) \,\mathrm{d}\nu(x)\leq\sup_{x\in\rz}\inf_{k\in\mathbb{N}^*}\frac{1}{k}\sum_{i=0}^{k-1} f(T^ix),
    \end{align*}
    it remains to prove the converse inequality to obtain Equality~\eqref{abc}. It is a direct corollary of the semi-uniform ergodic theorem \cite[Theorem 1.9]{MR1734626}. The equalities on $\lambda_F$ and $\lambda_u$ follow from the continuity of the functions $F$ and $\log |T'|$ (see Lemma~\ref{lmc}), and from Proposition~\ref{proplf}.
\end{proof}

\subsubsection{Effective upper bound on the Lyapunov exponents}\label{eff}

Computing an upper bound for the Lyapunov exponent $\lambda_F$ requires three steps, which are described in the next three paragraphs. First, we find a constant $K<1$ such that $K\geq q(x)$ for all $x\in\RZ$. Second, we compute an upper bound on $q$ using the expression $\varphi^{(n)}(x,K)$ with $n$ large. Finally, we compute an upper bound for the Lyapunov exponents using the upper bound on $q$ and the expression for the Lyapunov exponent $\lambda_F$ given in Corollary~\ref{coro2.2}.

\paragraph{Upper bound on $K$}~

In the uniformly supercritical case, there exists a constant $K<1$ such that $K\geq q(x)$ for all $x\in\RZ$ \cite[Lemma~4.1.1]{morand2024galtonwatsonprocessesdynamicalenvironments}. Lemma~\ref{lem2.1} justifies using the function $x\mapsto \varphi^{(n)}(x,K)$ with $n$ large as an upper bound on $q$.

\begin{lemma}\label{lem2.1}
Assume (H\ref{hyp4}). Let $K<1$ be such that $K\geq q(x)$ for all $x\in\RZ$. Then:\begin{itemize}
    \item For all $n\in\N$ and $x\in\RZ$, $\varphi^{(n)}(x,K)\geq q(x)$.
    \item The sequence of functions $(x\mapsto\varphi^{(n)}(x,K))_{n\in\mathbb{N}}$ converges uniformly to $q$.
\end{itemize}
\end{lemma}

\begin{proof}As $K<1$, the uniform convergence of this sequence of functions is proved by \cite[Corollary~4.1.2]{morand2024galtonwatsonprocessesdynamicalenvironments}.
Let $x\in\RZ$ and $n\in\mathbb{N}$.
As $s\mapsto \varphi^{(n)}(x,s)$ is increasing and by Proposition \ref{prop1},
\begin{align*}
    \varphi^{(n)}(x,K)&\geq\varphi^{(n)}(x,q(T^nx))=q(x).\qedhere
\end{align*}
\end{proof}

We need to find a suitable $K<1$. If there exists $N\in\N^*$ such that, for all $x\in\RZ$, $\varphi^{(N)}(x,K)\leq K$, then $K$ is suitable. However, we may choose a value of $N$ depending on $x$ by Lemma~\ref{lem_k2}.

\begin{lemma}\label{lem_k2}
Assume $(H\ref{hyp4})$. Let $K<1$ be such that for all $x\in\RZ$, there exists $N_x\in\N^*$ such that $\varphi^{(N_x)}(x,K)\leq K$. Then, $q(x)\leq K$ for all $x\in\RZ$.
\end{lemma}

\begin{proof}
Let $x\in\RZ$. We define a sequence of positive integers $(n_i)_{i\in\N}$ by the following induction relation:
\begin{align*} 
\left\{\begin{array}{ll}
  & n_0=N_x, \\
  & n_{i+1}=N_{T^{n_0+\ldots+n_i}x} \text{ for all } i\in\N.
   \end{array}\right.
\end{align*}
Then for all $i\in\N$,
\begin{align*}
    \varphi^{(n_0+\ldots+n_i)}(x,K)&=\varphi^{(n_0)}(x,\varphi^{(n_1)}(T^{n_0}x,\ldots,\varphi^{(n_i)}(T^{n_0+\ldots+n_{i-1}}x,K)\ldots)\leq K, 
\end{align*}
by induction, thanks to the definition of the sequence $(n_i)_{i\in\N}$. By \cite[Corollary~4.1.2]{morand2024galtonwatsonprocessesdynamicalenvironments}, \begin{align*}
    \varphi^{(n_0+\ldots+n_i)}(x,K)\underset{i\to +\infty}{\longrightarrow} q(x).
\end{align*} So, $q(x)\leq K$.
\end{proof}

\begin{remark}\label{rem2}
    In practice, it is sometimes difficult to check if a process is in the uniformly supercritical regime. However, Lemma~\ref{lem_k2} gives a sufficient condition for this to be the case.
\end{remark}

By Lemma~\ref{lem_k2}, we can certify whether a constant $0<C<1$ is an upper bound on $q$. This method is used in Algorithm~\ref{alg_K}. The algorithm returns true if it is verified that $C$ is an upper bound on $q$. It returns false if it is not verified (note that this does not necessarily imply that $C$ is not an upper bound of $q$).

\begin{algorithm}[H]
\caption{Verify whether $C$ is an upper bound on $\sup_{x\in\mathbb{R}} q(x)$}
\label{alg_K}
\begin{algorithmic}[1]
\Require $0 < C < 1$, integer $n_{\max} \geq 0$
\Ensure \texttt{True} if it is verified that $C \geq \sup_{x \in \mathbb{R}} q(x)$, \texttt{False} otherwise

\State Let $\mathcal{L}_{\text{interval}} \gets \{ [0, 1] \}$
\For{$i = 1$ to $n_{\max}$}
    \State Let $\mathcal{L}_{\text{new}} \gets$ empty list
    \cmt{$\mathcal{L}_{\text{new}}$ is the list of intervals after an iteration}
    \ForAll{$I \in \mathcal{L}_{\text{interval}}$}
        \If{for all $j = 1$ to $\left\lfloor \frac{i}{2} \right\rfloor + 1$, we have $\sup \varphi^{(j)}(I, C) > C$}
            \State Let $I_1, I_2 \gets \textsc{Split}(I)$
            \cmt{\textsc{Split} divides an interval into two intervals of the same size}
            \State Append $I_1$ and $I_2$ to $\mathcal{L}_{\text{new}}$
        \EndIf
    \EndFor
    \State $\mathcal{L}_{\text{interval}} \gets \mathcal{L}_{\text{new}}$
    \If{$\mathcal{L}_{\text{interval}}$ is empty}
        \State \Return \texttt{True}
    \EndIf
\EndFor
\State \Return \texttt{False}
\end{algorithmic}

pre_theorem_intro_text:
Understanding the regularity of invariant graphs is a central issue in the study of skew product systems \cite{MR1605989,MR1677161,MR1898800,MR3816739}. From a numerical point of view, their regularity can often be estimated by controlling Lyapunov exponents.
The numerical estimation of Lyapunov exponents has been investigated in several contexts, 
notably for random matrix products \cite{MR4014663,MR4304495}, 
for iterated function systems contracting on average \cite{MR1751564}, 
and for interval transformations \cite{MR2430654,MR4538289} 
(including maps with critical points, discontinuities, or unbounded derivatives).

In this article, we focus on a model close to skew products, arising from the study of 
Galton--Watson processes in dynamical environments in the uniformly supercritical case introduced in 
\cite{morand2024galtonwatsonprocessesdynamicalenvironments}. 
The invariant function of this model represents the probability of extinction. 
We express the Hölder regularity of this invariant function as a ratio between two Lyapunov exponents. 
The main numerical difficulty in controlling the regularity of the invariant graph lies in the fact that the Lyapunov exponent in the fibre direction depends on the invariant function itself.

\subsection*{Numerical bounds on the Lyapunov exponent in the fibre}

We consider a $\mathcal{C}^1$ uniformly expanding transformation of the circle $T:\RZ\to\RZ$, and a continuous application $\varphi:\RZ\times[0,1]\to[0,1]$. Moreover, we assume that for all $x\in\RZ$, the function $s\mapsto\varphi(x,s)$ is analytic on $[0,1)$, increasing, convex, and that $\varphi(x,1)=1$. We denote by $\partial_s\varphi$ the derivative of $\varphi$ with respect to the second variable and by $\partial_x\varphi$ the derivative of $\varphi$ with respect to the first variable if it is well defined. For all $n\in\mathbb{N}$, we define $\varphi^{(n)}:\RZ\times[0,1]\to[0,1]$ by induction: for all $x\in\RZ$ and $s\in[0,1]$, \begin{align*}
\varphi^{(n)}(x,s)\vcentcolon=
\left\{\begin{array}{ll}
    & s \text{ if } n=0,\\
    & \varphi(x,\varphi^{(n-1)}(Tx,s)) \text{ otherwise.}
    \end{array}
    \right.
    \end{align*}
We consider the solutions $f:\RZ\to[0,1]$ of the functional equation: \begin{align}\label{invgraph}
     f(x)=\varphi(x,f(Tx)).
\end{align}
The constant function equal to $1$ is a solution of \eqref{invgraph}. We denote by $q$ the smallest solution of this functional equation. This model is closely related to models of invariant graphs of skew product systems, as presented in references \cite{MR1605989,MR1677161,MR1898800,MR3170606,MR3816739}. See \cite[Subsection 1.4]{morand2024galtonwatsonprocessesdynamicalenvironments} for details of the connections. \begin{remark}
     If we consider an invertible transformation of the circle instead of an uniformly expanding transformation, we would recover exactly a skew product system by considering the dynamics in the past. Let $\Psi$ be defined by: \fonction{\Psi}{\RZ\times [0,1]}{\RZ\times [0,1]}{(x,s)}{(T^{-1}x,\varphi(T^{-1}x,s))}
Then, for all $x\in\RZ$, $n\in\mathbb{N}$, and $s\in[0,1]$, 
\begin{align*}
    \Psi^n(x,s)=(T^{-n}x,\varphi^{(n)}(T^{-n}x,s)).
\end{align*}
\end{remark}
We refer to $q$ as the invariant function of the system $(\varphi,T)$ by analogy with models of invariant graphs of skew product systems. 

In this article, we study two Lyapunov exponents: \begin{itemize}
    \item the Lyapunov exponent of the invariant function $q$ in the fibre direction:
  \begin{align}\label{lf}
      \lambda_F&\vcentcolon=\lim_{n\to\infty}\frac{1}{n}\sup_{x\in\mathbb{R}/\mathbb{Z}}\log(\partial_s\varphi^{(n)}(x,q(T^n x))),
      \end{align}    
    \item the Lyapunov exponent of the transformation $T$:
  \begin{align}\label{lu}
    \lambda_u\vcentcolon=\lim_{n\to\infty}\frac{1}{n}\sup_{x\in\mathbb{R}/\mathbb{Z}}\log(|(T^n)'(x)|). 
  \end{align}\end{itemize}

  We obtain rigorous numerical bounds on these Lyapunov exponents. The difficulty lies in the fact that the Lyapunov exponent in the fibre depends on the invariant function, which is not explicit and may have low and unknown regularity. According to the specification property \cite[Corollary~5]{MR718829}, to obtain a lower bound on the Lyapunov exponent in the fibre, it is sufficient to have a lower bound on the invariant function only along the periodic orbits Proposition~\ref{prop2.1}. We then estimate the periodic orbits of $T$ of length at most some $M\in\mathbb{N}$. Corollary~\ref{coro2.2} allows us to obtain an upper bound on the Lyapunov exponent in the fibre. We first need to obtain an upper bound on the invariant function using arithmetic intervals and Lemma~\ref{lem2.1}.

 It is easier to control the Lyapunov exponents of the transformation and previous work has been done in more complicated cases \cite{MR2430654,MR4538289}.

  All the code has been written in the Julia programming language and is available on GitHub\footnote{\href{https://github.com/thomas-morand/holder_regularity_of_invariant_graph}{Link to code: https://github.com/thomas-morand/holder\_regularity\_of\_invariant\_graph}}.

 \subsection*{Application to the probability of extinction of Galton-Watson processes in dynamical environments in the uniformly supercritical case}

We apply these results to study the model of Galton-Watson processes in dynamical environments defined in \cite{morand2024galtonwatsonprocessesdynamicalenvironments}. These are Galton-Watson processes (stochastic branching processes in which each individual in a generation produces a random number of offspring) in which the law of reproduction varies between generations according to a dynamical system. We consider a $\mathcal{C}^1$ uniformly expanding transformation of the circle $T:\RZ\to\RZ$ together with a continuous function $x\in\RZ\mapsto \mu_x\in\mathcal{P}(\mathbb{N})$, called the law of reproduction of the Galton-Watson process in dynamical environments (a function that associates a probability on $\mathbb{N}$ to each $x\in\RZ$). The law of reproduction of the Galton–Watson process in dynamical environments with initial environment $x\in\RZ$ at generation $n\in\mathbb{N}$ is $\mu_{T^nx}$, i.e., the law of reproduction between generations evolves under the action of $T$. For a fixed $x\in\RZ$, the process is a Galton-Watson process in varying environments, as studied in particular in \cite{MR0368197,MR0365733,MR2384553,MR4094390}. We denote by $(Z_n(x))_{n\in\mathbb{N}}$ the Galton–Watson process in dynamical environment with initial environment $x\in\RZ$ and where for all $n\in\mathbb{N}$, $Z_n(x)$ represents the size of the population at the $n$th generation.
To study this model, we use the probability generating function of the law of reproduction $\mu$, defined on $\RZ\times [0,1]$ by:
\begin{align*}
    \varphi(x,s) \vcentcolon= \sum_{k=0}^{+\infty} \mu_x(k)s^k.
\end{align*}
Moreover, for all $n\in\mathbb{N}$ and $x\in\RZ$, we consider the probability generating function of the random variable $Z_n(x)$, defined for all $s\in[0,1]$ by:
\begin{align*}
    \varphi^{(n)}(x,s) \vcentcolon=  \mathbb{E}[s^{Z_n(x)}].
\end{align*}
The probability of extinction $q:\RZ\to[0,1]$ is a function that associates to each $x\in\RZ$ the probability of extinction of the Galton-Watson process in dynamical environments with the initial environment $x$, i.e., with law of reproduction $(\mu_{T^nx})_{n\in\mathbb{N}}$. When $q(x)=1$, there is almost certain extinction of the process, and we say that $x\in\RZ$ is a bad environment.

We are therefore in the context of the model described in the first part of the introduction, and the probability of extinction $q$ is the smallest solution of the functional equation~\eqref{invgraph}, it is thus the invariant function of our model. If, for all ergodic probability measures, the survival probability is positive for $\nu$-almost all $x\in\RZ$, then we are in the uniformly supercritical case. In this setting, Theorem~\ref{thm2.2} shows that the H\"older regularity and the differentiability class of $q$ are controlled by the ratio $\frac{|\lambda_F|}{\lambda_u}$.

