The post-theorem introduction states that the proof of the main theorem \emph{“strongly relies on a scalar algebraic identity”}
\begin{equation}
\label{eq: identita_fondamentale}
\|w(p, f, g)\|^2_{L^2(\Omega;\C)} + \|\widetilde{w}(p, f, g)\|^2_{L^2(\Omega;\C)}  = \|f\|^p_{L^p(\Omega;\C)} + (p - 1)\|g\|^p_{L^p(\Omega;\C)} - p\Re(|g|^{p-2}g, f)_{L^2(\Omega;\C)},
\end{equation}
which yields the positivity estimate
\begin{equation}\label{eq:scalar-positivity}
	\|f\|_{L^p(\Omega;\C)}^p + (p-1) \|g\|_{L^p(\Omega;\C)}^p -p\Re (|g|^{p-2}g,f)_{L^2(\Omega; \C)}\geq 0,
	\qquad f,g\in L^p(\Omega;\C).
\end{equation}
