 \left\|\partial_{x}^{l} u_{0}\right\|_{L^{2}\left(\left(x_{0}, \infty\right)\right)}^{2}=\int_{x_{0}}^{\infty}\left|\partial_{x}^{l} u_{0}(x)\right|^{2} d x<\infty,
 \end{equation}
 then for any $v \geq 0, \epsilon>0$ and $R>0$ hold the following statements for the solutions $u(t)$ on $[0,T]$ of the IBVP \eqref{IBVP} given by Theorem \ref{katot}:
 \begin{itemize}
\item[(a)] (Propagation of regularity) There exists $C>0$ such that
 $$
 \sup _{0 \leq t \leq T^*} \int_{\max\{ x_{0}+\epsilon-v t,0\}}^{\infty}\left(\partial_{x}^{j} u\right)^{2}(x, t) d x<C,
 $$
 where $T^*=T$ if $j=1$ and $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$; $j=2, \ldots, l$.
 In particular, for all $t \in(0, T^*]$, the restriction of $u(\cdot, t)$ to any interval $\left(x_{0}, \infty\right)$ belongs to $H^{l}\left(\left(x_{0}, \infty\right)\right)$.
\item[(b)] (Kato smoothing effect) For any $v\geq 0$, $\epsilon>0$, $R>0$ and $T^*=T$ if $j=1$ and $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$; $j=2, \ldots, l$.
 $$
 \int_{0}^{T^*} \int_{\max\{ x_{0}+\epsilon-v t,0\}}^{x_{0}+R-v t}\left(\partial_{x}^{l+1} u\right)^{2}(x, t) d x d t<C.
 $$

{The estimates of $I_1$ and $I_2$ follow from the arguments in \cite{Isaza}.} In addition, for the $I_3$ term we have 
\begin{align*}
 I_3 &= \intr (\partial_xu)^3 \chi_{\epsilon,b}(x+v t-x_0)\,dx + \intr u \partial_x^2 u \partial_xu \chi_{\epsilon,b}(x+v t-x_0) \,dx \\
 &= \frac12\intr (\partial_xu)^3 \chi_{\epsilon,b}\,dx-\frac12 \intr u(\partial_xu)^2\chi_{\epsilon,b}'dx-\frac12 u(0,t)(\partial_xu(0,t))^2\chi_{\epsilon,b}(vt-x_0)\\
 &:= I_{3_1} + I_{3_2} -\frac12 f(t)(\partial_xu(0,t))^2\chi_{\epsilon,b}(vt-x_0).
\end{align*}
These first two terms above can be controlled in the following way
\begin{equation}
 |I_{3_1}| \leq \|\partial_xu \|_{L^{\infty}(\mathbb R^+)} \intr (\partial_x u)^2 \chi_{\epsilon,b}(x+vt-x_0) \,dx 
\end{equation}
and
\begin{equation}
 |I_{3_2}| \leq \|u(t)\|_{L^{\infty}(\mathbb R^+)} \intr (\partial_x u)^2 \chi_{\epsilon,b}'(x+vt-x_0) \,dx. \tag{3.6}
\end{equation}
Hence, by Sobolev embedding and (3.2) after integrating in the time interval $[0,T]$ one gets
\begin{equation}
 \int_0^T |I_{3_2}| \,dt \leq \sup_t \|u(t)\|_{H^{3/4 +}(\R^+)} \int_0^T \intr (\partial_x u)^2 \chi_{\epsilon,b}'(x+vt-x_0) \,dx dt \leq C_0. \tag{3.7}
\end{equation}
It follows that
\begin{equation}
\begin{split}
\sup _{0 \leq t \leq T*} &\intr\left(\partial_{x} u\right)^{2} \chi_{ \epsilon, b}(x+v t-x_0) d x+\int_{0}^{T^*} \intr\left(\partial_{x}^{2} u\right)^{2} \chi_{\epsilon, b}^{\prime}(x+v t-x_0) d x d t \\
&\leq C+\int_{0}^{T^*}\tau_1(t)dt,
\end{split}
\end{equation}
with $c=c(\epsilon ; b ; v;T^*)>0$ for any $\epsilon>0, b \geq 5 \epsilon, v>0$.

In order to control the antepenultimate term, we invoke the properties of the weighted function to get
\begin{equation}\label{l32e}
\begin{split}
 &\left|\intr\left(\partial_x^2 u\right)^3 \chi'_{\epsilon,b}(x+vt-x_0)dx\right| \\
 &\quad\leq\left\|{\partial}_x^2 u \chi_{ \epsilon, b}^{\prime}(\cdot+v t-x_0)\right\|_{L^\infty(\R^+)} \intr\left({\partial}_x^2 u\right)^2 \chi_{ \epsilon / 5, \epsilon}(x+v t-x_0) d x,
\end{split}
\end{equation}
where the last term is bounded, after integration in time, by the former case $l=2$. Next, we take care of the first term on the RHS of \eqref{l32e} as follows

Now we have that
 \begin{equation}\label{Hipl1}
 \left. u_0\right|_{(x_0, \infty)} \in H^{l+1}([x_0, \infty)). 
 \end{equation}
 Thus from the previous step $\eqref{HIl1}$ holds. Also formally we have for $\varepsilon>0, b \geq 5 \epsilon$, the identity
 \begin{align}\nonumber
 \frac{1}{2} & \frac{d}{d t} \intr\left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon, b}(x+v t-x_0) d x-\underbrace{v \intr\left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon, b}^{\prime}(x+v t-x_0) d x}_{I_1} \\\nonumber
 + & \frac{3}{2} \intr\left(\partial_x^{l+2} u\right)^2 \chi_{\epsilon, b}^{\prime}(x+v t-x_0) d x+\underbrace{\left(\partial_x^{l+2} u(0, t)\right)^2 \chi_{\epsilon, b}(v t-x_0)}_{I_2}\\\nonumber&\quad-\underbrace{\frac{1}{2} \intr\left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon, b}^{\prime \prime \prime}(x+v t-x_0) d x}_{I_3} \\\label{lcasel1}
 &\quad +\underbrace{\intr \partial_x^{l+1}\left(u {\partial}_x u\right) \partial_x^{l+1} u(x, t) \chi_{\epsilon, b}(x+v t-x_0) d x}_{I_4}+\tau_{l+1}(t)=0,
 \end{align}
 where the trace term $\tau_{l+1}(t)$ is given as
 \begin{equation}\label{tracel1}
 \begin{split}
 \tau_{l+1}(t)=&-\partial_x^{l+3} u(0, t) \partial_x^{l+1} u(0, t) \chi_{\epsilon, b}(v t-x_0) \\&\quad +\partial_x^{l+2} u(0, t) \partial_x^{l+1} u(0, t) \chi_{\epsilon,b}^{\prime}\left(v t-x_0\right)-\left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon, b}^{\prime \prime \prime}(v t-x_0). 
 \end{split}
 \end{equation}
 We observe that all the term on the LHS of $\eqref{lcasel1}$ can be treated as we did previously in the former cases. We also note that the trace term $\eqref{tracel1}$ is of order $l+1$ and can be estimated employing the argument used in the analysis of the cases $l=1$ and $l=2$, taking advantage of the properties of weighted function $\chi_{\epsilon,b}$. However, we illustrate the analysis of the nonlinear term $I_4$. In fact, we write
 \begin{align}\nonumber
 I_4= & \intr \partial_x^{l+1}\left(u \partial_x u\right) \partial_x^{l+1} u \chi_{\epsilon,b}(x+v t-x_0) d x \\\nonumber
 = & c_0 \intr u \left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon,b}^{\prime}(x+v t-x_0) d x \\\nonumber
 & +c_1 \intr \partial_x u\left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon,b}(x+v t-x_0) d x \\\nonumber
 & +c_2 \intr \partial_x^2 u \partial_x^l u \partial_x^{l+1} u \chi_{\epsilon,b}(x+v t-x_0) d x \\\label{A4l1}
 & -\left(\partial_x^{l+1} u(0,t)\right)^2 u(0,t) \chi_{\epsilon, b}(v t-x_0)+\sum_{k=3}^{l-1} c_k\intr \partial_x^{l+2-k} u \partial_x^{k} u \partial_x^{l+1} u \chi_{\epsilon,b}(x+v t-x_0) d x \\\nonumber
 := & I_{4,0}+I_{4,1}+I_{4,2}+ \tilde\tau_{l+1}(t)+\sum_{k=3}^{l-1} I_{4, k}.
 \end{align}

Finally, we see that
 \begin{align}\nonumber
 \left|I_{4, k}(t)\right|= & \left|\intr \partial_x^{l+2-k} u \partial_x^{k} u \partial_x^{l+1} u \chi_{\epsilon,b}(x+v t-x_0) d x\right| \\\nonumber
 \leq & \frac{1}{2} \intr\left(\partial_x^{l+2-k} u \partial_x^{k} u\right)^2 \chi_{\epsilon,b}(x+v t-x_0) d x \\\label{a4k}
 & +\frac{1}{2} \intr\left(\partial_x^{l+1} u\right)^2 \chi_{\epsilon,b}(x+v t-x_0) d x 
 \end{align}
 where the last term is the quantity to be estimated. We notice that $k$, $l+2-k \leq l-1$ so we obtain
\begin{align}\label{fina4k}
 &\left|\intr\left(\partial_x^{l+2-k} u \partial_x^{k} u\right)^2 \chi_{\epsilon,b}(x+v t-x_0) d x\right| \leq \nonumber\\
 &\qquad\left\|\left(\partial_x^{k} u\right)^2 \chi_{ \epsilon / 5, \epsilon}(\cdot+v t-x_0)\right\|_{L^\infty(\mathbb R^+)} \intr\left(\partial_x^{l+2-k} u\right)^2 \chi_{\epsilon,b}(x+v t-x_0) d x.
\end{align}

post_theorem_intro_text:
\begin{remark}
	The property \eqref{kato}, now known as Kato's smoothing effect, estimulated an extensive investigation of various smoothing properties associated with solving the KdV-equation and other dispersive wave equations. In fact, \eqref{kato} is crucial to obtain propagation of the regularity result for nonlinear dispersive equations in general (see the discussion in \cite{LPSmith}).
	\end{remark}

The following interesting questions arise naturally in this situation:

\begin{itemize}
\item Is it possible to get results of propagation of the regularity for the solutions of the IBVP on the level obtained in the context of IVP by Isaza, Linares and Ponce \cite{Isaza} in the context of half-lines?

\item What is the influence of the known boundary functions and the unknown traces $\partial_x^ku(0,t)$ to get this result?

\item Is it possible to get propagation for any time of the existence?

\item With the assumption of regularity on the portion of the half-line for the initial data, is there any gain of the regularity of the trace  functions if it compared with \eqref{reg-trace}?

\end{itemize}

In this work we investigate these questions. Our result is concerned with the propagation of regularity in the right hand side of the data for positive times. It affirms that this regularity moves with infinite
speed to its left as time evolves.

\begin{thm}\label{thm1}
 If $u_{0} \in H^{3 / 4^{+}}(\mathbb{R}^+)$ and $f\in H^{\frac{3}{2}^+}(\mathbb R^+)$ for some $l \in \mathbb{Z}^{+}, l \geq 1$ and $x_{0} \in \mathbb{R}^+$

	\begin{equation}\label{hipl}
	\left\|\partial_{x}^{l} u_{0}\right\|_{L^{2}\left(\left(x_{0}, \infty\right)\right)}^{2}=\int_{x_{0}}^{\infty}\left|\partial_{x}^{l} u_{0}(x)\right|^{2} d x<\infty,
	\end{equation}
	then  for any $v \geq 0, \epsilon>0$ and $R>0$ hold the following statements for the solutions $u(t)$ on $[0,T]$ of the IBVP \eqref{IBVP} given by Theorem \ref{katot}:
	\begin{itemize}
\item[(a)] (Propagation of regularity) There exists $C>0$ such that
	$$
	\sup _{0 \leq t \leq T^*} \int_{\max\{ x_{0}+\epsilon-v t,0\}}^{\infty}\left(\partial_{x}^{j} u\right)^{2}(x, t) d x<C,
	$$
	where $T^*=T$ if $j=1$ and $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$; $j=2, \ldots, l$.
	In particular, for all $t \in(0, T^*]$, the restriction of $u(\cdot, t)$ to any interval $\left(x_{0}, \infty\right)$ belongs to $H^{l}\left(\left(x_{0}, \infty\right)\right)$.
\item[(b)] (Kato smoothing effect)	For any $v\geq 0$, $\epsilon>0$, $R>0$ and $T^*=T$ if $j=1$ and $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$; $j=2, \ldots, l$.
	$$
	\int_{0}^{T^*} \int_{\max\{ x_{0}+\epsilon-v t,0\}}^{x_{0}+R-v t}\left(\partial_{x}^{l+1} u\right)^{2}(x, t) d x d t<C.
	$$

	\item[(c)] (Trace estimate) Additionally, for  $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$, we have the following estimate for the trace: 
	 \begin{equation}
	 \int_{\frac{b+x_0}{v}}^{T^*}(\partial_{x}^{2}u(0,t))^2d t\leq C.
	 \end{equation}

		\end{itemize}
		(The constant $C$ depends on the numbers  $\left\|u_{0}\right\|_{H^{{3/4}^{+}}(\mathbb R^+)}$ $\left\|\partial_{x}^{l} u_{0}\right\|_{L^{2}\left(\left(x_{0}, \infty\right)\right)}$, $\|f\|_{H^{\frac{3}{2}^+}(\mathbb R^+)},$ $l,$ $v$, $\epsilon$ and  $T$.)
\end{thm}

The argument of the proof initially follows the ideas of \cite{Isaza}, but we need to take care with the trace terms which in general are not controllable on the low regularity regime. The main ingredients are the use of some Kato smoothing effects combined with a interpolation inequality, which is essential to control some problematic traces terms.
 \begin{figure}[htp]\label{figure}
	\centering 
	\begin{tikzpicture}[scale=2.2]
