\subsection{The local Hardy space}\label{h1}
We recall in the section the definition of the local atomic Hardy space $\mathfrak{h}^1(S)$, which can be viewed as the analogue, in the setting of Damek--Ricci spaces, of the local Hardy space introduced by Goldberg in the Euclidean case \cite{G}. The local Hardy space was further developed and studied by Meda and Volpi \cite{MV} and by Taylor \cite{T} in more general contexts. It is straightforward to verify that Damek--Ricci spaces satisfy the geometric assumptions of \cite{MV} and \cite{T}, so that the corresponding theory applies to our setting.

A function $a$ in $L^1(S)$ is called a \emph{standard $\fh^1$-atom} if $a$ is  supported in a ball $B$ of radius less than $1$, and satisfies
\begin{enumerate}[(i)]
\item size condition: $\|a\|_{L^2(S)}\leq \rho(B)^{-1/2}$;
\item cancellation condition: $\int a \,\d\rho=0$. 
\end{enumerate}
A \emph{global $\fh^1$-atom} is a function $a$ in $L^1(S)$ supported in a ball $B$ of radius $1$ such that $\|a\|_{L^2(S)}\leq \rho(B)^{-1/2}$. Standard and global $\fh^1$-atoms will be referred to as \emph{admissible atoms}.
The Hardy space $\fh^1(S)$ is the space of functions $f$ in $L^1(S)$ such that $f=\sum_jc_ja_j$, where $\sum_j|c_j|<\infty$ and $a_j$ are admissible atoms. The norm $\|f\|_{\fh^1(S)}$ is defined as the infimum of $\sum_j|c_j|<\infty$ over all atomic decompositions of $f$. We now introduce several technical lemmas that will be useful in the subsequent analysis.

\begin{lemma}\label{lem2.7.0}
Let $T$ be a bounded linear operator on $L^2(S)$ with Schwartz kernel $K_T$, which satisfies the following two conditions: 
\begin{asparaenum}[(i)]
\item The local H\"{o}rmonder condition:
\begin{align*}
\sup_B\sup_{y,y'\in B}\int_{(2B)^c}|K_T(x,y)-K_T(x,y')|\,\d \rho(x)<\infty,
\end{align*}
where the first supremum is taken over all balls $B$ of radii at most $1$;
\item The size condition:
\begin{align*}
\sup_{y\in S}\int_{(B(y,2))^c}|K_T(x,y)|\,\d\rho(x)<\infty.
\end{align*}
\end{asparaenum}
Then, the operator $T$ is bounded from $\fh^1(S)$ to $L^1(S)$.
\end{lemma}
\begin{proof}
The proof is a combination of \cite[Theorem 8.2]{CaMaMe09} and \cite[Proposition 4.5 (ii)]{CaMaMe10}.
\end{proof}
Recall that the symbol class is defined by
\begin{align*}
\cS^\sigma=\left\{m\in C^\infty(\R):\|m\|_{\cS^\sigma,k}:=\sup_{\lambda\in\R}\,(1+\lambda^2)^{-{\sigma-k\over 2}}|m^{(k)}(\lambda)|\leq C_{\alpha,k}\text{ for all }k\in \mathbb{N}\right\}.
\end{align*}
\begin{lemma}\label{lem2.6}
Suppose that $m\in\cS^\sigma$ is an even symbol. Then the following statements hold.
\begin{asparaenum}[(i)]
\item If $\sigma=0$, then the multiplier $m(\L)$ is bounded from $\fh^1(S)$ to $L^1(S)$, and is bounded on $L^p(S)$ for all $1<p<\infty$.
\item If $\sigma=-1$, then the operator $|\nabla m(\L)\cdot|_\g$, where $\nabla$ denotes the Riemannian gradient on $S$, is bounded from $\fh^1(S)$ to $L^1(S)$, and from $L^p(S)$ to $L^p(S)$ for all $1<p<\infty$.
\end{asparaenum}
\end{lemma}

\begin{proof}
We briefly outline the proof of this lemma. Following the argument of \cite[Lemma A.1]{WaYa}, we obtain that the Schwartz kernel $K$ of any operator in (i) or (ii) satisfies
\begin{align*}
|K(x,y)|+|(\nabla K(x,\cdot))(y)|_\g
\lesssim \delta(xy)^{1\over 2}(d(x,y))^{-N} 
\quad\text{if }d(x,y)\geq 1,
\end{align*}
for any $N\in\mathbb{N}^*$, and
\begin{align*}
|(\nabla K(x,\cdot))(y)|_\g
\lesssim \delta(xy)^{1\over 2}(d(x,y))^{-n-1}
\quad\text{if } 0<d(x,y)\leq 1.
\end{align*}
Using Lemma \ref{lem2.2} and reasoning as in the proof of \cite[Lemma 2.11]{WaYa}, we verify that both the local Hörmander condition and the size condition are satisfied. Finally, a standard interpolation argument yields the $L^p$-boundedness.
\end{proof}

We conclude this section by recalling the following analytic interpolation property.

\begin{lemma}\label{lem2.7}
Denote by $\Sigma$ the closed strip $\{\zeta\in\mathbb{C}:\Re \zeta\in[0,1]\}$. Suppose that $\{T_\zeta\}_{\zeta\in\Sigma}$ is a family of uniformly bounded operators on $L^2(S)$ such that the map $\zeta \mapsto \int_G T_\zeta(f)\, g\,\d \rho$ is continuous on $\Sigma$ and analytic in the interior of $\Sigma$, whenever $f,g\in L^2(S)$. Moreover, assume that
\begin{align*}
\|T_\zeta f\|_{L^1(S)}\leq A_1\|f\|_{\fh^1(S)}\quad\text{for all }f\in L^2(S)\cap \fh^1(S) \text{ and }\Re\zeta=0,
\end{align*}
and
\begin{align*}
\|T_\zeta f\|_{L^2(S)}\leq A_2\|f\|_{L^2(S)}\quad\text{for all }f\in L^2(S)\text{ and }\Re\zeta=1,
\end{align*}
where $A_1$ and $A_2$ are positive constants independent of $\Im \zeta\in\R$. Then for every $\vartheta\in(0,1)$ the operator $T_\vartheta$ is bounded on $L^{q_\vartheta}$ with $1/q_\vartheta=1-\vartheta/2$ and
\begin{align*}
\|T_\vartheta f\|_{L^{q_\vartheta}(S)}\leq C\,A_1^{1-\vartheta} A_2^\vartheta\|f\|_{L^{q_\vartheta}(S)}\quad\text{for all }f\in L^2(S)\cap L^{q_\vartheta}(S).
\end{align*}
\end{lemma}
\begin{proof}
This follows from \cite[Theorem 5 (ii)]{MV} and \cite[Theorem 1]{CwJa}.
\end{proof}

\section{Proof of the main theorems}\label{sec3}
We prove our main theorems in this section, focusing on Theorem \ref{thm:main2}, since Theorem \ref{thm:main} follows from an interpolation argument. The proof of the necessity part of Theorem \ref{thm:main2} is a straightforward adaptation of the argument for the $ax+b$ group given in \cite{WaYa}, and will therefore be omitted. The sufficiency part of Theorem \ref{thm:main2} follows from the results below concerning the corresponding multipliers.

\begin{proposition}\label{prop: main}
Let $m$ be an even symbol. Then, for all $t\in\mathbb{R}^*$, the following results hold.
\begin{asparaenum}[\rm (a)]
\item If $m\in\cS^{-(n-1)/2}$, then
\begin{align*}
\|m(\sqrt{\L})\,\cos(t\sqrt{\L})\|_{\fh^1(S)\to L^1(S)}\lesssim 1+|t|.
\end{align*}

\item If $m\in\cS^{-(n-1)/2+1}$, then
\begin{align*}
\left\|m(\sqrt{\L})\,{\sin(t\sqrt{\L})\over\sqrt{\L}}\right\|_{\fh^1(S)\to L^1(S)}\lesssim 1+|t|. 
\end{align*}
\end{asparaenum}
\end{proposition}

The proof of Proposition \ref{prop: main} relies on the idea, originating from the critical case on Euclidean space, of relating the wave propagator to the spherical measure. See, for instance, \cite{Pe,Ta}. In our setting, the spherical measure is closely related to the spherical function given by \eqref{e2.10}, which therefore requires a detailed analysis. The following expression will be useful later on.

\begin{lemma}
Let $f$ be a suitable function on $S$. Then, for all $t>0$ and $z\in S$, we have
\begin{align}
\varphi_{\!\sqrt{\L}}(t)(f)(z)
={1\over\nu_n}\int_{\SS^{n-1}}\delta(x(t,\omega))^{-{1\over 2}} f(z\cdot x(t,\omega))\,\d \omega,\label{e4.1}
\end{align}

