 \end{cases}
 \end{equation}
 Then $u\in C^{s}(\Omega\cap B_{1/2})$ and 
 \[
 \norm{u}_{C^s(\Omega\cap B_{1/2})}\le C(\norm{g} _{L^\infty(\Omega\cap B_4)} + \norm{u} _{L^\infty(\Omega\cap B_4)} ),
 \]
 where $C$ depends on $n,s$ and $C^{1,1}_{loc}$ norm of $\partial\Omega$, and $B_r$ denotes a ball centered at any fixed point on the boundary $\partial\Omega$ with radius $r$.
\end{theorem}
The idea of the proof is that we divide the solution into two parts: the potential part and the harmonic part. The regularity for the potential part is obtained by Theorem \ref{otonserra}. For the harmonic part, we firstly derived an $\alpha$ power order decay near $\partial\Omega$, here $\alpha$ is a certain positive number which may be less than $s$. Combining the decay estimate and the interior regularity result (Theorem \ref{Holder thm}), we derive the $C^\alpha$ boundary regularity. Finally we refine the boundary regularity by an iteration progress.

To continue estimate $\norm{u}_{C^{\alpha_0}(\Omega\cap B_{1/2})}$, we need the interior H\"older estimate from \cite{chen2025refinedregularitynonlocalelliptic}.
\begin{proposition}[Interior H\"older regularity]\label{Holder thm}
 Assume $0<s<1$, and $u\in C^{1,1}_{loc}(\R^n)\cap \mathcal{L}_{2s}$ is a nonnegative solution of 
 \begin{equation}
 \flap u(x) = g(x),\quad x\in B_1
 \end{equation}
 where $g\in L^\infty(B_1)$. Then for any $0<\varepsilon <2s$,
 \begin{equation}
 \norm {u}_{C^{[2s-\varepsilon],\{2s-\varepsilon\}}(B_{1/2})}\le C(\norm{g}_{L^\infty(B_1)}+\norm{u}_{L^\infty(B_1)}).
 \end{equation}
\end{proposition}
Based on this, we arrive at
\begin{lemma}\label{global holder lemma}
 The decay estimate \eqref{decay estimate} and Proposition \ref{Holder thm} implies that 
 \begin{equation}
 \norm{u} _{C^{\alpha _0}(\Omega\cap B_{1/2})}\le C(\norm{u}_{L^\infty(\Omega\cap B_4)}+\norm{g}_{L^\infty(\Omega\cap B_4)})
 \end{equation}
 where $C$ depends on $s,n$, and $\norm{\partial \Omega}_{C^{1,1}_{loc}}$, $\alpha_0:=\min\{s,1-s\}\in (0,1/2)$. 
\end{lemma}

