\begin{proof}
Since $P(Y>y , X> x) = \bar{F}_0(x)\bar{F}_1\bigl(\beta(x)y\bigr)$ then $P(Y>y) = \lim_{x\to 0^+}P(Y>y , X> x) = \bar{F}_0(0)\bar{F}_1\bigl(\beta(0)y\bigr) = \bar{F}_1\bigl(\beta(0)y\bigr)$ since $\lim_{x\to 0^+}\bar{F}_0(x) = 1$ and $\beta(0): = \lim_{x\to 0^+} \beta(x)$. We note from Hoeffding's covariance identity:
\begin{align}
    Cov(X, Y) & = \int_0^\infty \int_0^\infty\left( P(Y>y , X> x) - P(X> x)P(Y> y)   \right) \ dx dy \nonumber \\
    & = \int_0^\infty \int_0^\infty  \bar{F}_0(x) \left( \bar{F}_1\bigl(\beta(x)y\bigr) - \bar{F}_1\bigl(\beta(0)y\bigr)  \right) \ dx dy.\nonumber 
\end{align}
Now since $\bar{F}_1'(\cdot)\le 0$ (as $\bar{F}_1$ is a survival function), if $\beta'(x) \geq 0$ then $\bar{F}_1\bigl(\beta(x)y\bigr) \leq \bar{F}_1\bigl(\beta(0)y\bigr)$ and $Cov(X, Y) \leq 0$ for $x, y \geq 0$. Conversely, if $\beta'(x) \leq 0$ then $\bar{F}_1\bigl(\beta(x)y\bigr) \geq \bar{F}_1\bigl(\beta(0)y\bigr)$ and $Cov(X, Y) \geq 0$ for $x, y \geq 0$. Finally, if $\beta(x)$ is constant, say $\beta(x)\equiv c$, then $P(X>x,Y>y)=\bar F_0(x)\,\bar F_1(cy)=P(X>x)\,P(Y>y)$, so $X$ and $Y$ are independent and ${Cov}(X,Y)=0$.
\end{proof}
Furthermore, as done in \citet{arnold2020bivariate}, we introduce a dependence parameter $\tau$ which controls the strength of the dependence between $X$ and $Y$. Extending from \eqref{eq: beta(x) general}, we define the acceleration function as such:
\begin{align}
    \beta(x) &= \gamma \frac{1}{\left[\bar{F}_0(\tau x)\right]^{c^*}}. \label{eq: beta(x) general 2}
\end{align}
