\begin{theorem}
\label{thm: ABC}
Let $h_0:(0,\infty)\to(0,\infty)$ be a hazard function. For $x>0$ and $\tau>0$ define:
\[
r(x,\tau):=\tau\,\frac{h_0(\tau x)}{h_0(x)},\qquad 
\phi(x):=x\,h_0(x).
\]
Let
\[
A:\ \ 0\le r(x,\tau)\le 1\ \ \text{for all }x>0,\qquad
B:\ \ \tau\in(0,1],\qquad
C:\ \ \phi \text{ is non-decreasing on }(0,\infty).
\]
Then:
\begin{enumerate}
\item[(1)] $(A \wedge B)\ \Rightarrow\ C$.
\item[(2)] $(C \wedge B)\ \Rightarrow\ A$.
\item[(3)] $(C \wedge A)\ \Rightarrow\ B$, \emph{unless} $\phi$ is identically constant on $(0,\infty)$, in which case $A$ holds for all $\tau>0$ and $B$ cannot be inferred.
\end{enumerate}

\end{theorem}

\begin{proof}
\textbf{(1) $(A \wedge B)\Rightarrow C$.}
Fix $0<y<x$ and set $\tau:=y/x\in(0,1]$ so that $B$ holds. By $A$,
\[
1 \ \ge\ r(x,\tau)=\tau\,\frac{h_0(\tau x)}{h_0(x)}=\frac{y\,h_0(y)}{x\,h_0(x)}.
\]
Hence $y\,h_0(y)\le x\,h_0(x)$ for all $0<y<x$, i.e.\ $\phi$ is non-decreasing. Thus $C$ holds.

\medskip
\textbf{(2) $(C \wedge B)\Rightarrow A$.}
Assume $C$ and $\tau\in(0,1]$. Then $\tau x\le x$ and, by the non-decreasing nature of $\phi$,
\[
\phi(\tau x)\le \phi(x)\ \Longleftrightarrow\ \tau x\,h_0(\tau x)\le x\,h_0(x)
\ \Longleftrightarrow\ r(x,\tau)\le 1.
\]
Since $h_0>0$, we also have $r(x,\tau)\ge 0$. Hence $A$ holds.

\medskip
\textbf{(3) $(C \wedge A)\Rightarrow B$, unless $\phi$ is constant.} 
Assume $C$ and $A$ hold. Because $h_0(x)>0$, the lower bound $r(x,\tau)\ge 0$ implies $\tau \ge 0$. Now suppose, toward a contradiction, that $\tau>1$, then $\tau x > x$ and, by assuming $\phi$ is now strictly increasing:
\[
\phi(\tau x) > \phi(x)\ \Longleftrightarrow\ \tau x\,h_0(\tau x) > x\,h_0(x)
\ \Longleftrightarrow\ r(x,\tau) > 1.
\]
contradicting the upper bound. Hence $\tau \le 1$. If instead $\phi$ is identically constant,
say $\phi(x)\equiv K>0$, then $h_0(x)=K/x$ and
\[
r(x,\tau)=\tau\,\frac{K/(\tau x)}{K/x}=1 \quad (\forall x>0,\ \forall \tau>0),
\]
so $A$ holds for all $\tau>0$ and no restriction $B$ follows.
\end{proof}
\begin{remark} When convenient, extend $B$ to $\tau\in[0,1]$ by defining $r(x,0):=\lim_{\tau\to 0^+} r(x,\tau)=0$ (whenever the limit exists). All implications above then carry over with this convention.
\end{remark}
\begin{remark}
If $h_0$ is non-decreasing, then $\phi(x) =  x h_0(x)$ is non-decreasing (product of increasing, positive functions), so Theorem~\ref{thm: ABC} recovers Theorem \ref{thm: ifr hazard}.
If $h_0(x)=C\,x^{p-1}g(x)$ with $C>0$, $p\ge 0$, and $g(x)$ non-decreasing, then $\phi(x) = C x^pg(x)$ is non-decreasing, so Theorem \ref{thm: ABC} recovers Theorem \ref{thm: factor hazard}.
