\begin{equation}\begin{aligned}\label{def:DC}
    \omega\in \mathrm{DC}:=&\bigcup_{a>0, A>1} \mathrm{DC}_{a,A}, \text{ where}\\
    \mathrm{DC}_{a,A}=&\left\{\omega\in \mathbb T:\, \|k\omega\|_{\mathbb T}\geq \frac{a}{|k|^A}\, \text{ for all } k\in \mathbb Z\setminus \{0\}\right\}.
\end{aligned}  
\end{equation}
We further assume that $B,V\in C^{\omega}(\T_{\delta}, \mathrm{Mat}(d,\mathbb C))$ are analytic, where $$\T_{\delta}:=\{\theta+i\varepsilon:\, \theta\in \mathbb T,\, \varepsilon\in \mathbb R,  \text{ and } |\varepsilon|\leq \delta\}$$with some positive $\delta>0$. 
We assume throughout the paper that $V$ is Hermitian, and that~$B$ is invertible ($\det B(\theta)\neq 0$ for any $\theta\in \T_{\delta}$). 
The difference equation $H_{\omega,\theta} \Phi=E\Phi$ is equivalent to the cocycle 
\begin{align}\label{def:M_E}
  \mathcal{C} &\::  (\theta,\Psi)\in \mathbb T\times \mathbb C^{2d}\mapsto (\theta+\omega, M_E(\theta)\Psi), \notag  \\
  \quad M_{E}(\theta) &= \left [ \begin{matrix}
   ( E-V(\theta))B(\theta)^{-1}  & -B^{(*)}(\theta) \\
  B(\theta)^{-1} & 0 
\end{matrix}\right]  
\end{align}
in the sense that for $n\ge1$, 
\begin{equation}\label{eq:MnE}
\mathcal{C}^n (\theta,\Psi)=(\theta+n\omega, M_{n,E}(\theta)\Psi), \quad M_{n,E}(\theta)=\prod_{j=n-1}^0 M_E(\theta+j\omega), \quad 
\Psi_n:=\binom{B_{n}\Phi_n}{\Phi_{n-1}}
\end{equation} 
satisfies $\Psi_n = M_{n,E} (\theta) \Psi_0$.  The model~\eqref{eq:BVsys} was studied systematically by S.~Klein~\cite{SK_block}, and Duarte and Klein~\cites{DK1, DK2} within a very general framework, including the identically singular case when $\det B(\theta)\equiv 0$ on $\mathbb T^k$, $k\geq 1$. These models generalize the quasi-periodic Schr\"odinger Hamiltonians on a strip considered by Bourgain and Jitomirskaya~\cite{BJ}, who proved localization perturbatively for large disorder. 

Since $M_E(\theta)$ is (complex) symplectic, see \eqref{def:symp}, for $\theta\in \mathbb T$, the Lyapunov exponents $\{L_j(\omega,M_E)\}_{j=1}^{2d}$, see definition in \eqref{def:LE}, satisfy $L_{2d+1-j}=-L_j$ for $1\le j\le d$. 
Let $L^d(\omega,M_E)$ be the sum of the top $d$ Lyapunov exponents, and let $\kappa^d(\omega,M_E)$ be the acceleration, defined to be the right-derivative of $L^d(\omega,M_E(\cdot+i\varepsilon))$ in the imaginary direction $\varepsilon$, see \eqref{eq:acc}.

Throughout the paper we shall fix an energy $E_0\in \mathbb R$ such that $L_d(\omega,E_0)\geq \tau>0$. It is known, see \cite{AJS}, that $L^d(\omega,M_E(\cdot+i\varepsilon))$ and $L_d(\omega,M_E)$ are continuous in $E,\varepsilon$ and $\kappa^d(\omega,M_E)$ is upper semi-continuous in $E,\varepsilon$, hence we can assume that in a neighborhood $I_{E_0}$ of $E_0$, the following holds uniformly in $E\in I_{E_0}$ and $|\varepsilon|\leq \delta$, $\varepsilon\in \mathbb R$, for some $\delta=\delta(E_0)>0$:
\begin{align}\label{def:IE0}
\begin{cases}
L_d(\omega,M_E(\cdot+i\varepsilon))\geq \tau/2,\\
\kappa^d(\omega,M_E(\cdot+i\varepsilon))\leq \kappa^d(\omega,M_{E_0})\\
L^d(\omega,M_E(\cdot+i\varepsilon))\leq L^d(\omega,M_E)+2\pi \kappa^d(\omega,M_{E_0})\varepsilon.
\end{cases}
\end{align}
Note the third inequality is a corollary of the second one.

The density of states $\mathcal{N}(\omega,\cdot)$ is the limiting cumulative distribution function of the finite-volume eigenvalues.  
Let $H_{\omega,\theta}|_{\Lambda}$ be the restriction of $H_{\omega,\theta}$ to the interval $\Lambda=[a,b]\subset \mathbb Z$.
Let $\{E_{\Lambda,j}(\omega,\theta)\}_{j=1}^{|\Lambda|}$ be the eigenvalues of $H_{\omega,\theta}|_{\Lambda}$.
Consider
\begin{align}
    N_{\Lambda}(\omega,E,\theta):=\frac{1}{|\Lambda|}\sum_{j=1}^{|\Lambda|}\chi_{(-\infty,E)}(E_{\Lambda,j}(\omega,\theta)).
\end{align}
It is well-known that the weak-limit
\begin{align}
    \lim_{a\to-\infty, b\to \infty}\mathrm{d} N_{\Lambda}(\omega,E,\theta)=:\mathrm{d} \mathcal{N}(\omega,E).
\end{align}
exists and is independent of $\theta$. In this paper we prove the following result.

