&f_{0}(x,v)=f_{0}(x,v^{*}),\label{v2.6}\\
&v_{\bot}\Big[\nabla_{x}^{\bot}f_{0}(x,v^{*})+\nabla_{x}^{\bot}f_{0}(x,v)\Big]+2E_{\bot}(0,x)\nabla_{v}^{\bot}f_{0}(x,v)=0,\label{v2.7}
