 \item Assume that $b=ka,\ k\in \{7,8,10,11,12,13\}$ and $c \in \{c_1^+,c_2^{\pm}\}$. If the equation $P_l=Q_m$ has a solution $(l,m)$ (of Type $1$), then we have
$$
l \geq \frac{1}{12}\left(-2+\sqrt{4+3\sqrt{a}}
\right).$$ 
\end{enumerate}
\end{lemma}
\begin{proof}
 Proof follows \cite[Lemma 3.2]{glavni} and here we will demonstrate the proof of $1)$. From the recurrent sequence (\ref{sequence_s_nu}), we have $s \equiv 2,r\ (\bmod\ a)$. Also, $b=ka \equiv 0\ (\bmod\ a)$ and $c=c_{1}^{-}\equiv -2 r\ (\bmod\ a)$. Using the previous Lemma, with solutions in Type $1$, we get
 $$ 
- 4 r m^2\pm 4m\equiv \pm2rl\pmod{a},\quad \mbox{if}\quad s\equiv 2\pmod{a}
$$
and 
$$ 
\ - 4m^2\pm 2m\mp2l\equiv 0\pmod{\dfrac{a}{\gcd (a,r)}},\quad \mbox{if}\quad s\equiv r\pmod{a}.
$$
In the first case, we multiply the congruence by $r$ and since $r^2 \equiv 4\ (\bmod\ a)$ we have $r \equiv \pm2\ (\bmod\ a')$ for some $a'$ that divides $a$ and $a' \geq \sqrt{a}$. So we get
$$-16m^2\pm8m\mp8l \equiv 0\ (\bmod\ a').$$
Using $l\leq m$ it follows that
$$16m^2+16m \geq |-16m^2\pm8m\mp8l|\geq a'\geq \sqrt{a},$$
which implies
\begin{align}\label{1}
 m \geq \frac{1}{4}\left(-2 +\sqrt{4+\sqrt{a}} \right).\end{align}
In the second case, since $\gcd(a,r)\leq2$ and $l \leq m$, we have
$$4m^2+4m \geq |- 4m^2\pm 2m\mp2l|\geq\frac{a}{\gcd(a,r)}\geq\frac{a}{2},$$
which implies
\begin{align}\label{2}
 m \geq \frac{1}{4}\left(-2+\sqrt{4+2a}\right).
\end{align}
Combining (\ref{1}) and (\ref{2}) we obtain the desired inequality.
\end{proof}

