The Mayer transfer operator encodes geometric information about the modular surface, which is the quotient orbifold $\mathbf{M}$ obtained from considering the Poincaré upper half plane $\mathbb{H}:\{x+iy:x,y\in \mathbb{R}, y>0\}$ equipped with the usual Riemannian metric $ds^2=(dx^2+dy^2)/y^2$ and identifying points via equivalence relation $\mathbb{H}\ni z\sim (az+b)/(cz+d)$ for all $a,b,c,d\in\mathbb{Z}$ with $ad-bc=1$. Since $\mathcal{L}_{\beta}$ is a nuclear operator, the Fredholm determinants $\det(1-\mathcal{L}_{\beta})$ and $\det(1+\mathcal{L}_{\beta})$ are well-defined. These relate to Selberg Zeta function $Z(s)$ by the formula 
\begin{equation}\label{equation: zeta functions}
 Z(s)= \det(1-\mathcal{L}_s)(1+\mathcal{L}_s),
\end{equation}
see \cite{Mayer91}. 
The Selberg zeta function is closely connected with the spectral theory of the Laplace-Beltrami operator $\Delta:=-y^2(d^2/dx^2+d^2/dy^2)$ \cite{Iwaniec}. Equation \eqref{equation: Mayer transfer extended} is thus a way of connecting the spectral theory of $\Delta$ with that of $\mathcal{L}_\beta$. This connection has been elaborated upon by Lewis, Zagier, Mayer and Chang \cite{Lewis97,ZagierLewis,MayerChang96,MayerChang98}.

From a dynamical perspective, it is interesting to see to what extent the aforementioned spectral properties of $\mathcal{L}_s$ survive when we consider e.g. Hölder continuous functions instead. For $\alpha\in (0,1)$, let $C^\alpha([0,1])$ denote the space of $\alpha$-Hölder functions on $[0,1]$. If $\alpha = k+\eta$ with $k\in\mathbb{N}$ and $\eta\in [0,1)$, let $C^\alpha([0,1])$ be the set of functions for which the $k$-th derivative exists and is continuous or $\eta$-Hölder if $\eta=0$ or $\eta\in (0,1)$ respectively. Denote by $L_\beta$ the operator \eqref{equation: Mayer transfer extended2} acting on $C^\alpha([0,1])$, which we shall show to be well-defined and continuous for large enough $\alpha$. These operators are not compact, but we can decompose the spectrum $\sigma(L_\beta)$ into the essential spectrum $\sigma_e(L_\beta)$ and the discrete spectrum $\sigma_{\mathrm{disc}}(L_\beta)$ which consists of isolated eigenvalues of finite algebraic multiplicity. We prove the following.

\begin{equation}\label{equation: Mayer transfer extended}
    \mathcal{L}_{\beta}(f)(z)=f(0)\zeta_H(2\beta,z+1)+\sum_{n=1}^\infty \frac{1}{(n+z)^{2\beta}}(f^\star)\left(\frac{1}{n+z}\right),
\end{equation}

\begin{equation}\label{equation: Mayer transfer extended2}
    \mathcal{L}_{\beta}(f)(z)=\sum_{n=0}^k\frac{d^nf}{dz^n}(0)\frac{\zeta_H(n+2\beta,z+1)}{n!}+\sum_{n=1}^\infty \frac{1}{(n+z)^{2\beta}}(f^\star)\left(\frac{1}{n+z}\right),
\end{equation}

Many of the usual theorems in complex analysis continue to hold for Banach or topological vector space-valued functions. In particular, holomorphic implies infinitely differentiable with a locally converging Taylor expansion. The unique extension theorem also continues to hold.
Finally, note that it is straightforward to show that $\beta\to L_\beta$ is a meromorphic function on $\Re(\beta)>(1-\alpha)/2$ for any $\alpha\in\mathbb{R}_{>0}$ with derivative 
\[ \left(\frac{d L_\beta}{d\beta}\right)(f)(z)= -\sum_{n=0}^k(n+2\beta)\frac{d^nf}{dz^n}(0)\frac{\zeta_H(n+2\beta+1,z+1)}{n!} -2 \sum_{n=1}^\infty \frac{\ln(n+z)}{(n+z)^{2\beta}}(f^\star)\left(\frac{1}{n+z}\right).\]
\section{Uniformly Bounded Essential Spectrum}\label{section: uniformly bounded essential spectrum}
By \eqref{equation: Nussbaum}, we can estimate the essential spectral radius by finding for each $l\in \mathbb{N}$ a compact operator $T'$ for which $\|L_\beta^l - T' \|$ is small. A first naive approach would be to consider the operator $P$ which sends $f$ to a piecwise linear approximation that interpolates $f$ on the points $0,\frac{1}{N},\frac{2}{N},\cdots,1$ and considering $\|L_\beta^l-L_\beta^l\circ P\|$ as $N\to \infty$. For $\Re(\beta)>0$, we indeed have by Lemma \ref{lemma: mayer operator inequalities} that for any $\varepsilon>0$ there exists some $N$ for which $\lvert (L_\beta-L_\beta\circ P) (f)\rvert_\alpha(x)\leq \mathfrak{L}_{\Re(\beta)+\alpha}((1+\varepsilon)|f-P(f)|_\alpha)(x)+\varepsilon$. However, we do not have sufficient control over the $\|\cdot\|_\infty$-norm. We remedy this by considering a \textit{countable} interpolation which ensures $(L_\beta^l\circ P)f$ remains a (nonlinear) interpolation of
$L_\beta^l f$.

Let us now prove most of Theorem \ref{theorem: radius of essential spectrum}. 
\begin{theorem}\label{theorem: spectral theorem}
Let $0<\alpha<1 $. Then for all $\beta$ with $\Re(\beta)>(1-\alpha)/2$ the transfer operator $L_\beta$ satisfies 
\[\rho_e(L_\beta) \leq \rho(\mathfrak{L}_{\Re(\beta)+\alpha}).\]
\end{theorem}
\begin{proof}
 By Nussbaum's formula and Proposition \ref{proposition: compact operator}, it suffices to prove that there is some constant $C''>0$ for which \[\limsup_{N\to\infty} \|L_{\beta}^l -L_{\beta}^l \circ P_{l,N} \| \leq C''\left\|\mathfrak{L}_{\Re(\beta)+\alpha}^l\right\| \text{ for all } l.\]

\end{proof}
\begin{remark}\label{remark: spectral radius}
By using the spectral radius formula $\rho(\mathfrak{L}_{\Re(\beta)+\alpha})=\limsup_{l\to\infty}\|\mathfrak{L}_{\Re(\beta)+\alpha}^l\|^{1/l}$ and bounding every function $f\in L^\infty([0,1])$ by a constant, we obtain that $\rho(\mathfrak{L}_{\Re(\beta)+\alpha})\leq \rho(\mathcal{L}_{\Re(\beta)+\alpha})$ and hence that 
\[\rho(\mathfrak{L}_{\Re(\beta)+\alpha}) = \lambda_1(\Re(\beta)+\alpha),\]
where $\lambda_1(t)$ for $t>1/2$ is the eigenvalue of maximum modulus of $\mathcal{L}_{t}$. The eigenvalue is guaranteed to be simple and positive by the Perron-Frobenius theorem. In fact $\lambda_1(t)$ is a real-analytic and decreasing function of $t$ with $\lambda(1)=1$, see \cite{Mayer90,Vallee98}. 
\end{remark}
Theorem \ref{theorem: radius of essential spectrum} for $\alpha \in (0,1)$ then follows from Remark \ref{remark: spectral radius} and from the following corollary of Theorem \ref{theorem: spectral theorem}.
\begin{corollary}\label{Corollary: Ruelle}
 Let $\lambda \in \mathbb{C}$ satisfy $\abs{\lambda}>\rho(\mathfrak{L}_{\Re(\beta)+\alpha})$. Then $\lambda$ is an eigenvalue of $L_\beta$ if and only if it is an eigenvalue of $\mathcal{L}_\beta$. In this case the respective eigenspaces $E_\lambda^\alpha$ and $E_\lambda^\omega$ are equal. 
\end{corollary}
This is an example of a more general principle for operators on Banach spaces, see e.g. \cite{Grabiner}. For our purposes, we may directly adapt a proof due to Ruelle (Corollary 3.3 in \cite{Ruelle89}), which we provide in the appendix.

\end{proof}
We see by Proposition $4.1$ that a generic solution of \eqref{equation: three term functional} in $C^\alpha((-1,\infty))$ satisfies $f= O(z^{1-2\Re(\beta)})$ if $\Re(\beta)>(1-\alpha)/2$. On the other hand, we see that the condition $Q=0$ in \eqref{equation: Qinfinity} or in \eqref{equation: Q0} is equivalent to the condition $L_\beta f= \lambda f$, which by Theorem \ref{theorem: radius of essential spectrum} implies $f$ extends to a holomorphic function in $\mathbb{C}\setminus (-\infty,-1]$ if $\abs{\lambda}\leq \rho(\mathcal{L}_{\Re(\beta)+\alpha})$. For example, we have the following corollary of Proposition \ref{equation: proposition: }, which we can view as a stronger version of the Bootstrapping procedure by Lewis and Zagier in \cite{ZagierLewis}.
\begin{corollary}
 Let $\Re(\beta)=1/2$. Suppose $f:(-1,\infty)\to \mathbb{C}$ is some solution of \eqref{equation: three term functional} for $\abs{\lambda} = 1$. Assume furthermore it satisfies the mild growth condition $f(z)= C_0x^{1-2\beta}+o(1)$ as $z\to \infty$.
 Then if $f$ is $1/2+\varepsilon$-Hölder for some $\varepsilon>0$, it is automatically holomorphically extendable to the cut plane $\mathbb{C}\setminus (-\infty,-1]$.
\end{corollary}
This corollary immediately follows from Theorem \ref{theorem: radius of essential spectrum} and the fact that $\rho(\mathcal{L}_a)<1$ if $a>1$. We remark that when $\Re(\beta)=1/2$ and $\lambda =1$ or $-1$, the space of eigenvalues of $\mathcal{L}_{\beta}$ is in bijection with the space of even, respectively uneven Maass cusp forms on the modular surface with eigenvalue $\beta(1-\beta)$ and we have that $C_0=0$, i.e. $f(z)= o(1)$ as $z\to \infty$, see \cite{Lewis97, ZagierLewis}.

\begin{proposition}\label{Proposition: Constructing Q}
 Let $\alpha>0$, $\lambda\in\mathbb{C}\setminus\{0\}$ and let $Q\in C^\alpha(\mathbb{R}/\mathbb{Z})$.
 For all $\beta$ for which $\Re(\beta)> (1-\alpha)/2$ and \[r(\mathcal{L}_{\Re(\beta)+\alpha})< \abs{\lambda},\]
 the function
 \[f=(1 - \lambda^{-1}L_\beta)^{-1}Q,\]
 is a meromorphic expression over all $\beta$ satisfying the conditions in this proposition. Furthermore $f$ satisfies \eqref{equation: three term functional}, \eqref{equation: Qinfinity} and \eqref{equation: Q0}.
\end{proposition}
\begin{proof}
 We interpret $(\lambda - L_\beta)^{-1}$ in the sense of Remark \ref{remark: extending L_beta}. More specifically, for $L_\beta$ acting on $ C^r([a,(1-a)^{-1}])$, the expression $(1 - \lambda^{-1}L_\beta)^{-1}\left(\rstr{Q}{[a,(1-a)^{-1}]}\right)$ is meromorphic and satisfies 
\begin{equation}\label{equation: expansion for resolvent}
 \begin{split}
 &(1 - \lambda^{-1}L_\beta)^{-1}\left(\rstr{Q}{[a,(1-a)^{-1}]}\right)(z)=\sum_{n=0}^\infty \lambda^{-n}L_\beta^n\left(\rstr{Q}{[a,(1-a)^{-1}]}\right)(z).\\
 &= Q(z)+\sum_{n=1}^\infty \lambda^{-n}\sum_{a_1,\ldots,a_n\in\mathbb{N}} Q([a_1,\ldots,a_n+z])\Pi_{k=1}^n[a_k,\ldots,a_n+z]^{2\beta}
 \end{split}
\end{equation}
if $\Re(\beta)$ is large enough. By Theorem \ref{theorem: radius of essential spectrum}, we see that $(1 - \lambda^{-1}L_\beta)^{-1}$ is a meromorphic operator-valued function for all $a\leq1$. Hence the functions $(1 - \lambda^{-1}L_\beta)^{-1}\left(\rstr{Q}{[a,(1-a)^{-1}]}\right)$ are 
meromorphic functions over the half-plane consisting of all $\beta$ satisfying the conditions in the proposition. We see by the second line of \eqref{equation: expansion for resolvent} and uniqueness of analytic continuation that these functions agree for different $a$ on the intersection of their domains. Hence we may define $(1 - \lambda^{-1}L_\beta)^{-1}Q(z)$ for any $z\in (-1,\infty)$ by choosing $a$ in \eqref{equation: expansion for resolvent} small enough.

