\qquad \quad+k_4 e^{-\mu x_3}, \\[7pt]
X_3=  \frac{\sqrt{-\varepsilon \mu} }{\mu^2}   \left(k_1 e^{\sqrt{-\varepsilon \mu} x_1}-k_2 e^{-\sqrt{-\varepsilon \mu} x_1} \right) -\frac\mu2
