X_2=  \frac{1}{\mu^2}   \left( k_1(\mu\sqrt{\varepsilon\mu} x_2  \sin (\sqrt{\varepsilon \mu} x_1)+\varepsilon \cos (\sqrt{\varepsilon \mu} x_1))  \right. \\[3pt]
\qquad \;\; \quad \quad \left. -k_2(\mu\sqrt{\varepsilon\mu} x_2  \cos (\sqrt{\varepsilon \mu} x_1)-\varepsilon \sin (\sqrt{\varepsilon \mu} x_1)) \right) +k_4 e^{-\mu x_3}, \\[7pt]
