\quad\quad-\frac{x_3^3}{3!}(\mu^3 u_1+(\frac12x_2^2\mu^5+\mu^2\varepsilon)u_2)+\cdots\big)dx_1\\[5pt]
\quad=\big(e^{-x_3\mu}dx_1\big)u_1-\big((\frac{x_2^2}{2}\mu^2e^{x_3\mu}+\frac{\varepsilon}{\mu}\sinh(x_3\mu))dx_1\big)u_2+\big(x_2\mu dx_1\big)u_3,\\[15pt]
\exp(-x_3u_3)\exp(-x_2u_2)\cdot dx_2\cdot u_2 \exp(x_2u_2)\exp(x_3u_3)\\[5pt]
\quad=\exp(-x_3u_3)\cdot dx_2\cdot u_2\exp(x_3u_3)\\[5pt]
\quad=\big(u_2+x_3\mu u_2+\frac{x_3^2}{2!}\mu^2 u_2+\frac{x_3^2}{3!}\mu^3 u_2+\cdots\big)dx_2=\big(e^{x_3\mu}dx_2\big)u_2,\\[15pt]
\exp(-x_3u_3)\cdot dx_3\cdot u_3\exp(x_3u_3)=dx_3u_3.
\end{array}
$$
From the above equations we then explictly get the basis $\{ \theta_i \}$ of $1$-forms dual to the pseudo-orthonormal basis $\{u_i \}$ used in \eqref{glie} in local coordinates, that is,
$$
\left\{\begin{array}{l}
\theta_1=e^{-\mu x_3}dx_1,\\[5pt]
\theta_2={-\frac{1}{2\mu} \left( (\mu^3 {x_2^2}+\varepsilon ) e^{\mu x_3} -\e e^{-\mu x_3})\right)dx_1}+e^{\mu x_3}dx_2,\\[5pt]
\theta_3=x_2\mu dx_1+dx_3.
\end{array}
\right.
$$
Consequently, we obtain the following explicit form of the pseudo-orthonormal basis $\{u_i \}$ with respect to the coordinate system $(x_1,x_2,x_3)$:
\begin{equation}\label{ui}
\left\{\begin{array}{l}
u_1=e^{\mu x_3} \pa1+{\frac{1}{2\mu} \left((\mu^3 {x_2^2}+\varepsilon ) e^{\mu x_3} -\e e^{-\mu x_3})\right)\pa2}
-\mu x_2 e^{\mu x_3} \pa3,\\[5pt]
u_2=e^{-\mu x_3} \pa2,\\[5pt]
u_3=\pa3.
\end{array}
\right.
\end{equation}
It is easy to check that the vector fields described by \eqref{ui} satisfy the bracket relations \eqref{lie}. The explicit form \eqref{g} of the left-invariant Lorentzian metric is then obtained applying \eqref{glie} to the explicit expressions \eqref{ui} of the basis of the Lie algebra (equivalently, substituting the explicit forms of $\theta _i$ into $g=\theta_1\theta_2+\theta_3^2$).

