G_1 (x_1) = c_1 , \qquad \lambda = -\frac 12 \mu^2 <0,
\end{array}
\end{equation}
for some real constant $c_1$. Consequently, equation \eqref{third} reduces to
\begin{equation}\label{third1}
\begin{array}{l}
\mu F_2(x_1,x_3)+\pa3 F_2(x_1,x_3) +H'_3 (x_1) +\e (e^{-\mu x_3}-e^{\mu x_3}) c_1=0,
