 \end{equation}
where $\mu_1, \mu_2$ are roots of \eqref{eq:algebraicHardy} as in Theorem \ref{thm:asymptEst}, and $0 < R_0< 1 < R_1$ are constants depending on $n, p, \gamma,\nu, \alpha,\beta$, $u$ and $v$.
\end{thm}

\begin{thm}\label{stimagradiente2}
